def exact_joined_fields(value, fields, label):
    expected = set(fields)
    if not isinstance(value, dict) or set(value) != expected:
        raise ValueError("joined %s has invalid fields" % label)
    allowed = JOINED_OBJECT_ORDERS.get(frozenset(expected))
    if allowed is not None and tuple(value) not in allowed:
        raise ValueError("joined %s has noncanonical field order" % label)
    return value


def valid_joined_string(value, label, allow_empty=False, maximum=4096):
    if not isinstance(value, str) or len(value) > maximum or (not allow_empty and not value) or any(ord(ch) < 32 for ch in value):
        raise ValueError("joined %s has invalid string" % label)
    return value


def valid_joined_reason(value, label, allow_empty=False):
    if value == "" and allow_empty:
        return value
    if not isinstance(value, str) or JOINED_REASON.fullmatch(value) is None:
        raise ValueError("joined %s has invalid reason" % label)
    return value


def valid_joined_date(value, label="local_date"):
    try:
        if not isinstance(value, str) or datetime.date.fromisoformat(value).isoformat() != value:
            raise ValueError
    except ValueError as exc:
        raise ValueError("joined %s is invalid" % label) from exc
    return value


def joined_canonical_bytes(value):
    raw = json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    return (
        raw.replace("&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e")
        .replace("\u2028", "\\u2028").replace("\u2029", "\\u2029").encode("utf-8")
    )


def joined_canonical_sha(value):
    return hashlib.sha256(joined_canonical_bytes(value)).hexdigest()


def decode_joined_json(content):
    def pairs(values):
        keys = tuple(key for key, _value in values)
        allowed = JOINED_OBJECT_ORDERS.get(frozenset(keys))
        if (allowed is not None and keys not in allowed) or (allowed is None and keys != tuple(sorted(keys))):
            raise ValueError("joined JSON object has noncanonical field order")
        out = {}
        for key, value in values:
            if key in out:
                raise ValueError("joined JSON contains a duplicate field")
            out[key] = value
        return out
    def finite_float(raw):
        value = float(raw)
        if not math.isfinite(value):
            raise ValueError("joined JSON contains a non-finite number")
        return value
    try:
        payload = json.loads(
            content.decode("utf-8"), object_pairs_hook=pairs,
            parse_float=finite_float,
            parse_constant=lambda _value: (_ for _ in ()).throw(ValueError("joined JSON contains a non-finite number")),
        )
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError("joined JSON artifact is not valid UTF-8 JSON") from exc
    if content != joined_canonical_bytes(payload):
        raise ValueError("joined JSON artifact is not canonical")
    return payload


def joined_timestamp_nanoseconds(value, label):
    parsed = valid_joined_timestamp(value, label)
    match = re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(?:\.([0-9]{1,9}))?(?:Z|[+-][0-9]{2}:[0-9]{2})", value)
    if match is None:
        raise ValueError("joined manifest has invalid %s" % label)
    fraction = int((match.group(1) or "").ljust(9, "0"))
    whole = parsed.astimezone(datetime.timezone.utc).replace(microsecond=0) - datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
    return (whole.days * 86400 + whole.seconds) * 1_000_000_000 + fraction


def joined_timestamp_is_go_zero(parsed):
    try:
        return parsed.astimezone(datetime.timezone.utc) == datetime.datetime(1, 1, 1, tzinfo=datetime.timezone.utc)
    except OverflowError:
        return False


def source_claim_projection(source):
    projected = {key: source[key] for key in (
        "clip_id", "recording_id", "recording_job_id", "storage_destination_id", "provider", "endpoint", "region", "bucket",
        "start_utc", "end_utc", "released_at", "object",
    )}
    projected["seam_to_previous"] = {"verdict": "", "reason": "", "signed_gap_nanoseconds": 0}
    return projected


def source_claim_sha(sources):
    # Go's empty source-only slice is nil and therefore serializes as null.
    return joined_canonical_sha([source_claim_projection(source) for source in sources] if sources else None)


def candidate_source_claim_sha(sources):
    return joined_canonical_sha([
        {"clip_id": source["clip_id"], "source_claim_sha256": source_claim_sha([source])}
        for source in sources
    ])


def frozen_source_sha(sources, qualification_day, recording_id):
    window_start = joined_timestamp_nanoseconds(qualification_day["window_start"], "qualification window_start")
    window_end = joined_timestamp_nanoseconds(qualification_day["window_end"], "qualification window_end")
    snapshots = []
    seen_clips, seen_locators = set(), set()
    for source in sources:
        clip_id = valid_source(source, recording_id, source_only=True)
        locator = (source["storage_destination_id"],) + tuple(source[key] for key in ("provider", "endpoint", "region", "bucket")) + (source["object"]["key"],)
        start_ns = joined_timestamp_nanoseconds(source["start_utc"], "source start_utc")
        end_ns = joined_timestamp_nanoseconds(source["end_utc"], "source end_utc")
        if (
            clip_id in seen_clips or locator in seen_locators
            or source["recording_job_id"] != qualification_day["job_id"]
            or end_ns <= window_start or start_ns >= window_end
        ):
            raise ValueError("joined frozen source identity conflicts")
        seen_clips.add(clip_id)
        seen_locators.add(locator)
        snapshots.append({
            "clip_id": clip_id,
            "recording_id": source["recording_id"],
            "recording_job_id": source["recording_job_id"],
            "storage_destination_id": source["storage_destination_id"],
            "provider": source["provider"],
            "endpoint": source["endpoint"],
            "region": source["region"],
            "bucket": source["bucket"],
            "object_key": source["object"]["key"],
            "start_utc": source["start_utc"],
            "end_utc": source["end_utc"],
            "size_bytes": source["object"]["size_bytes"],
            "ingest_sha256": source["object"]["sha256"],
            # V2 retains released_at in the ledger for audit, but it is mutable
            # transfer bookkeeping and is not part of denominator identity.
            "released_at": None,
        })
    return joined_canonical_sha(snapshots)


def valid_qualification_day(day, recording_id, timezone, local_date):
    fields = set(day) if isinstance(day, dict) else set()
    historical = fields == set(HISTORICAL_QUALIFICATION_FIELDS)
    if fields not in (set(QUALIFICATION_FIELDS), set(HISTORICAL_QUALIFICATION_FIELDS)):
        raise ValueError("qualification day has invalid fields")
    if (
        day["local_date"] != valid_joined_date(local_date)
        or not 1 <= positive_joined_int(day["qualification_window_ordinal"], "qualification_window_ordinal") <= 14
        or positive_joined_int(day["job_id"], "job_id") < 1
    ):
        raise ValueError("joined qualification day identity conflicts")
    try:
        location = ZoneInfo(valid_joined_string(timezone, "timezone", maximum=255))
    except ZoneInfoNotFoundError as exc:
        raise ValueError("joined timezone is invalid") from exc
    start_ns = joined_timestamp_nanoseconds(day["window_start"], "qualification window_start")
    end_ns = joined_timestamp_nanoseconds(day["window_end"], "qualification window_end")
    completed_ns = joined_timestamp_nanoseconds(day["completed_at"], "qualification completed_at")
    if (
        end_ns - start_ns != 12 * 3_600_000_000_000
        or start_ns != local_boundary_nanoseconds(local_date, location, 8)
        or end_ns != local_boundary_nanoseconds(local_date, location, 20)
    ):
        raise ValueError("joined qualification day is invalid")
    if not historical:
        if completed_ns < end_ns:
            raise ValueError("joined qualification day is incomplete")
        return
    scheduled_ns = joined_timestamp_nanoseconds(day["scheduled_for"], "qualification scheduled_for")
    status = day["job_status"]
    reasons = []
    if scheduled_ns != start_ns:
        reasons.append("scheduled_for_drift")
    if status == "error":
        reasons.append("terminal_job_error")
        allowed_error = (recording_id == 348 and local_date == "2026-07-29") or (
            recording_id in (408, 406, 409) and local_date == "2026-08-11"
        )
        if not allowed_error:
            raise ValueError("joined historical error day conflicts")
    elif status != "done" or completed_ns < end_ns:
        raise ValueError("joined historical qualification status conflicts")
    if completed_ns < start_ns or day["reason_codes"] != reasons:
        raise ValueError("joined historical qualification reason conflicts")


def valid_media_tool(tool):
    exact_joined_fields(tool, MEDIA_TOOL_FIELDS, "media tool")
    valid_joined_string(tool["ffmpeg_version"], "ffmpeg_version")
    valid_joined_string(tool["ffprobe_version"], "ffprobe_version")
    valid_sha256(tool["ffmpeg_sha256"], "ffmpeg")
    valid_sha256(tool["ffprobe_sha256"], "ffprobe")
    identity = valid_sha256(tool["identity_sha256"], "media tool")
    unsealed = dict(tool)
    unsealed["identity_sha256"] = ""
    if joined_canonical_sha(unsealed) != identity:
        raise ValueError("joined media tool identity conflicts")


def valid_source(source, recording_id, source_only=False, location=None, local_date=None):
    fields = set(SOURCE_FIELDS)
    if not isinstance(source, dict) or set(source) not in (fields, fields | {"audio_sequence_contract"}):
        raise ValueError("joined source has invalid fields")
    clip_id = positive_joined_int(source["clip_id"], "clip_id")
    if source["recording_id"] != recording_id:
        raise ValueError("joined source recording identity conflicts")
    positive_joined_int(source["recording_job_id"], "recording_job_id")
    positive_joined_int(source["storage_destination_id"], "storage_destination_id")
    if source["provider"] not in ("r2", "r2_managed") or source["region"] != "auto" or not isinstance(source["bucket"], str) or re.fullmatch(r"[a-z0-9][a-z0-9-]{0,62}", source["bucket"]) is None:
        raise ValueError("joined source storage identity is invalid")
    endpoint = source["endpoint"]
    if not isinstance(endpoint, str) or SOURCE_ENDPOINT_V1.fullmatch(endpoint) is None:
        raise ValueError("joined source endpoint is not a canonical HTTPS authority")
    start = valid_joined_timestamp(source["start_utc"], "source start_utc")
    end = valid_joined_timestamp(source["end_utc"], "source end_utc")
    start_ns = joined_timestamp_nanoseconds(source["start_utc"], "source start_utc")
    end_ns = joined_timestamp_nanoseconds(source["end_utc"], "source end_utc")
    if end_ns <= start_ns or end_ns - start_ns > 15 * 60 * 1_000_000_000:
        raise ValueError("joined source range is invalid")
    if source["released_at"] is not None:
        released_at = valid_joined_timestamp(source["released_at"], "source released_at")
        if joined_timestamp_is_go_zero(released_at):
            raise ValueError("joined source released_at is zero")
    if location is not None and local_date is not None and (start.astimezone(location).date().isoformat() != local_date or end.astimezone(location).date().isoformat() != local_date):
        raise ValueError("joined source local date conflicts")
    object_fields = set(OBJECT_FIELDS)
    if isinstance(source["object"], dict) and "version_id" in source["object"]:
        object_fields.add("version_id")
    exact_joined_fields(source["object"], object_fields, "source object")
    key = valid_joined_string(source["object"]["key"], "source object key")
    if key in (".", "..") or key.startswith("/") or posixpath.normpath(key) != key or "\\" in key or "\0" in key:
        raise ValueError("joined source object key is unsafe")
    etag = source["object"]["etag"]
    if not isinstance(etag, str) or not 1 <= len(etag) <= 256 or etag.startswith("W/") or '"' in etag or any(not 0x21 <= ord(ch) <= 0x7e for ch in etag):
        raise ValueError("joined source object ETag is invalid")
    if "version_id" in source["object"]:
        version_id = source["object"]["version_id"]
        if not isinstance(version_id, str) or not 1 <= len(version_id) <= 1024 or any(not 0x21 <= ord(ch) <= 0x7e for ch in version_id):
            raise ValueError("joined source object version_id is invalid")
    positive_joined_int(source["object"]["size_bytes"], "source object size_bytes")
    valid_sha256(source["object"]["sha256"], "source object")
    exact_joined_fields(source["seam_to_previous"], SEAM_FIELDS, "source seam")
    if source_only:
        if "audio_sequence_contract" in source or source["seam_to_previous"] != {"verdict": "", "reason": "", "signed_gap_nanoseconds": 0}:
            raise ValueError("joined source-only claim contains derived evidence")
    else:
        valid_joined_string(source["seam_to_previous"]["verdict"], "source seam verdict", allow_empty=True)
        valid_joined_string(source["seam_to_previous"]["reason"], "source seam reason", allow_empty=True)
        valid_joined_int64(source["seam_to_previous"]["signed_gap_nanoseconds"], "source seam gap")
        if "audio_sequence_contract" in source:
            valid_audio_contract(source["audio_sequence_contract"])
    return clip_id


def valid_derived_source_seams(sources):
    empty = {"verdict": "", "reason": "", "signed_gap_nanoseconds": 0}
    if sources and sources[0]["seam_to_previous"] != empty:
        raise ValueError("joined first source has prior-seam evidence")
    for previous, following in zip(sources, sources[1:]):
        seam = following["seam_to_previous"]
        signed_gap = joined_timestamp_nanoseconds(following["start_utc"], "seam next start") - joined_timestamp_nanoseconds(previous["end_utc"], "seam previous end")
        valid_joined_reason(seam["reason"], "source seam reason")
        valid = (
            (seam["verdict"] == "continuous" and signed_gap == 0)
            or (seam["verdict"] == "gap" and signed_gap > 0)
            or (seam["verdict"] == "overlap" and signed_gap < 0)
            or seam["verdict"] == "incompatible"
        )
        if not valid or seam["signed_gap_nanoseconds"] != signed_gap:
            raise ValueError("joined derived source seam conflicts")


def valid_boundary(boundary, cross_day=False):
    exact_joined_fields(boundary, CROSS_DAY_FIELDS if cross_day else CROSS_HOUR_FIELDS, "boundary")
    if not cross_day:
        previous = positive_joined_int(boundary["previous_delivery_hour"], "previous_delivery_hour")
        following = positive_joined_int(boundary["next_delivery_hour"], "next_delivery_hour")
        if following != previous + 1 or following > 12:
            raise ValueError("joined boundary hour identity conflicts")
        valid_joined_timestamp(boundary["scheduled_utc"], "boundary scheduled_utc")
    else:
        valid_joined_timestamp(boundary["scheduled_previous_end_utc"], "boundary scheduled_previous_end_utc")
        valid_joined_timestamp(boundary["scheduled_next_start_utc"], "boundary scheduled_next_start_utc")
    pairs = (
        ("previous_clip_id", "previous_presentation_end_utc"),
        ("next_clip_id", "next_presentation_start_utc"),
    )
    present = []
    for id_key, time_key in pairs:
        clip_id, timestamp = boundary[id_key], boundary[time_key]
        if (clip_id is None) != (timestamp is None):
            raise ValueError("joined boundary has partial source identity")
        if clip_id is not None:
            positive_joined_int(clip_id, id_key)
            valid_joined_timestamp(timestamp, time_key)
            present.append(True)
        else:
            present.append(False)
    signed_gap = boundary["signed_gap_nanoseconds"]
    if (signed_gap is None) != (not all(present)) or (signed_gap is not None and (isinstance(signed_gap, bool) or not isinstance(signed_gap, int))):
        raise ValueError("joined boundary has invalid signed gap")
    if signed_gap is not None:
        valid_joined_int64(signed_gap, "boundary signed gap")
        want_gap = joined_timestamp_nanoseconds(boundary["next_presentation_start_utc"], "boundary next start") - joined_timestamp_nanoseconds(boundary["previous_presentation_end_utc"], "boundary previous end")
        if signed_gap != want_gap:
            raise ValueError("joined boundary signed gap conflicts")
    actual = None if cross_day else boundary["actual_seam_utc"]
    skew = boundary["boundary_skew_nanoseconds"]
    if actual is not None:
        valid_joined_timestamp(actual, "boundary actual_seam_utc")
    if skew is not None:
        valid_joined_int64(skew, "boundary skew")
    valid_joined_reason(boundary["allocation_decision"], "boundary allocation_decision")
    valid_joined_reason(boundary["verdict"], "boundary verdict")
    valid_joined_reason(boundary["reason"], "boundary reason")


def local_boundary_nanoseconds(local_date, location, hour, day_delta=0):
    day = datetime.date.fromisoformat(local_date) + datetime.timedelta(days=day_delta)
    value = datetime.datetime(day.year, day.month, day.day, hour, tzinfo=location)
    epoch = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
    utc = value.astimezone(datetime.timezone.utc)
    delta = utc - epoch
    return (delta.days * 86400 + delta.seconds) * 1_000_000_000


def validate_cross_hour_boundaries(payload, location, local_date):
    sources = payload["sources"]
    minimum = consumed = 0
    for index, boundary in enumerate(payload["cross_hour_boundaries"]):
        consumed += len(payload["hours"][index]["source_clip_ids"])
        scheduled_ns = local_boundary_nanoseconds(local_date, location, 9 + index)
        if joined_timestamp_nanoseconds(boundary["scheduled_utc"], "boundary scheduled_utc") != scheduled_ns:
            raise ValueError("joined allocation ledger boundary schedule conflicts")
        if not sources:
            if boundary != {
                "previous_delivery_hour": index + 1, "next_delivery_hour": index + 2,
                "previous_clip_id": None, "next_clip_id": None,
                "previous_presentation_end_utc": None, "next_presentation_start_utc": None,
                "signed_gap_nanoseconds": None, "scheduled_utc": boundary["scheduled_utc"],
                "actual_seam_utc": None, "boundary_skew_nanoseconds": None,
                "allocation_decision": "no_sources", "verdict": "absent_source",
                "reason": "both_sources_absent",
            }:
                raise ValueError("joined source-free boundary conflicts")
            continue
        candidates = []
        for position in range(minimum, len(sources) + 1):
            if position:
                source = sources[position - 1]
                at_ns = joined_timestamp_nanoseconds(source["end_utc"], "source end")
                candidates.append((abs(at_ns - scheduled_ns), at_ns, position, source["clip_id"], source["end_utc"]))
            if position < len(sources):
                source = sources[position]
                at_ns = joined_timestamp_nanoseconds(source["start_utc"], "source start")
                candidates.append((abs(at_ns - scheduled_ns), at_ns, position, source["clip_id"], source["start_utc"]))
        _, best_ns, best_position, _, best_at = min(candidates)
        if consumed != best_position:
            raise ValueError("joined allocation ledger is not assigned at the closest frozen seam")
        previous = sources[best_position - 1] if best_position else None
        following = sources[best_position] if best_position < len(sources) else None
        if (
            boundary["previous_clip_id"] != (previous["clip_id"] if previous else None)
            or boundary["previous_presentation_end_utc"] != (previous["end_utc"] if previous else None)
            or boundary["next_clip_id"] != (following["clip_id"] if following else None)
            or boundary["next_presentation_start_utc"] != (following["start_utc"] if following else None)
        ):
            raise ValueError("joined allocation ledger boundary source identity conflicts")
        if previous is None or following is None:
            decision, reason = ("no_source_before_boundary", "previous_source_absent") if previous is None else ("no_source_after_boundary", "next_source_absent")
            if (
                boundary["signed_gap_nanoseconds"] is not None or boundary["actual_seam_utc"] is not None
                or boundary["boundary_skew_nanoseconds"] is not None
                or boundary["allocation_decision"] != decision or boundary["verdict"] != "absent_source"
                or boundary["reason"] != reason
            ):
                raise ValueError("joined allocation ledger absent boundary conflicts")
        else:
            gap = joined_timestamp_nanoseconds(following["start_utc"], "source start") - joined_timestamp_nanoseconds(previous["end_utc"], "source end")
            if (
                boundary["signed_gap_nanoseconds"] != gap
                or joined_timestamp_nanoseconds(boundary["actual_seam_utc"], "boundary actual seam") != best_ns
                or boundary["boundary_skew_nanoseconds"] != best_ns - scheduled_ns
                or boundary["allocation_decision"] != "split_before_next_source"
                or boundary["verdict"] != "allocated" or boundary["reason"] != "closest_source_boundary"
            ):
                raise ValueError("joined allocation ledger closest boundary conflicts")
        minimum = best_position


def validate_cross_day_boundaries(payload, location, local_date):
    sources = payload["sources"]
    schedules = (
        (local_boundary_nanoseconds(local_date, location, 20, -1), local_boundary_nanoseconds(local_date, location, 8)),
        (local_boundary_nanoseconds(local_date, location, 20), local_boundary_nanoseconds(local_date, location, 8, 1)),
    )
    for index, (boundary, schedule) in enumerate(zip(payload["cross_day_boundaries"], schedules)):
        previous_scheduled = joined_timestamp_nanoseconds(boundary["scheduled_previous_end_utc"], "scheduled previous end")
        next_scheduled = joined_timestamp_nanoseconds(boundary["scheduled_next_start_utc"], "scheduled next start")
        if (previous_scheduled, next_scheduled) != schedule or previous_scheduled >= next_scheduled:
            raise ValueError("joined cross-day boundary schedule conflicts")
        previous_present = boundary["previous_clip_id"] is not None
        next_present = boundary["next_clip_id"] is not None
        if boundary["verdict"] == "absent_source":
            if previous_present and next_present or boundary["signed_gap_nanoseconds"] is not None or boundary["boundary_skew_nanoseconds"] is not None:
                raise ValueError("joined cross-day absent boundary conflicts")
            reason, decision = ("previous_source_absent", "no_previous_day_source")
            if index == 0 and previous_present:
                reason, decision = "next_source_absent", "empty_day_after_previous_source"
            elif index == 1:
                reason, decision = "next_source_absent", "no_next_day_source"
                if next_present:
                    reason, decision = "previous_source_absent", "empty_day_before_next_source"
            if boundary["reason"] != reason or boundary["allocation_decision"] != decision:
                raise ValueError("joined cross-day absence reason conflicts")
        else:
            if not previous_present or not next_present:
                raise ValueError("joined cross-day boundary lacks adjacent sources")
            gap = joined_timestamp_nanoseconds(boundary["next_presentation_start_utc"], "cross-day next start") - joined_timestamp_nanoseconds(boundary["previous_presentation_end_utc"], "cross-day previous end")
            skew = gap - (next_scheduled - previous_scheduled)
            verdict = "overlap" if gap < 0 else "scheduled_gap"
            if (
                boundary["signed_gap_nanoseconds"] != gap or boundary["boundary_skew_nanoseconds"] != skew
                or boundary["verdict"] != verdict or boundary["allocation_decision"] != "separate_local_days"
                or boundary["reason"] != "scheduled_day_boundary"
            ):
                raise ValueError("joined cross-day boundary classification conflicts")
    if sources and (
        payload["cross_day_boundaries"][0]["next_clip_id"] != sources[0]["clip_id"]
        or payload["cross_day_boundaries"][0]["next_presentation_start_utc"] != sources[0]["start_utc"]
        or payload["cross_day_boundaries"][1]["previous_clip_id"] != sources[-1]["clip_id"]
        or payload["cross_day_boundaries"][1]["previous_presentation_end_utc"] != sources[-1]["end_utc"]
    ):
        raise ValueError("joined cross-day boundary does not bind stream-day edges")


def valid_allocation_ledger(payload):
    fields = {
        "schema_version", "batch_id", "generation", "recording_id", "timezone", "local_date",
        "qualification_day", "qualification_sha256", "frozen_source_sha256", "source_claim_sha256", "source_clip_count", "source_bytes",
        "first_clip_id", "last_clip_id", "consecutive_pairs", "sources", "hours", "hour_source_claim_sha256",
        "cross_hour_boundaries", "cross_day_boundaries", "ledger_sha256",
    }
    exact_joined_fields(payload, fields, "allocation ledger")
    if payload["schema_version"] != 1 or not isinstance(payload["batch_id"], str) or JOINED_BATCH.fullmatch(payload["batch_id"]) is None:
        raise ValueError("joined allocation ledger identity is invalid")
    positive_joined_int(payload["generation"], "generation")
    recording_id = positive_joined_int(payload["recording_id"], "recording_id")
    local_date = valid_joined_date(payload["local_date"])
    valid_qualification_day(payload["qualification_day"], recording_id, payload["timezone"], local_date)
    location = ZoneInfo(payload["timezone"])
    valid_sha256(payload["qualification_sha256"], "qualification")
    valid_sha256(payload["frozen_source_sha256"], "frozen source")
    source_count = positive_joined_int(payload["source_clip_count"], "source_clip_count", allow_zero=True)
    source_bytes = positive_joined_int(payload["source_bytes"], "source_bytes", allow_zero=True)
    if not isinstance(payload["sources"], list) or len(payload["sources"]) != source_count:
        raise ValueError("joined allocation ledger source count conflicts")
    source_ids, object_ids, calculated_bytes = [], set(), 0
    for source in payload["sources"]:
        source_ids.append(valid_source(source, recording_id, source_only=True, location=location, local_date=local_date))
        object_identity = (source["storage_destination_id"],) + tuple(source[key] for key in ("provider", "endpoint", "region", "bucket")) + tuple(source["object"].get(key, "") for key in ("key", "version_id", "etag"))
        if object_identity in object_ids:
            raise ValueError("joined allocation ledger duplicates a source object")
        object_ids.add(object_identity)
        calculated_bytes += source["object"]["size_bytes"]
    for previous, following in zip(payload["sources"], payload["sources"][1:]):
        if (joined_timestamp_nanoseconds(following["start_utc"], "source start") , following["clip_id"]) <= (joined_timestamp_nanoseconds(previous["start_utc"], "source start"), previous["clip_id"]):
            raise ValueError("joined allocation ledger source order conflicts")
    if len(source_ids) != len(set(source_ids)) or calculated_bytes != source_bytes:
        raise ValueError("joined allocation ledger source denominator conflicts")
    if frozen_source_sha(payload["sources"], payload["qualification_day"], recording_id) != payload["frozen_source_sha256"]:
        raise ValueError("joined allocation ledger frozen source identity conflicts")
    if (payload["first_clip_id"], payload["last_clip_id"]) != ((source_ids[0], source_ids[-1]) if source_ids else (None, None)):
        raise ValueError("joined allocation ledger edge identity conflicts")
    pair_fields = {
        "previous_clip_id", "next_clip_id", "previous_presentation_end_utc", "next_presentation_start_utc",
        "signed_gap_nanoseconds",
    }
    if not isinstance(payload["consecutive_pairs"], list) or len(payload["consecutive_pairs"]) != max(0, source_count - 1):
        raise ValueError("joined allocation ledger pair count conflicts")
    for index, pair in enumerate(payload["consecutive_pairs"], 1):
        exact_joined_fields(pair, pair_fields, "allocation pair")
        previous, following = payload["sources"][index - 1], payload["sources"][index]
        previous_end = valid_joined_timestamp(pair["previous_presentation_end_utc"], "pair previous end")
        following_start = valid_joined_timestamp(pair["next_presentation_start_utc"], "pair next start")
        gap = joined_timestamp_nanoseconds(pair["next_presentation_start_utc"], "pair next start") - joined_timestamp_nanoseconds(pair["previous_presentation_end_utc"], "pair previous end")
        valid_joined_int64(pair["signed_gap_nanoseconds"], "pair signed gap")
        if pair["previous_clip_id"] != previous["clip_id"] or pair["next_clip_id"] != following["clip_id"] or pair["previous_presentation_end_utc"] != previous["end_utc"] or pair["next_presentation_start_utc"] != following["start_utc"] or pair["signed_gap_nanoseconds"] != gap:
            raise ValueError("joined allocation ledger pair conflicts")
    if not isinstance(payload["hours"], list) or len(payload["hours"]) != 12 or not isinstance(payload["hour_source_claim_sha256"], list) or len(payload["hour_source_claim_sha256"]) != 12:
        raise ValueError("joined allocation ledger must contain 12 hours")
    flat_ids, cursor = [], 0
    for index, hour in enumerate(payload["hours"], 1):
        exact_joined_fields(hour, {"delivery_hour", "clock_hour", "source_clip_ids"}, "allocation hour")
        if hour["delivery_hour"] != index or hour["clock_hour"] != index + 7 or not isinstance(hour["source_clip_ids"], list):
            raise ValueError("joined allocation ledger hour identity conflicts")
        count = len(hour["source_clip_ids"])
        hour_sources = payload["sources"][cursor:cursor + count]
        if hour["source_clip_ids"] != [source["clip_id"] for source in hour_sources] or source_claim_sha(hour_sources) != payload["hour_source_claim_sha256"][index - 1]:
            raise ValueError("joined allocation ledger hour source claim conflicts")
        flat_ids.extend(hour["source_clip_ids"])
        cursor += count
    if flat_ids != source_ids or source_claim_sha(payload["sources"]) != valid_sha256(payload["source_claim_sha256"], "allocation source claim"):
        raise ValueError("joined allocation ledger ordered source claim conflicts")
    if not isinstance(payload["cross_hour_boundaries"], list) or len(payload["cross_hour_boundaries"]) != 11 or not isinstance(payload["cross_day_boundaries"], list) or len(payload["cross_day_boundaries"]) != 2:
        raise ValueError("joined allocation ledger boundary count conflicts")
    for index, boundary in enumerate(payload["cross_hour_boundaries"], 1):
        valid_boundary(boundary)
        if boundary["previous_delivery_hour"] != index:
            raise ValueError("joined allocation ledger boundary order conflicts")
    for boundary in payload["cross_day_boundaries"]:
        valid_boundary(boundary, cross_day=True)
    validate_cross_hour_boundaries(payload, location, local_date)
    validate_cross_day_boundaries(payload, location, local_date)
    ledger_sha = valid_sha256(payload["ledger_sha256"], "allocation ledger")
    unsealed = dict(payload)
    unsealed["ledger_sha256"] = ""
    if joined_canonical_sha(unsealed) != ledger_sha:
        raise ValueError("joined allocation ledger seal conflicts")
    return payload


def recording_ids_sha(recording_ids):
    return hashlib.sha256("".join("%d\n" % recording_id for recording_id in recording_ids).encode("ascii")).hexdigest()


def joined_naming_token(value):
    out = []
    for character in value.strip():
        if character in "-.":
            out.append(character)
        elif character == "_" or character.isspace():
            out.append("_")
        elif character.isascii() and character.isalnum():
            out.append(character)
    return re.sub(r"_+", "_", "".join(out)).strip("_.")


def joined_folder_name(recording_id, metadata, raw_folder):
    plaza_id = metadata["plaza_id"].strip()
    if not plaza_id.isascii() or not plaza_id.isdigit() or int(plaza_id) <= 0:
        raise ValueError("joined frozen plaza identity is invalid")
    for key in ("continent", "country", "city", "plaza_name"):
        if not metadata[key].strip():
            raise ValueError("joined frozen naming metadata is incomplete")
    if raw_folder.strip():
        parts = raw_folder.strip().strip("/").split("/")
        clean = [joined_naming_token(part) for part in parts]
        if not clean or any(part in ("", ".", "..") for part in clean):
            raise ValueError("joined frozen folder is invalid")
        return "/".join(clean)
    return "_".join((
        "%02d" % int(plaza_id), joined_naming_token(metadata["continent"]),
        joined_naming_token(metadata["country"]), joined_naming_token(metadata["city"]),
        joined_naming_token(metadata["plaza_name"]),
    ))


def joined_delivery_path(frozen, media, delivery_hour):
    location = ZoneInfo(frozen["timezone"])
    start = valid_joined_timestamp(media["actual_start_utc"], "delivery start").astimezone(location)
    end = valid_joined_timestamp(media["actual_end_utc"], "delivery end").astimezone(location)
    if end <= start or start.date() != end.date() or not 1 <= delivery_hour <= 12:
        raise ValueError("joined delivery range is invalid")
    ordinal = positive_joined_int(media["part"], "delivery part")
    parts = positive_joined_int(media["parts"], "delivery parts")
    if ordinal > parts or (parts == 1 and ordinal != 1):
        raise ValueError("joined delivery part is invalid")
    month = start.strftime("%B")
    weekday = start.strftime("%A")
    plaza_id = "%02d" % int(frozen["naming_metadata"]["plaza_id"].strip())
    base = "%s_%s_%04d_%s_W%d_%s_hour_%02d" % (
        plaza_id, joined_naming_token(frozen["naming_metadata"]["plaza_name"]), start.year,
        month, (start.day - 1) // 7 + 1, weekday, delivery_hour,
    )
    if parts > 1:
        base += "_part_%02d" % ordinal
    base += "_%s-%s.mp4" % (start.strftime("%H%M%S"), end.strftime("%H%M%S"))
    return "/".join((frozen["folder_name"], month, weekday, base))


def selected_qualification_windows_sha(recordings):
    return joined_canonical_sha([
        {"recording_id": recording["recording_id"], "qualification_sha256": recording["qualification_sha256"]}
        for recording in recordings
    ])


def qualification_window_sha(recording, days, cutoff, run_frozen_at, rule=""):
    if len(days) != 14:
        raise ValueError("joined qualification window must contain 14 days")
    cutoff_ns = joined_timestamp_nanoseconds(cutoff, "selection cutoff")
    run_frozen_ns = joined_timestamp_nanoseconds(run_frozen_at, "qualification run frozen_at")
    seen_jobs = set()
    previous_date = None
    completed = None
    for ordinal, day in enumerate(days, 1):
        valid_qualification_day(day, recording["recording_id"], recording["timezone"], day["local_date"])
        date = datetime.date.fromisoformat(day["local_date"])
        job_id = day["job_id"]
        completed_ns = joined_timestamp_nanoseconds(day["completed_at"], "qualification completed_at")
        if (
            day["qualification_window_ordinal"] != ordinal or job_id in seen_jobs
            or (previous_date is not None and date != previous_date + datetime.timedelta(days=1))
            or (rule != TIER1_HISTORICAL_QUALIFICATION_VERSION
                and joined_timestamp_nanoseconds(day["window_start"], "qualification window_start") < run_frozen_ns)
            or completed_ns > cutoff_ns
        ):
            raise ValueError("joined qualification window conflicts")
        seen_jobs.add(job_id)
        previous_date = date
        completed = completed_ns if completed is None else max(completed, completed_ns)
    if completed != joined_timestamp_nanoseconds(recording["completed_at"], "recording completed_at"):
        raise ValueError("joined recording completion conflicts with qualification window")
    window = {
        "recording_id": recording["recording_id"],
        "timezone": recording["timezone"],
        "days": days,
        "frozen_at": cutoff,
    }
    if rule == TIER1_HISTORICAL_QUALIFICATION_VERSION:
        window["authority_kind"] = TIER1_HISTORICAL_AUTHORITY_KIND
    window["evidence_sha256"] = ""
    return joined_canonical_sha(window)


def valid_selection_authority(authority, recording_ids, frozen_recordings):
    fields = {
        "selection_basis", "ordered_recording_ids_sha256", "cutoff", "qualification_run_id",
        "qualification_run_frozen_at", "qualification_rule_version", "qualification_cohort_sha256",
        "qualification_windows_sha256", "selected_qualification_windows_sha256",
    }
    exact_joined_fields(authority, fields, "selection authority")
    cutoff = valid_joined_timestamp(authority["cutoff"], "selection cutoff")
    cutoff_ns = joined_timestamp_nanoseconds(authority["cutoff"], "selection cutoff")
    run_frozen = valid_joined_timestamp(authority["qualification_run_frozen_at"], "qualification run frozen_at")
    run_frozen_ns = joined_timestamp_nanoseconds(authority["qualification_run_frozen_at"], "qualification run frozen_at")
    rule = valid_joined_string(authority["qualification_rule_version"], "qualification rule version", maximum=128)
    if (
        authority["selection_basis"] != "operator_approved_ordered_cohort_v1" or not authority["cutoff"].endswith("Z")
        or cutoff.utcoffset() != datetime.timedelta(0) or joined_timestamp_is_go_zero(cutoff)
        or joined_timestamp_is_go_zero(run_frozen)
        or authority["ordered_recording_ids_sha256"] != recording_ids_sha(recording_ids)
        or (rule != TIER1_HISTORICAL_QUALIFICATION_VERSION and run_frozen_ns > cutoff_ns)
        or (rule == TIER1_HISTORICAL_QUALIFICATION_VERSION and run_frozen_ns <= cutoff_ns)
        or rule.strip() != rule or len(rule.encode("utf-8")) > 128
        or positive_joined_int(authority["qualification_run_id"], "qualification_run_id") < 1
    ):
        raise ValueError("joined selection authority conflicts")
    for key in ("qualification_cohort_sha256", "qualification_windows_sha256", "selected_qualification_windows_sha256"):
        valid_sha256(authority[key], "selection authority")
    if selected_qualification_windows_sha(frozen_recordings) != authority["selected_qualification_windows_sha256"]:
        raise ValueError("joined selected qualification evidence conflicts")
    return cutoff_ns


def frozen_denominator_sha(selection_authority, recordings, ledgers):
    return joined_canonical_sha({
        "projection_version": 2,
        "selection_authority": selection_authority,
        "recordings": [{
            "recording_id": recording["recording_id"],
            "priority_ordinal": recording["priority_ordinal"],
            "selection_tier": recording["selection_tier"],
            "completed_at": recording["completed_at"],
        } for recording in recordings],
        "days": [{
            "recording_id": ledger["recording_id"], "local_date": ledger["local_date"],
            "qualification_sha256": ledger["qualification_sha256"],
            "frozen_source_sha256": ledger["frozen_source_sha256"],
            "source_count": ledger["source_count"] if "source_count" in ledger else ledger["source_clip_count"],
            "source_bytes": ledger["source_bytes"],
        } for ledger in ledgers],
    })


def batch_generation_sha(payload):
    evidence_ledgers = [{
        "recording_id": ledger["recording_id"], "local_date": ledger["local_date"],
        "qualification_sha256": ledger["qualification_sha256"], "source_claim_sha256": ledger["source_claim_sha256"],
        "ledger_sha256": ledger["ledger_sha256"], "source_count": ledger["source_count"],
        "source_bytes": ledger["source_bytes"],
    } for ledger in payload["allocation_ledgers"]]
    return joined_canonical_sha({
        "schema_version": payload["schema_version"], "policy_version": payload["policy_version"],
        "batch_id": payload["batch_id"], "generation": payload["generation"], "frozen_at": payload["frozen_at"],
        "frozen_denominator_sha256": payload["frozen_denominator_sha256"],
        "selection_authority": payload["selection_authority"], "frozen_recordings": payload["frozen_recordings"],
        "media_tool_identity": payload["media_tool"]["identity_sha256"],
        "expected_ledger_count": payload["expected_ledger_count"], "scheduled_hour_count": payload["scheduled_hour_count"],
        "source_clip_count": payload["source_clip_count"], "source_bytes": payload["source_bytes"],
        "ledgers": evidence_ledgers,
    })


def valid_batch_index(payload, item=None):
    fields = {
        "schema_version", "policy_version", "allocation_schema_version", "hour_manifest_schema_version",
        "batch_id", "generation", "frozen_at", "batch_generation_sha256", "frozen_denominator_sha256",
        "recording_ids", "selection_authority", "frozen_recordings", "media_tool", "expected_ledger_count",
        "scheduled_hour_count", "source_clip_count", "source_bytes", "final_media_artifact_count",
        "allocation_ledgers", "hours",
    }
    exact_joined_fields(payload, fields, "batch index")
    if payload["schema_version"] != 1 or payload["policy_version"] != "joined-delivery-v1" or payload["allocation_schema_version"] != 1 or payload["hour_manifest_schema_version"] not in (1, 2):
        raise ValueError("joined batch index schema conflicts")
    batch_id = payload["batch_id"]
    if not isinstance(batch_id, str) or JOINED_BATCH.fullmatch(batch_id) is None:
        raise ValueError("joined batch index identity is invalid")
    generation = positive_joined_int(payload["generation"], "generation")
    frozen_at_ns = joined_timestamp_nanoseconds(payload["frozen_at"], "frozen_at")
    valid_sha256(payload["frozen_denominator_sha256"], "frozen denominator")
    recording_ids = payload["recording_ids"]
    if not isinstance(recording_ids, list) or not recording_ids or any(isinstance(value, bool) or not isinstance(value, int) or value < 1 for value in recording_ids) or len(set(recording_ids)) != len(recording_ids):
        raise ValueError("joined batch recording identities are invalid")
    valid_media_tool(payload["media_tool"])
    frozen_fields = {"recording_id", "priority_ordinal", "selection_tier", "qualification_sha256", "completed_at", "timezone", "folder_name", "naming_metadata"}
    naming_fields = {"plaza_id", "continent", "country", "city", "plaza_name"}
    if not isinstance(payload["frozen_recordings"], list) or len(payload["frozen_recordings"]) != len(recording_ids):
        raise ValueError("joined frozen recording count conflicts")
    for ordinal, (recording_id, frozen) in enumerate(zip(recording_ids, payload["frozen_recordings"]), 1):
        exact_joined_fields(frozen, frozen_fields, "frozen recording")
        exact_joined_fields(frozen["naming_metadata"], naming_fields, "frozen recording naming")
        if frozen["recording_id"] != recording_id or frozen["priority_ordinal"] != ordinal or frozen["selection_tier"] != "good+":
            raise ValueError("joined frozen recording order conflicts")
        try:
            ZoneInfo(valid_joined_string(frozen["timezone"], "frozen timezone", maximum=255))
        except ZoneInfoNotFoundError as exc:
            raise ValueError("joined frozen timezone is invalid") from exc
        valid_sha256(frozen["qualification_sha256"], "recording qualification")
        if joined_timestamp_is_go_zero(valid_joined_timestamp(frozen["completed_at"], "completed_at")):
            raise ValueError("joined frozen recording completion is zero")
        for key, value in frozen["naming_metadata"].items():
            valid_joined_string(value, "frozen naming %s" % key)
        if valid_joined_relative_path(frozen["folder_name"]) != joined_folder_name(recording_id, frozen["naming_metadata"], frozen["folder_name"]):
            raise ValueError("joined frozen recording folder conflicts")
    cutoff_ns = valid_selection_authority(payload["selection_authority"], recording_ids, payload["frozen_recordings"])
    if frozen_at_ns < cutoff_ns or any(joined_timestamp_nanoseconds(recording["completed_at"], "completed_at") > cutoff_ns for recording in payload["frozen_recordings"]):
        raise ValueError("joined batch selection cutoff conflicts")
    ledgers, hours = payload["allocation_ledgers"], payload["hours"]
    expected_ledger_count = positive_joined_int(payload["expected_ledger_count"], "expected_ledger_count")
    scheduled_hour_count = positive_joined_int(payload["scheduled_hour_count"], "scheduled_hour_count")
    positive_joined_int(payload["source_clip_count"], "source_clip_count", allow_zero=True)
    positive_joined_int(payload["source_bytes"], "source_bytes", allow_zero=True)
    positive_joined_int(payload["final_media_artifact_count"], "final_media_artifact_count", allow_zero=True)
    if not isinstance(ledgers, list) or expected_ledger_count != len(ledgers) or expected_ledger_count != len(recording_ids) * 14 or not isinstance(hours, list) or scheduled_hour_count != len(hours) or scheduled_hour_count != expected_ledger_count * 12:
        raise ValueError("joined batch denominator shape conflicts")
    ledger_fields = {
        "artifact_id", "recording_id", "local_date", "qualification_sha256", "frozen_source_sha256", "source_claim_sha256",
        "relative_path", "object_key", "size_bytes", "sha256", "ledger_sha256", "source_count",
        "source_bytes", "scheduled_hour_ids",
    }
    seen_artifacts, expected_hours = set(), {}
    source_count = source_bytes = 0
    previous_date = None
    for index, ledger in enumerate(ledgers):
        exact_joined_fields(ledger, ledger_fields, "batch ledger reference")
        recording_id, day_index = recording_ids[index // 14], index % 14
        local_date = valid_joined_date(ledger["local_date"])
        parsed_date = datetime.date.fromisoformat(local_date)
        if (
            ledger["recording_id"] != recording_id
            or ledger["qualification_sha256"] != payload["frozen_recordings"][index // 14]["qualification_sha256"]
            or (day_index and parsed_date != previous_date + datetime.timedelta(days=1))
        ):
            raise ValueError("joined batch ledger order conflicts")
        previous_date = parsed_date
        artifact_id = positive_joined_int(ledger["artifact_id"], "ledger artifact_id")
        if artifact_id in seen_artifacts:
            raise ValueError("joined batch artifact identity is duplicated")
        seen_artifacts.add(artifact_id)
        relative = "coverage/ledgers/%d/%s.json" % (recording_id, local_date)
        if ledger["relative_path"] != relative or ledger["object_key"] != "joined/%s/%s" % (batch_id, relative):
            raise ValueError("joined batch ledger path conflicts")
        if positive_joined_int(ledger["size_bytes"], "ledger size_bytes") > JOINED_MANIFEST_MAX_BYTES:
            raise ValueError("joined batch ledger exceeds JSON size cap")
        for key in ("qualification_sha256", "frozen_source_sha256", "source_claim_sha256", "sha256", "ledger_sha256"):
            valid_sha256(ledger[key], "batch ledger")
        source_count += positive_joined_int(ledger["source_count"], "ledger source_count", allow_zero=True)
        source_bytes += positive_joined_int(ledger["source_bytes"], "ledger source_bytes", allow_zero=True)
        if not isinstance(ledger["scheduled_hour_ids"], list) or len(ledger["scheduled_hour_ids"]) != 12:
            raise ValueError("joined batch ledger hour identities are invalid")
        for delivery_hour, hour_id in enumerate(ledger["scheduled_hour_ids"], 1):
            expected = "%s__recording-%d__date-%s__hour-%02d__generation-%d" % (batch_id, recording_id, local_date, delivery_hour, generation)
            if hour_id != expected or hour_id in expected_hours:
                raise ValueError("joined batch ledger hour identity conflicts")
            expected_hours[hour_id] = ledger
    hour_fields = {
        "hour_manifest_artifact_id", "hour_id", "recording_id", "local_date", "delivery_hour", "status",
        "relative_path", "object_key", "size_bytes", "sha256", "source_count", "source_bytes",
        "media_artifact_count",
    }
    hour_source_count = hour_source_bytes = media_count = 0
    for index, hour in enumerate(hours):
        exact_joined_fields(hour, hour_fields, "batch hour reference")
        ledger = ledgers[index // 12]
        hour_id = hour["hour_id"]
        artifact_id = positive_joined_int(hour["hour_manifest_artifact_id"], "hour manifest artifact_id")
        if artifact_id in seen_artifacts or hour_id != ledger["scheduled_hour_ids"][index % 12] or expected_hours.get(hour_id) is not ledger or hour["delivery_hour"] != index % 12 + 1 or hour["recording_id"] != ledger["recording_id"] or hour["local_date"] != ledger["local_date"]:
            raise ValueError("joined batch hour order conflicts")
        seen_artifacts.add(artifact_id)
        relative = "coverage/hours/%s.json" % hour_id
        if hour["relative_path"] != relative or hour["object_key"] != "joined/%s/%s" % (batch_id, relative):
            raise ValueError("joined batch hour path conflicts")
        if positive_joined_int(hour["size_bytes"], "hour size_bytes") > JOINED_MANIFEST_MAX_BYTES:
            raise ValueError("joined batch hour exceeds JSON size cap")
        valid_sha256(hour["sha256"], "batch hour")
        count = positive_joined_int(hour["source_count"], "hour source_count", allow_zero=True)
        byte_count = positive_joined_int(hour["source_bytes"], "hour source_bytes", allow_zero=True)
        media = positive_joined_int(hour["media_artifact_count"], "media artifact count", allow_zero=True)
        if hour["status"] == "media":
            if count == 0 or media == 0:
                raise ValueError("joined media hour lacks sources or artifacts")
        elif hour["status"] == "gap_only":
            if count or byte_count or media:
                raise ValueError("joined gap-only hour accounts sources")
        elif hour["status"] == "quarantine_only":
            if count == 0 or media:
                raise ValueError("joined quarantine-only hour conflicts")
        else:
            raise ValueError("joined batch hour status is invalid")
        hour_source_count += count
        hour_source_bytes += byte_count
        media_count += media
    if source_count != payload["source_clip_count"] or source_bytes != payload["source_bytes"] or hour_source_count != source_count or hour_source_bytes != source_bytes or media_count != payload["final_media_artifact_count"]:
        raise ValueError("joined batch aggregate denominator conflicts")
    if frozen_denominator_sha(payload["selection_authority"], payload["frozen_recordings"], ledgers) != payload["frozen_denominator_sha256"]:
        raise ValueError("joined frozen denominator hash conflicts")
    if batch_generation_sha(payload) != payload["batch_generation_sha256"]:
        raise ValueError("joined batch generation hash conflicts")
    if item is not None and (item["batch_id"] != batch_id or item["relative_path"] != "coverage/batch.json"):
        raise ExistingFileMismatch("joined batch index identity conflicts")
    return payload


def valid_audio_contract(contract):
    fields = {"codec_name", "sample_rate", "channels", "channel_layout", "initial_padding", "skip_samples", "discard_padding", "codec_delay", "trailing_padding"}
    if not isinstance(contract, dict) or set(contract) not in (fields, fields | {"edit_list_kind", "edit_list_sha256"}):
        raise ValueError("joined audio contract has invalid fields")
    if not valid_joined_string(contract["codec_name"], "audio codec").strip() or not valid_joined_string(contract["channel_layout"], "audio channel layout").strip():
        raise ValueError("joined audio contract has blank format fields")
    positive_joined_int(contract["sample_rate"], "audio sample_rate")
    positive_joined_int(contract["channels"], "audio channels")
    for key in ("initial_padding", "skip_samples", "discard_padding", "codec_delay", "trailing_padding"):
        positive_joined_int(contract[key], key, allow_zero=True)
    if "edit_list_sha256" in contract:
        valid_joined_string(contract["edit_list_kind"], "edit list kind")
        valid_sha256(contract["edit_list_sha256"], "edit list")


def valid_media_fingerprint(fingerprint, output, aac_padding=False):
    base_fields = {"duration_seconds", "tracks"}
    decoded_video_fields = {"decoded_video_sha256"}
    audio_fields = {"audio_sequence_contracts", "effective_audio_bytes", "effective_audio_sample_frames", "effective_audio_sha256"}
    allowed = (base_fields, base_fields | decoded_video_fields, base_fields | audio_fields, base_fields | decoded_video_fields | audio_fields)
    if not isinstance(fingerprint, dict) or set(fingerprint) not in allowed:
        raise ValueError("joined media fingerprint has invalid fields")
    if "decoded_video_sha256" in fingerprint:
        valid_sha256(fingerprint["decoded_video_sha256"], "decoded video")
    if (
        isinstance(fingerprint["duration_seconds"], bool)
        or not isinstance(fingerprint["duration_seconds"], (int, float))
        or not math.isfinite(fingerprint["duration_seconds"])
        or fingerprint["duration_seconds"] <= 0
    ):
        raise ValueError("joined media fingerprint has invalid duration")
    tracks = fingerprint["tracks"]
    if not isinstance(tracks, dict) or set(tracks) not in ({"video"}, {"video", "audio"}):
        raise ValueError("joined media fingerprint has invalid tracks")
    track_base = {
        "media_type", "packet_count", "packet_chain_sha256", "packet_timing_sha256", "packet_time_bases",
        "first_packet_pts_seconds", "last_packet_pts_seconds", "first_packet_dts_seconds", "last_packet_dts_seconds",
        "packet_duration_seconds", "decode_timeline_span_seconds", "decoded_frames", "first_timestamp", "last_timestamp",
        "timestamp_status",
    }
    for media_type, track in tracks.items():
        fields = track_base | ({"decoded_samples"} if media_type == "audio" else set())
        if aac_padding and media_type == "audio":
            fields |= {"codec_profile", "codec_extradata_sha256"}
            if not output:
                fields.add("aac_padding_normalized_timing_sha256")
        exact_joined_fields(track, fields, "media track fingerprint")
        if track["media_type"] != media_type:
            raise ValueError("joined media track identity conflicts")
        for key in ("packet_count", "decoded_frames"):
            positive_joined_int(track[key], "media track %s" % key)
        if aac_padding and media_type == "audio":
            if track["codec_profile"] != "LC":
                raise ValueError("joined AAC profile conflicts")
            valid_sha256(track["codec_extradata_sha256"], "AAC codec extradata")
            if not output:
                valid_sha256(track["aac_padding_normalized_timing_sha256"], "AAC normalized timing")
        if media_type == "audio":
            positive_joined_int(track["decoded_samples"], "decoded_samples")
        for key in ("packet_chain_sha256", "packet_timing_sha256"):
            valid_sha256(track[key], "media track")
        if not isinstance(track["packet_time_bases"], list) or not track["packet_time_bases"] or not all(isinstance(value, str) and re.fullmatch(r"[1-9][0-9]*/[1-9][0-9]*", value) for value in track["packet_time_bases"]):
            raise ValueError("joined media track has invalid time base")
        for key in ("first_packet_pts_seconds", "last_packet_pts_seconds", "first_packet_dts_seconds", "last_packet_dts_seconds", "packet_duration_seconds", "decode_timeline_span_seconds"):
            if not isinstance(track[key], str) or re.fullmatch(r"-?[0-9]+(?:/[1-9][0-9]*)?", track[key]) is None:
                raise ValueError("joined media track has invalid rational")
        for key in ("packet_duration_seconds", "decode_timeline_span_seconds"):
            if int(track[key].split("/", 1)[0]) <= 0:
                raise ValueError("joined media track has non-positive duration")
        for key in ("first_timestamp", "last_timestamp"):
            if isinstance(track[key], bool) or not isinstance(track[key], int):
                raise ValueError("joined media track has invalid timestamp")
        if output and (track["timestamp_status"] != "monotonic" or track["decode_timeline_span_seconds"] != track["packet_duration_seconds"]):
            raise ValueError("joined output timestamps are not monotonic")
    if "audio" in tracks:
        expected_fields = base_fields | audio_fields | (decoded_video_fields if "decoded_video_sha256" in fingerprint else set())
        if set(fingerprint) != expected_fields or not isinstance(fingerprint["audio_sequence_contracts"], list) or not fingerprint["audio_sequence_contracts"] or (output and len(fingerprint["audio_sequence_contracts"]) != 1):
            raise ValueError("joined audio fingerprint lacks contracts")
        for contract in fingerprint["audio_sequence_contracts"]:
            valid_audio_contract(contract)
        positive_joined_int(fingerprint["effective_audio_bytes"], "effective_audio_bytes")
        positive_joined_int(fingerprint["effective_audio_sample_frames"], "effective_audio_sample_frames")
        valid_sha256(fingerprint["effective_audio_sha256"], "effective audio")
    elif set(fingerprint) not in (base_fields, base_fields | decoded_video_fields):
        raise ValueError("joined audio evidence exists without an audio track")


def rejected_video_stream_copy_equivalent(expected, actual, decoded):
    if set(expected["tracks"]) != {"video"} or set(actual["tracks"]) != {"video"} or abs(actual["duration_seconds"] - expected["duration_seconds"]) > 2:
        return False
    want, got = expected["tracks"]["video"], actual["tracks"]["video"]
    if want["timestamp_status"] != "source_clips_independent" or got["timestamp_status"] != "monotonic":
        return False
    if decoded:
        return (
            want["packet_count"] == got["packet_count"] and
            want["packet_chain_sha256"] == got["packet_chain_sha256"] and
            want["decoded_frames"] == got["decoded_frames"] and
            expected.get("decoded_video_sha256") == actual.get("decoded_video_sha256")
        )
    return (
        want["packet_time_bases"] == got["packet_time_bases"] and
        want["packet_duration_seconds"] == got["packet_duration_seconds"] and
        got["decode_timeline_span_seconds"] == got["packet_duration_seconds"] and
        want["first_packet_pts_seconds"] == got["first_packet_pts_seconds"] and
        want["last_packet_pts_seconds"] == got["last_packet_pts_seconds"] and
        want["first_packet_dts_seconds"] == got["first_packet_dts_seconds"] and
        want["last_packet_dts_seconds"] == got["last_packet_dts_seconds"] and
        want["packet_count"] == got["packet_count"] and
        want["packet_chain_sha256"] == got["packet_chain_sha256"] and
        want["packet_timing_sha256"] == got["packet_timing_sha256"] and
        want["decoded_frames"] == got["decoded_frames"]
    )

def valid_aac_padding_verification(verification):
    expected, actual = verification["source_fingerprint"], verification["output_fingerprint"]
    evidence = verification["audio_padding_normalization"]
    evidence_fields = {
        "policy_version", "sources", "output", "ordered_source_evidence_sha256",
        "decoded_audio_surplus_samples", "packet_duration_delta_seconds",
        "decode_timeline_span_delta_seconds", "audio_content_status",
    }
    exact_joined_fields(evidence, evidence_fields, "AAC padding normalization")
    policy = evidence["policy_version"]
    if policy not in ("aac-discard-padding-v1", "aac-discard-padding-v2") or evidence["audio_content_status"] != "compressed_packets_exact_decoded_audio_not_sample_exact":
        raise ValueError("joined AAC padding policy conflicts")
    if not isinstance(evidence["sources"], list) or len(evidence["sources"]) < 2:
        raise ValueError("joined AAC padding sources are invalid")
    valid_sha256(evidence["ordered_source_evidence_sha256"], "ordered AAC source evidence")
    if joined_canonical_sha(evidence["sources"]) != evidence["ordered_source_evidence_sha256"]:
        raise ValueError("joined AAC source evidence hash conflicts")

    source_contracts, output_contracts = expected.get("audio_sequence_contracts", []), actual.get("audio_sequence_contracts", [])
    if len(source_contracts) != len(evidence["sources"]) or len(output_contracts) != 1:
        raise ValueError("joined AAC contract cardinality conflicts")
    want_audio, got_audio = expected["tracks"].get("audio"), actual["tracks"].get("audio")
    want_video, got_video = expected["tracks"].get("video"), actual["tracks"].get("video")
    if any(track is None for track in (want_audio, got_audio, want_video, got_video)):
        raise ValueError("joined AAC tracks are incomplete")
    if (
        want_audio["codec_profile"] != "LC" or got_audio["codec_profile"] != "LC"
        or want_audio["codec_extradata_sha256"] != got_audio["codec_extradata_sha256"]
        or want_audio["packet_time_bases"] != ["1/44100"] or got_audio["packet_time_bases"] != ["1/44100"]
    ):
        raise ValueError("joined AAC codec identity conflicts")
    if (
        want_video["timestamp_status"] != "source_clips_independent" or got_video["timestamp_status"] != "monotonic"
        or any(want_video[key] != got_video[key] for key in ("packet_count", "packet_chain_sha256", "packet_time_bases", "decoded_frames"))
        or want_audio["timestamp_status"] != "source_clips_independent" or got_audio["timestamp_status"] != "monotonic"
        or any(want_audio[key] != got_audio[key] for key in ("packet_count", "packet_chain_sha256", "packet_time_bases", "decoded_frames"))
        or got_audio["packet_timing_sha256"] != want_audio["aac_padding_normalized_timing_sha256"]
    ):
        raise ValueError("joined AAC exact packet or video evidence conflicts")

    def valid_trim(item, source):
        fields = {
            "packet_count", "max_decoded_frame_samples", "last_decoded_frame_samples",
            "terminal_packet_duration_samples", "trim_events",
        }
        if source:
            fields |= {"clip_id", "source_claim_sha256"}
            if policy == "aac-discard-padding-v2":
                fields |= {"first_packet_pts_samples", "first_packet_dts_samples"}
        exact_joined_fields(item, fields, "AAC trim evidence")
        if source:
            positive_joined_int(item["clip_id"], "AAC source clip_id")
            valid_sha256(item["source_claim_sha256"], "AAC source claim")
            if policy == "aac-discard-padding-v2":
                positive_joined_int(item["first_packet_pts_samples"], "AAC source first PTS", allow_zero=True)
                positive_joined_int(item["first_packet_dts_samples"], "AAC source first DTS", allow_zero=True)
        for key in ("packet_count", "max_decoded_frame_samples", "last_decoded_frame_samples", "terminal_packet_duration_samples"):
            positive_joined_int(item[key], "AAC trim %s" % key)
        if item["max_decoded_frame_samples"] != 1024 or item["terminal_packet_duration_samples"] != 1024:
            raise ValueError("joined AAC frame contract conflicts")
        events = item["trim_events"]
        if not isinstance(events, list) or len(events) > 1:
            raise ValueError("joined AAC trim events conflict")
        if not events:
            if item["last_decoded_frame_samples"] != 1024:
                raise ValueError("joined AAC partial frame lacks padding")
            return 0
        event = exact_joined_fields(events[0], {"packet_ordinal", "skip_samples", "discard_padding"}, "AAC trim event")
        if (
            event["packet_ordinal"] != item["packet_count"] or event["skip_samples"] != 0
            or isinstance(event["discard_padding"], bool) or not isinstance(event["discard_padding"], int)
            or event["discard_padding"] <= 0 or event["discard_padding"] > 1024
            or item["last_decoded_frame_samples"] + event["discard_padding"] != 1024
        ):
            raise ValueError("joined AAC trim position conflicts")
        return event["discard_padding"]

    source_packets, padding, seen_source_ids = 0, 0, set()
    first_format = {key: source_contracts[0][key] for key in ("codec_name", "sample_rate", "channels", "channel_layout")}
    if first_format != {"codec_name": "aac", "sample_rate": 44100, "channels": 2, "channel_layout": "stereo"}:
        raise ValueError("joined AAC format conflicts")
    for index, (item, contract) in enumerate(zip(evidence["sources"], source_contracts)):
        if item["clip_id"] in seen_source_ids:
            raise ValueError("joined AAC source identity is duplicated")
        seen_source_ids.add(item["clip_id"])
        if (
            {key: contract[key] for key in first_format} != first_format
            or any(contract[key] != 0 for key in ("initial_padding", "skip_samples", "codec_delay", "trailing_padding"))
        ):
            raise ValueError("joined AAC source padding conflicts")
        discard = valid_trim(item, True)
        if (
            discard != contract["discard_padding"]
            or policy == "aac-discard-padding-v2" and (
                item["first_packet_pts_samples"] != discard
                or item["first_packet_dts_samples"] != discard
            )
        ):
            raise ValueError("joined AAC source discard conflicts")
        source_packets += item["packet_count"]
        if index < len(source_contracts) - 1:
            padding += discard
    if policy == "aac-discard-padding-v2":
        offsets = [contract["discard_padding"] for contract in source_contracts]
        if any(offsets[index] < offsets[index - 1] for index in range(1, len(offsets))):
            raise ValueError("joined variable AAC source offsets decrease")
        if (
            want_video["packet_count"] != want_video["decoded_frames"]
            or want_video["decode_timeline_span_seconds"] != want_video["packet_duration_seconds"]
        ):
            raise ValueError("joined variable AAC video timing proof is incomplete")
        if any(Fraction(got_video[key]) != Fraction(want_video[key]) for key in ("first_packet_pts_seconds", "first_packet_dts_seconds")):
            raise ValueError("joined variable AAC video first timestamp conflicts")
        hold = Fraction(got_video["packet_duration_seconds"]) - Fraction(want_video["packet_duration_seconds"])
        if hold < 0:
            raise ValueError("joined variable AAC video hold conflicts")
        for key in ("decode_timeline_span_seconds", "last_packet_pts_seconds", "last_packet_dts_seconds"):
            if Fraction(got_video[key]) - Fraction(want_video[key]) != hold:
                raise ValueError("joined variable AAC video timing transform conflicts")
        maximum_hold = min(
            Fraction(2),
            Fraction(want_video["packet_duration_seconds"]) * (len(source_contracts) - 1) / want_video["packet_count"],
        )
        if hold > maximum_hold:
            raise ValueError("joined variable AAC video hold exceeds aggregate seam budget")
    output_discard = valid_trim(evidence["output"], False)
    output_contract = output_contracts[0]
    if (
        {key: output_contract[key] for key in first_format} != first_format
        or any(output_contract[key] != 0 for key in ("initial_padding", "skip_samples", "codec_delay", "trailing_padding"))
        or output_discard != output_contract["discard_padding"]
        or output_discard != source_contracts[-1]["discard_padding"]
        or source_packets != want_audio["packet_count"] or evidence["output"]["packet_count"] != got_audio["packet_count"]
        or padding <= 0 or evidence["decoded_audio_surplus_samples"] != padding
    ):
        raise ValueError("joined AAC output padding conflicts")
    bytes_per_frame = first_format["channels"] * 4
    if (
        got_audio["decoded_samples"] - want_audio["decoded_samples"] != padding
        or actual["effective_audio_sample_frames"] - expected["effective_audio_sample_frames"] != padding
        or actual["effective_audio_bytes"] - expected["effective_audio_bytes"] != padding * bytes_per_frame
        or expected["effective_audio_sample_frames"] != want_audio["decoded_samples"]
        or actual["effective_audio_sample_frames"] != got_audio["decoded_samples"]
        or expected["effective_audio_bytes"] != expected["effective_audio_sample_frames"] * bytes_per_frame
        or actual["effective_audio_bytes"] != actual["effective_audio_sample_frames"] * bytes_per_frame
        or expected["effective_audio_sha256"] == actual["effective_audio_sha256"]
    ):
        raise ValueError("joined AAC decoded surplus conflicts")
    timing_padding = padding if policy == "aac-discard-padding-v1" else sum(contract["discard_padding"] for contract in source_contracts[1:])
    if policy == "aac-discard-padding-v2" and all(contract["discard_padding"] == source_contracts[0]["discard_padding"] for contract in source_contracts[1:]):
        raise ValueError("joined variable AAC padding policy has constant offsets")
    delta = Fraction(timing_padding, 44100)
    for key in ("packet_duration_seconds", "decode_timeline_span_seconds"):
        observed = Fraction(got_audio[key]) - Fraction(want_audio[key])
        evidence_key = "packet_duration_delta_seconds" if key == "packet_duration_seconds" else "decode_timeline_span_delta_seconds"
        if observed != delta or Fraction(evidence[evidence_key]) != delta or evidence[evidence_key] != str(delta):
            raise ValueError("joined AAC timing delta conflicts")
    for key in ("first_packet_pts_seconds", "first_packet_dts_seconds"):
        if Fraction(got_audio[key]) != Fraction(want_audio[key]):
            raise ValueError("joined AAC first timestamp conflicts")
    for key in ("last_packet_pts_seconds", "last_packet_dts_seconds"):
        if Fraction(got_audio[key]) - Fraction(want_audio[key]) != delta:
            raise ValueError("joined AAC last timestamp conflicts")



def valid_verification(verification, media_size=None):
    strict_fields = {
        "status", "packet_payload_order_status", "decoded_frame_totals_status", "decoded_audio_totals_status",
        "output_timestamp_status", "strict_decode_status", "source_fingerprint", "output_fingerprint",
    }
    relaxed_fields = strict_fields | {"acceptance_mode", "decoded_frame_sequence_status"}
    normalized_fields = relaxed_fields | {"lossless_normalization"}
    padding_fields = relaxed_fields | {"audio_padding_normalization"}
    fields = set(verification) if isinstance(verification, dict) else set()
    if fields not in (strict_fields, relaxed_fields, normalized_fields, padding_fields):
        raise ValueError("joined media verification has invalid fields")
    exact_joined_fields(verification, fields, "media verification")
    normalized = fields == normalized_fields
    padding = fields == padding_fields
    for key in fields - {"source_fingerprint", "output_fingerprint", "lossless_normalization", "audio_padding_normalization"}:
        if key == "acceptance_mode":
            want_mode = "lossless_native_timeline_normalized" if normalized else ("video_frame_exact_audio_padding_normalized" if padding else "decoded_frame_equivalent")
            if verification[key] != want_mode:
                raise ValueError("joined media verification has invalid acceptance mode")
        elif key == "packet_payload_order_status" and normalized:
            if verification[key] != "not_applicable_lossless_normalization":
                raise ValueError("joined lossless normalization has invalid packet status")
        elif key == "decoded_audio_totals_status" and padding:
            if verification[key] != "aac_discard_padding_normalized":
                raise ValueError("joined AAC padding normalization has invalid audio status")
        elif verification[key] != "passed":
            raise ValueError("joined media verification did not pass")
    valid_media_fingerprint(verification["source_fingerprint"], False, aac_padding=padding)
    valid_media_fingerprint(verification["output_fingerprint"], True, aac_padding=padding)
    expected, actual = verification["source_fingerprint"], verification["output_fingerprint"]
    if set(expected["tracks"]) != set(actual["tracks"]) or abs(actual["duration_seconds"] - expected["duration_seconds"]) > 2:
        raise ValueError("joined media fingerprint stream set conflicts")
    relaxed = fields in (relaxed_fields, padding_fields)
    if relaxed:
        valid_sha256(expected.get("decoded_video_sha256"), "decoded video")
        valid_sha256(actual.get("decoded_video_sha256"), "decoded video")
        if expected["decoded_video_sha256"] != actual["decoded_video_sha256"]:
            raise ValueError("joined decoded video sequence conflicts")
    if padding:
        valid_aac_padding_verification(verification)
        return
    if normalized:
        evidence = verification["lossless_normalization"]
        evidence_fields = {
            "codec", "preset", "quantizer", "pixel_format", "frame_rate", "timeline_rule",
            "sample_aspect_ratio", "color_range", "color_space", "color_transfer", "color_primaries",
            "chroma_location", "field_order",
            "source_decoded_frames", "output_decoded_frames", "decoded_frame_sequence_sha256",
            "decoded_frame_field_status", "decoded_frame_field_sha256",
            "source_timeline_signature_sha256", "output_limit_bytes", "audio_status",
            "trigger_reason_code", "trigger_failure_facts", "trigger_failure_sha256",
        }
        exact_joined_fields(evidence, evidence_fields, "lossless normalization")
        if evidence["codec"] != "libx264" or evidence["preset"] != "veryfast" or evidence["quantizer"] != 0 or evidence["pixel_format"] != "yuv420p" or evidence["audio_status"] != "absent" or evidence["trigger_reason_code"] != "media_sequence_mismatch":
            raise ValueError("joined lossless normalization codec evidence conflicts")
        if not isinstance(evidence["frame_rate"], str) or re.fullmatch(r"[1-9][0-9]*(?:/[1-9][0-9]*)?", evidence["frame_rate"]) is None:
            raise ValueError("joined lossless normalization frame rate conflicts")
        if not isinstance(evidence["sample_aspect_ratio"], str) or re.fullmatch(r"[1-9][0-9]*:[1-9][0-9]*", evidence["sample_aspect_ratio"]) is None:
            raise ValueError("joined lossless normalization aspect ratio conflicts")
        for display_field in ("color_range", "color_space", "color_transfer", "color_primaries", "chroma_location", "field_order"):
            if not isinstance(evidence[display_field], str) or len(evidence[display_field]) > 64:
                raise ValueError("joined lossless normalization display metadata conflicts")
        if evidence["field_order"] != "progressive":
            raise ValueError("joined lossless normalization field order conflicts")
        rate_parts = [int(value) for value in evidence["frame_rate"].split("/", 1)]
        rate_num, rate_den = (rate_parts[0], 1) if len(rate_parts) == 1 else rate_parts
        if evidence["timeline_rule"] != "settb=expr=%d/%d,setpts=N,setsar=%s" % (rate_den, rate_num, evidence["sample_aspect_ratio"].replace(":", "/")):
            raise ValueError("joined lossless normalization timeline rule conflicts")
        positive_joined_int(evidence["source_decoded_frames"], "source_decoded_frames")
        positive_joined_int(evidence["output_decoded_frames"], "output_decoded_frames")
        positive_joined_int(evidence["output_limit_bytes"], "output_limit_bytes")
        if evidence["output_limit_bytes"] > JOINED_MAX_BYTES:
            raise ValueError("joined lossless normalization output limit conflicts")
        if media_size is not None and (isinstance(media_size, bool) or not isinstance(media_size, int) or media_size <= 0 or media_size >= evidence["output_limit_bytes"]):
            raise ValueError("joined lossless normalization output limit conflicts with delivered media size")
        valid_sha256(evidence["decoded_frame_sequence_sha256"], "lossless decoded frame sequence")
        valid_sha256(evidence["decoded_frame_field_sha256"], "lossless decoded frame field proof")
        valid_sha256(evidence["source_timeline_signature_sha256"], "lossless source timeline")
        valid_sha256(evidence["trigger_failure_sha256"], "lossless stream-copy failure")
        if not isinstance(evidence["trigger_failure_facts"], dict) or not evidence["trigger_failure_facts"] or joined_canonical_sha(evidence["trigger_failure_facts"]) != evidence["trigger_failure_sha256"]:
            raise ValueError("joined lossless normalization trigger evidence conflicts")
        rejected = evidence["trigger_failure_facts"]
        rejected_fields = strict_fields | {"decoded_frame_sequence_status"}
        exact_joined_fields(rejected, rejected_fields, "rejected stream-copy verification")
        if (rejected["status"] != "failed" or rejected["decoded_frame_sequence_status"] != "failed" or
                any(rejected[key] != "" for key in rejected_fields - {"status", "decoded_frame_sequence_status", "source_fingerprint", "output_fingerprint"})):
            raise ValueError("joined lossless normalization rejected stream-copy status conflicts")
        valid_media_fingerprint(rejected["source_fingerprint"], False)
        valid_media_fingerprint(rejected["output_fingerprint"], False)
        valid_sha256(rejected["source_fingerprint"].get("decoded_video_sha256"), "rejected source decoded video")
        valid_sha256(rejected["output_fingerprint"].get("decoded_video_sha256"), "rejected output decoded video")
        if rejected["source_fingerprint"] != expected:
            raise ValueError("joined lossless normalization rejected source fingerprint conflicts")
        if rejected_video_stream_copy_equivalent(rejected["source_fingerprint"], rejected["output_fingerprint"], False) or rejected_video_stream_copy_equivalent(rejected["source_fingerprint"], rejected["output_fingerprint"], True):
            raise ValueError("joined lossless normalization trigger did not reject both stream-copy modes")
        if set(expected["tracks"]) != {"video"} or set(actual["tracks"]) != {"video"}:
            raise ValueError("joined lossless normalization audio evidence conflicts")
        want_video, got_video = expected["tracks"]["video"], actual["tracks"]["video"]
        if (evidence["source_decoded_frames"] != want_video["decoded_frames"] or
                evidence["output_decoded_frames"] != got_video["decoded_frames"] or
                want_video["decoded_frames"] != got_video["decoded_frames"]):
            raise ValueError("joined lossless normalization frame evidence conflicts")
        frame_field_payload = "all_frames_match_explicit_progressive_layout|%d\n" % evidence["source_decoded_frames"]
        if (evidence["decoded_frame_field_status"] != "all_frames_match_explicit_progressive_layout" or
                hashlib.sha256(frame_field_payload.encode("ascii")).hexdigest() != evidence["decoded_frame_field_sha256"]):
            raise ValueError("joined lossless normalization decoded frame field evidence conflicts")
        for fingerprint in (expected, actual):
            valid_sha256(fingerprint.get("decoded_video_sha256"), "decoded video")
            if fingerprint["decoded_video_sha256"] != evidence["decoded_frame_sequence_sha256"]:
                raise ValueError("joined lossless normalization decoded video sequence conflicts")
    for media_type, want in expected["tracks"].items():
        got = actual["tracks"][media_type]
        comparable = (("decoded_frames",) if normalized else (("packet_count", "packet_chain_sha256", "decoded_frames") if relaxed else (
            "packet_time_bases", "packet_duration_seconds", "first_packet_pts_seconds", "last_packet_pts_seconds",
            "first_packet_dts_seconds", "last_packet_dts_seconds", "packet_count", "packet_chain_sha256",
            "packet_timing_sha256", "decoded_frames",
        ))) + (("decoded_samples",) if media_type == "audio" else ())
        if want["timestamp_status"] != "source_clips_independent" or any(want[key] != got[key] for key in comparable):
            raise ValueError("joined media fingerprint sequence conflicts")
    for key in ("effective_audio_bytes", "effective_audio_sample_frames", "effective_audio_sha256"):
        if expected.get(key) != actual.get(key):
            raise ValueError("joined decoded audio fingerprint conflicts")
    if expected.get("audio_sequence_contracts"):
        source_format = expected["audio_sequence_contracts"][0]
        output_contracts = actual.get("audio_sequence_contracts", [])
        format_fields = ("codec_name", "sample_rate", "channels", "channel_layout")
        if len(output_contracts) != 1 or any(source_format[key] != output_contracts[0][key] for key in format_fields):
            raise ValueError("joined effective audio format conflicts")



def valid_aac_padding_source_claims(verification, run_sources):
    sources = verification["audio_padding_normalization"]["sources"]
    if len(sources) != len(run_sources):
        raise ValueError("joined AAC source evidence cardinality conflicts")
    for evidence, source in zip(sources, run_sources):
        if evidence["clip_id"] != source["clip_id"] or evidence["source_claim_sha256"] != source_claim_sha([source]):
            raise ValueError("joined AAC source claim conflicts")


def valid_hour_manifest_schema(schema_version, has_aac_padding):
    if schema_version != (2 if has_aac_padding else 1):
        raise ValueError("joined hour schema does not match AAC acceptance mode")


def valid_hour_manifest(payload, item=None):
    fields = {
        "schema_version", "policy_version", "status", "batch_id", "hour_id", "recording_id", "timezone",
        "local_date", "delivery_hour", "clock_hour", "scheduled_start_utc", "scheduled_end_utc",
        "qualification_day", "qualification_sha256", "allocation", "media_tool", "source_claim_sha256",
        "source_count", "sources", "source_dispositions", "gaps", "scheduled_gap", "quarantine_reason_code",
        "quarantine_evidence", "media",
    }
    exact_joined_fields(payload, fields, "hour manifest")
    batch_id, hour_id = payload["batch_id"], payload["hour_id"]
    if payload["schema_version"] not in (1, 2) or payload["policy_version"] != "joined-delivery-v1" or not isinstance(batch_id, str) or JOINED_BATCH.fullmatch(batch_id) is None or not valid_joined_hour_id(batch_id, hour_id):
        raise ValueError("joined hour manifest identity is invalid")
    recording_id = positive_joined_int(payload["recording_id"], "recording_id")
    local_date = valid_joined_date(payload["local_date"])
    delivery_hour = positive_joined_int(payload["delivery_hour"], "delivery_hour")
    if delivery_hour > 12 or payload["clock_hour"] != delivery_hour + 7:
        raise ValueError("joined hour manifest clock identity conflicts")
    expected_hour = "%s__recording-%d__date-%s__hour-%02d__generation-" % (batch_id, recording_id, local_date, delivery_hour)
    if not hour_id.startswith(expected_hour):
        raise ValueError("joined hour manifest hour identity conflicts")
    try:
        location = ZoneInfo(payload["timezone"])
    except (TypeError, ZoneInfoNotFoundError) as exc:
        raise ValueError("joined hour timezone is invalid") from exc
    if (
        joined_timestamp_nanoseconds(payload["scheduled_start_utc"], "scheduled_start_utc") != local_boundary_nanoseconds(local_date, location, delivery_hour + 7)
        or joined_timestamp_nanoseconds(payload["scheduled_end_utc"], "scheduled_end_utc") != local_boundary_nanoseconds(local_date, location, delivery_hour + 8)
    ):
        raise ValueError("joined hour manifest schedule conflicts")
    valid_qualification_day(payload["qualification_day"], recording_id, payload["timezone"], local_date)
    valid_sha256(payload["qualification_sha256"], "qualification")
    valid_media_tool(payload["media_tool"])
    allocation_fields = {
        "artifact_id", "relative_path", "object_key", "size_bytes", "sha256", "ledger_sha256",
        "hour_source_claim_sha256", "boundaries", "cross_day_boundaries",
    }
    allocation = exact_joined_fields(payload["allocation"], allocation_fields, "hour allocation")
    positive_joined_int(allocation["artifact_id"], "allocation artifact_id")
    want_ledger_path = "coverage/ledgers/%d/%s.json" % (recording_id, local_date)
    if valid_joined_relative_path(allocation["relative_path"], ".json") != want_ledger_path or allocation["object_key"] != "joined/%s/%s" % (batch_id, want_ledger_path):
        raise ValueError("joined hour allocation path conflicts")
    if positive_joined_int(allocation["size_bytes"], "allocation size_bytes") > JOINED_MANIFEST_MAX_BYTES:
        raise ValueError("joined hour allocation exceeds JSON size cap")
    for key in ("sha256", "ledger_sha256", "hour_source_claim_sha256"):
        valid_sha256(allocation[key], "hour allocation")
    if not isinstance(allocation["boundaries"], list) or not isinstance(allocation["cross_day_boundaries"], list):
        raise ValueError("joined hour allocation boundaries are invalid")
    for boundary in allocation["boundaries"]:
        valid_boundary(boundary)
    for boundary in allocation["cross_day_boundaries"]:
        valid_boundary(boundary, cross_day=True)
    source_count = positive_joined_int(payload["source_count"], "source_count", allow_zero=True)
    if not isinstance(payload["sources"], list) or len(payload["sources"]) != source_count:
        raise ValueError("joined hour manifest source count conflicts")
    source_ids = [valid_source(source, recording_id, location=location, local_date=local_date) for source in payload["sources"]]
    for previous, following in zip(payload["sources"], payload["sources"][1:]):
        if (joined_timestamp_nanoseconds(following["start_utc"], "source start"), following["clip_id"]) <= (joined_timestamp_nanoseconds(previous["start_utc"], "source start"), previous["clip_id"]):
            raise ValueError("joined hour manifest source order conflicts")
    valid_derived_source_seams(payload["sources"])
    storage_ids = {
        tuple(source[key] for key in ("provider", "endpoint", "region", "bucket"))
        + tuple(source["object"].get(key, "") for key in ("key", "version_id", "etag"))
        for source in payload["sources"]
    }
    if len(source_ids) != len(set(source_ids)) or len(storage_ids) != len(source_ids) or source_claim_sha(payload["sources"]) != payload["source_claim_sha256"] or payload["source_claim_sha256"] != allocation["hour_source_claim_sha256"]:
        raise ValueError("joined hour manifest source claim conflicts")
    disposition_fields = {"clip_id", "disposition", "media_artifact_id", "media_ordinal", "reason_code"}
    if not isinstance(payload["source_dispositions"], list) or len(payload["source_dispositions"]) != source_count:
        raise ValueError("joined hour manifest dispositions conflict")
    included, quarantined = {}, {}
    for clip_id, disposition in zip(source_ids, payload["source_dispositions"]):
        exact_joined_fields(disposition, disposition_fields, "source disposition")
        if disposition["clip_id"] != clip_id:
            raise ValueError("joined source disposition order conflicts")
        if disposition["disposition"] == "included":
            positive_joined_int(disposition["media_artifact_id"], "disposition media_artifact_id")
            positive_joined_int(disposition["media_ordinal"], "disposition media_ordinal")
            if disposition["reason_code"] != "":
                raise ValueError("joined included source has a quarantine reason")
            included[clip_id] = (disposition["media_artifact_id"], disposition["media_ordinal"])
        elif disposition["disposition"] == "quarantined":
            if disposition["media_artifact_id"] != 0 or disposition["media_ordinal"] != 0:
                raise ValueError("joined quarantined source references media")
            valid_joined_reason(disposition["reason_code"], "source quarantine")
            quarantined[clip_id] = disposition["reason_code"]
        else:
            raise ValueError("joined source disposition is invalid")
    gap_fields = {"previous_clip_id", "next_clip_id", "at_utc", "signed_gap_nanoseconds", "reason"}
    if not isinstance(payload["gaps"], list):
        raise ValueError("joined hour gaps are invalid")
    gap_pairs = set()
    gap_reasons = {}
    last_gap_position = -1
    for gap in payload["gaps"]:
        exact_joined_fields(gap, gap_fields, "hour gap")
        positive_joined_int(gap["previous_clip_id"], "gap previous_clip_id")
        positive_joined_int(gap["next_clip_id"], "gap next_clip_id")
        valid_joined_timestamp(gap["at_utc"], "gap at_utc")
        valid_joined_int64(gap["signed_gap_nanoseconds"], "hour gap duration")
        valid_joined_reason(gap["reason"], "hour gap")
        try:
            position = source_ids.index(gap["next_clip_id"])
        except ValueError as exc:
            raise ValueError("joined hour gap source identity conflicts") from exc
        next_seam = payload["sources"][position]["seam_to_previous"] if position else None
        quarantine_boundary = gap["previous_clip_id"] in quarantined or gap["next_clip_id"] in quarantined
        if (
            position == 0 or source_ids[position - 1] != gap["previous_clip_id"]
            or gap["at_utc"] != payload["sources"][position - 1]["end_utc"]
            or gap["signed_gap_nanoseconds"] != next_seam["signed_gap_nanoseconds"]
            or gap["signed_gap_nanoseconds"] != joined_timestamp_nanoseconds(payload["sources"][position]["start_utc"], "gap next start") - joined_timestamp_nanoseconds(payload["sources"][position - 1]["end_utc"], "gap previous end")
            or (gap["reason"] != next_seam["reason"] and not (quarantine_boundary and gap["reason"] == "source_quarantined"))
        ):
            raise ValueError("joined hour gap evidence conflicts")
        pair = (gap["previous_clip_id"], gap["next_clip_id"])
        if pair in gap_pairs:
            raise ValueError("joined hour gap evidence is duplicated")
        if position <= last_gap_position:
            raise ValueError("joined hour gaps are not in source order")
        last_gap_position = position
        gap_pairs.add(pair)
        gap_reasons[pair] = gap["reason"]
    quarantine_fields = {
        "reason_code", "source_clip_ids", "source_claim_sha256", "policy_version", "normalized_failure_facts",
        "failure_sha256", "evidence_sha256", "isolated_attempt_count", "media_tool_identity",
    }
    if not isinstance(payload["quarantine_evidence"], list):
        raise ValueError("joined quarantine evidence is invalid")
    evidenced = {}
    for evidence in payload["quarantine_evidence"]:
        exact_joined_fields(evidence, quarantine_fields, "quarantine evidence")
        valid_joined_reason(evidence["reason_code"], "quarantine evidence")
        ids = evidence["source_clip_ids"]
        if not isinstance(ids, list) or not ids or any(isinstance(value, bool) or not isinstance(value, int) or value < 1 for value in ids):
            raise ValueError("joined quarantine evidence sources are invalid")
        subset = [payload["sources"][source_ids.index(clip_id)] for clip_id in ids if clip_id in source_ids]
        if len(subset) != len(ids) or len(set(ids)) != len(ids) or candidate_source_claim_sha(subset) != evidence["source_claim_sha256"]:
            raise ValueError("joined quarantine source claim conflicts")
        if evidence["policy_version"] != payload["policy_version"] or evidence["media_tool_identity"] != payload["media_tool"]["identity_sha256"] or evidence["isolated_attempt_count"] != 2 or not isinstance(evidence["normalized_failure_facts"], dict) or not evidence["normalized_failure_facts"]:
            raise ValueError("joined quarantine evidence conflicts")
        if joined_canonical_sha(evidence["normalized_failure_facts"]) != evidence["failure_sha256"]:
            raise ValueError("joined quarantine failure hash conflicts")
        proof = {
            "source_claim_sha256": evidence["source_claim_sha256"], "reason_code": evidence["reason_code"],
            "failure_sha256": evidence["failure_sha256"], "policy_version": evidence["policy_version"],
            "media_tool_identity": evidence["media_tool_identity"], "repeat_count": evidence["isolated_attempt_count"],
        }
        if joined_canonical_sha(proof) != evidence["evidence_sha256"]:
            raise ValueError("joined quarantine evidence hash conflicts")
        for clip_id in ids:
            if clip_id in evidenced:
                raise ValueError("joined quarantine evidence overlaps")
            evidenced[clip_id] = evidence["reason_code"]
    if evidenced != quarantined:
        raise ValueError("joined quarantine evidence does not exactly cover quarantined sources")
    media_fields = {
        "artifact_id", "ordinal", "part", "parts", "relative_path", "object_key", "content_id", "size_bytes",
        "sha256", "actual_start_utc", "actual_end_utc", "utc_offset_seconds", "media_tool_identity",
        "source_clip_ids", "verification", "maximality_evidence",
    }
    if not isinstance(payload["media"], list):
        raise ValueError("joined hour media is invalid")
    seen_media, media_sources = set(), []
    has_aac_padding = False
    for ordinal, media in enumerate(payload["media"], 1):
        exact_joined_fields(media, media_fields, "hour media")
        artifact_id = positive_joined_int(media["artifact_id"], "media artifact_id")
        if artifact_id in seen_media or media["ordinal"] != ordinal or media["part"] != ordinal or media["parts"] != len(payload["media"]):
            raise ValueError("joined hour media order conflicts")
        seen_media.add(artifact_id)
        path = valid_joined_relative_path(media["relative_path"], ".mp4")
        if media["object_key"] != "joined/%s/objects/%s.mp4" % (batch_id, media["content_id"]):
            raise ValueError("joined hour media object identity conflicts")
        size_bytes = positive_joined_int(media["size_bytes"], "media size_bytes")
        if size_bytes > JOINED_MAX_BYTES:
            raise ValueError("joined hour media exceeds size cap")
        sha256 = valid_sha256(media["sha256"], "hour media")
        if media["content_id"] != sha256 or media["media_tool_identity"] != payload["media_tool"]["identity_sha256"]:
            raise ValueError("joined hour media content identity conflicts")
        actual_start = valid_joined_timestamp(media["actual_start_utc"], "actual_start_utc")
        valid_joined_timestamp(media["actual_end_utc"], "actual_end_utc")
        offset = actual_start.astimezone(location).utcoffset()
        expected_offset = int(offset.total_seconds()) if offset is not None else None
        if (
            joined_timestamp_nanoseconds(media["actual_end_utc"], "actual_end_utc") <= joined_timestamp_nanoseconds(media["actual_start_utc"], "actual_start_utc")
            or not -86400 < valid_joined_int64(media["utc_offset_seconds"], "media UTC offset") < 86400
            or media["utc_offset_seconds"] != expected_offset
        ):
            raise ValueError("joined hour media timing conflicts")
        ids = media["source_clip_ids"]
        if not isinstance(ids, list) or not ids or len(ids) != len(set(ids)) or any(included.get(clip_id) != (artifact_id, ordinal) for clip_id in ids):
            raise ValueError("joined hour media source membership conflicts")
        positions = [source_ids.index(clip_id) for clip_id in ids]
        if positions != list(range(positions[0], positions[0] + len(positions))):
            raise ValueError("joined hour media crosses a non-member source")
        run_sources = [payload["sources"][position] for position in positions]
        if media["actual_start_utc"] != run_sources[0]["start_utc"] or media["actual_end_utc"] != run_sources[-1]["end_utc"]:
            raise ValueError("joined hour media range conflicts with its exact sources")
        for previous, following in zip(run_sources, run_sources[1:]):
            if (previous["clip_id"], following["clip_id"]) in gap_pairs:
                raise ValueError("joined hour media crosses a gap or non-continuous seam")
        media_sources.extend(ids)
        valid_verification(media["verification"], media["size_bytes"])
        if media["verification"].get("acceptance_mode") == "video_frame_exact_audio_padding_normalized":
            has_aac_padding = True
            valid_aac_padding_source_claims(media["verification"], run_sources)
        if media["verification"].get("acceptance_mode") == "lossless_native_timeline_normalized" and len(ids) < 2:
            raise ValueError("joined lossless normalization requires multiple sources")
        source_fingerprint = media["verification"]["source_fingerprint"]
        audio_contracts = [source["audio_sequence_contract"] for source in run_sources if "audio_sequence_contract" in source]
        if (
            ("audio" not in source_fingerprint["tracks"] and audio_contracts)
            or ("audio" in source_fingerprint["tracks"] and (
                len(audio_contracts) != len(run_sources)
                or audio_contracts != source_fingerprint["audio_sequence_contracts"]
            ))
        ):
            raise ValueError("joined source audio contracts conflict with verification")
        if not isinstance(media["maximality_evidence"], list):
            raise ValueError("joined media maximality evidence is invalid")
        for evidence in media["maximality_evidence"]:
            exact_joined_fields(evidence, {"candidate_clip_ids", "reason_code", "source_claim_sha256", "policy_version", "evidence_sha256", "normalized_failure_facts", "failure_sha256", "repeat_count", "media_tool_identity"}, "maximality evidence")
            valid_joined_reason(evidence["reason_code"], "maximality evidence")
            ids = evidence["candidate_clip_ids"]
            candidates = [payload["sources"][source_ids.index(clip_id)] for clip_id in ids if clip_id in source_ids]
            if not isinstance(ids, list) or not ids or len(candidates) != len(ids) or len(set(ids)) != len(ids) or candidate_source_claim_sha(candidates) != evidence["source_claim_sha256"] or evidence["policy_version"] != payload["policy_version"] or evidence["media_tool_identity"] != payload["media_tool"]["identity_sha256"] or not isinstance(evidence["normalized_failure_facts"], dict) or not evidence["normalized_failure_facts"]:
                raise ValueError("joined maximality evidence conflicts")
            if joined_canonical_sha(evidence["normalized_failure_facts"]) != evidence["failure_sha256"]:
                raise ValueError("joined maximality failure hash conflicts")
            repeat_count = 1 if evidence["reason_code"] in {"output_exceeds_put_cap", "lossless_normalization_expansion_cap"} else 2
            proof = {
                "source_claim_sha256": evidence["source_claim_sha256"], "reason_code": evidence["reason_code"],
                "failure_sha256": evidence["failure_sha256"], "policy_version": evidence["policy_version"],
                "media_tool_identity": evidence["media_tool_identity"], "repeat_count": evidence["repeat_count"],
            }
            if evidence["repeat_count"] != repeat_count or joined_canonical_sha(proof) != evidence["evidence_sha256"]:
                raise ValueError("joined maximality evidence hash conflicts")
        if media["maximality_evidence"]:
            first_length = len(media["maximality_evidence"][0]["candidate_clip_ids"])
            for evidence_index, evidence in enumerate(media["maximality_evidence"]):
                candidate_ids = evidence["candidate_clip_ids"]
                expected_length = first_length - evidence_index
                if (
                    len(candidate_ids) != expected_length or len(candidate_ids) <= len(media["source_clip_ids"])
                    or positions[0] + len(candidate_ids) > len(source_ids)
                    or candidate_ids != source_ids[positions[0]:positions[0] + len(candidate_ids)]
                ):
                    raise ValueError("joined maximality peel order conflicts")
            adjacent = media["maximality_evidence"][-1]["candidate_clip_ids"]
            if adjacent[:-1] != media["source_clip_ids"] or positions[-1] + 1 >= len(source_ids) or adjacent[-1] != source_ids[positions[-1] + 1]:
                raise ValueError("joined maximality evidence is not the immediate source extension")
    valid_hour_manifest_schema(payload["schema_version"], has_aac_padding)
    if media_sources != [clip_id for clip_id in source_ids if clip_id in included]:
        raise ValueError("joined media does not exactly cover included sources")
    broken = 0
    sources_by_id = {source["clip_id"]: source for source in payload["sources"]}
    media_by_id = {media["artifact_id"]: media for media in payload["media"]}
    for previous, following in zip(source_ids, source_ids[1:]):
        same_media = previous in included and following in included and included[previous][0] == included[following][0]
        has_gap = (previous, following) in gap_pairs
        if same_media == has_gap:
            raise ValueError("joined hour gaps do not exactly cover media run boundaries")
        if same_media:
            if sources_by_id[following]["seam_to_previous"]["verdict"] != "continuous":
                raise ValueError("joined continuous media run seam conflicts")
            continue
        broken += 1
        seam = sources_by_id[following]["seam_to_previous"]
        signed_gap = seam["signed_gap_nanoseconds"]
        if previous in quarantined or following in quarantined:
            if gap_reasons[(previous, following)] != "source_quarantined":
                raise ValueError("joined quarantine boundary reason conflicts")
        elif signed_gap > 0:
            if seam["verdict"] != "gap":
                raise ValueError("joined signed gap verdict conflicts")
        elif signed_gap < 0:
            if seam["verdict"] != "overlap":
                raise ValueError("joined signed overlap verdict conflicts")
        else:
            previous_media = media_by_id.get(included.get(previous, (0, 0))[0])
            evidence = previous_media["maximality_evidence"][-1] if previous_media and previous_media["maximality_evidence"] else None
            if (
                seam["verdict"] != "incompatible" or evidence is None
                or previous_media["source_clip_ids"][-1] != previous
                or evidence["reason_code"] != seam["reason"]
                or evidence["candidate_clip_ids"][-1] != following
            ):
                raise ValueError("joined zero-duration split lacks typed maximality evidence")
    if broken != len(gap_pairs):
        raise ValueError("joined hour gap count conflicts with media runs")
    status = payload["status"]
    if status == "media":
        if not source_ids or not payload["media"] or payload["scheduled_gap"] is not None or payload["quarantine_reason_code"] != "":
            raise ValueError("joined media hour terminal state conflicts")
    elif status == "gap_only":
        exact_joined_fields(payload["scheduled_gap"], {"reason_code", "signed_gap_nanoseconds", "no_allocatable_sources"}, "scheduled gap")
        if source_ids or payload["media"] or payload["quarantine_evidence"] or payload["quarantine_reason_code"] != "" or payload["scheduled_gap"]["no_allocatable_sources"] is not True:
            raise ValueError("joined gap-only hour terminal state conflicts")
        valid_joined_reason(payload["scheduled_gap"]["reason_code"], "scheduled gap")
        if payload["scheduled_gap"]["signed_gap_nanoseconds"] != 3_600_000_000_000:
            raise ValueError("joined scheduled gap duration conflicts")
    elif status == "quarantine_only":
        valid_joined_reason(payload["quarantine_reason_code"], "quarantine-only hour")
        if not source_ids or payload["media"] or payload["scheduled_gap"] is not None or not payload["quarantine_evidence"] or set(source_ids) != set(quarantined):
            raise ValueError("joined quarantine-only hour terminal state conflicts")
    else:
        raise ValueError("joined hour manifest has unknown status")
    if item is not None:
        if batch_id != item["batch_id"] or hour_id != item["hour_id"]:
            raise ExistingFileMismatch("joined hour manifest identity conflicts")
        if item["kind"] == "media":
            matches = [media for media in payload["media"] if media["artifact_id"] == item["id"]]
            if len(matches) != 1 or matches[0]["relative_path"] != item["relative_path"] or matches[0]["size_bytes"] != item["size_bytes"] or matches[0]["sha256"] != item["sha256"]:
                raise ExistingFileMismatch("joined media conflicts with sealed hour manifest")
    return payload


def read_joined_content(cfg, runtime, directory_fd, name, limit, stop_event):
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    descriptor = os.open(name, flags, dir_fd=directory_fd)
    content = bytearray()
    digest = hashlib.sha256()
    started = time.monotonic()
    try:
        before = os.fstat(descriptor)
        if not stat_module.S_ISREG(before.st_mode) or before.st_nlink not in (1, 2):
            raise ExistingFileMismatch("joined hour manifest has an unknown hardlink")
        while True:
            if stop_event.is_set():
                raise JoinedDownloadYield("joined manifest validation stopped at a read boundary")
            if runtime.joined_fair_share_enabled():
                await_joined_work(cfg, runtime, stop_event)
            chunk = os.read(descriptor, min(JOINED_RANGE_BYTES, limit + 1 - len(content)))
            if not chunk:
                break
            content.extend(chunk)
            digest.update(chunk)
            throttle_joined_io(started, len(content), JOINED_HASH_BYTES_PER_SEC, stop_event)
            if len(content) > limit:
                raise ValueError("joined JSON artifact is too large")
        after = os.fstat(descriptor)
        path_after = joined_entry_stat(directory_fd, name)
        if path_after is None or certification_identity(before) != certification_identity(after) or certification_identity(after) != certification_identity(path_after):
            raise FileChangedDuringHash("joined hour manifest changed while reading")
    finally:
        os.close(descriptor)
    return bytes(content), digest.hexdigest()


def read_joined_manifest(cfg, runtime, directory_fd, name, expected_sha, item, stop_event):
    content, digest = read_joined_content(
        cfg, runtime, directory_fd, name, JOINED_MANIFEST_MAX_BYTES, stop_event,
    )
    if digest != expected_sha:
        raise ExistingFileMismatch("joined hour manifest checksum conflicts")
    return valid_hour_manifest(decode_joined_json(content), item)


def read_joined_json_path(cfg, runtime, batch_id, relative_path, expected_size, expected_sha, stop_event):
    joined_raw_priority_checkpoint(cfg, runtime, stop_event)
    holder = {"batch_id": batch_id, "relative_path": relative_path}
    directory_fd = open_joined_output_dir(cfg, holder, create=False)
    try:
        content, digest = read_joined_content(
            cfg, runtime, directory_fd, Path(relative_path).name, JOINED_MANIFEST_MAX_BYTES, stop_event,
        )
    finally:
        os.close(directory_fd)
    if len(content) != expected_size or digest != expected_sha:
        raise ExistingFileMismatch("joined JSON reference conflicts: %s" % relative_path)
    return decode_joined_json(content)


def expected_hour_boundaries(ledger, delivery_hour):
    boundaries = []
    cross_day = []
    if delivery_hour > 1:
        boundaries.append(ledger["cross_hour_boundaries"][delivery_hour - 2])
    if delivery_hour < 12:
        boundaries.append(ledger["cross_hour_boundaries"][delivery_hour - 1])
    if delivery_hour == 1:
        cross_day.append(ledger["cross_day_boundaries"][0])
    if delivery_hour == 12:
        cross_day.append(ledger["cross_day_boundaries"][1])
    return boundaries, cross_day


def validate_hour_against_ledger(manifest, ledger, ledger_artifact_id, ledger_relative_path, ledger_size, ledger_sha):
    allocation = manifest["allocation"]
    if (
        ledger["batch_id"] != manifest["batch_id"] or ledger["recording_id"] != manifest["recording_id"]
        or ledger["local_date"] != manifest["local_date"] or ledger["qualification_sha256"] != manifest["qualification_sha256"]
        or ledger["qualification_day"] != manifest["qualification_day"]
        or allocation["artifact_id"] != ledger_artifact_id or allocation["relative_path"] != ledger_relative_path
        or allocation["size_bytes"] != ledger_size or allocation["sha256"] != ledger_sha
        or allocation["ledger_sha256"] != ledger["ledger_sha256"]
    ):
        raise ExistingFileMismatch("joined hour allocation conflicts with installed ledger")
    delivery_hour = manifest["delivery_hour"]
    hour = ledger["hours"][delivery_hour - 1]
    ledger_sources = []
    by_id = {source["clip_id"]: source for source in ledger["sources"]}
    for clip_id in hour["source_clip_ids"]:
        if clip_id not in by_id:
            raise ExistingFileMismatch("joined hour source is absent from installed ledger")
        ledger_sources.append(by_id[clip_id])
    if (
        [source["clip_id"] for source in manifest["sources"]] != hour["source_clip_ids"]
        or [source_claim_projection(source) for source in manifest["sources"]] != [source_claim_projection(source) for source in ledger_sources]
        or manifest["source_claim_sha256"] != ledger["hour_source_claim_sha256"][delivery_hour - 1]
        or allocation["hour_source_claim_sha256"] != manifest["source_claim_sha256"]
    ):
        raise ExistingFileMismatch("joined hour source claim conflicts with installed ledger")
    boundaries, cross_day = expected_hour_boundaries(ledger, delivery_hour)
    if allocation["boundaries"] != boundaries or allocation["cross_day_boundaries"] != cross_day:
        raise ExistingFileMismatch("joined hour boundary evidence conflicts with installed ledger")


def validate_cross_day_ledger_link(previous, following):
    if any(previous[key] != following[key] for key in ("batch_id", "generation", "recording_id", "timezone")):
        raise ExistingFileMismatch("joined consecutive ledger scope conflicts")
    fields = (
        "previous_clip_id", "next_clip_id", "previous_presentation_end_utc", "next_presentation_start_utc",
        "signed_gap_nanoseconds", "scheduled_previous_end_utc", "scheduled_next_start_utc",
        "boundary_skew_nanoseconds", "verdict",
    )
    previous_right = previous["cross_day_boundaries"][1]
    following_left = following["cross_day_boundaries"][0]
    if any(previous_right[field] != following_left[field] for field in fields):
        raise ExistingFileMismatch("joined consecutive ledgers disagree on their shared day boundary")


def validate_hour_ledger_binding(cfg, runtime, item, manifest, stop_event):
    if item["kind"] != "hour_manifest":
        return
    allocation = manifest["allocation"]
    if (
        allocation["artifact_id"] != item["ledger_artifact_id"]
        or allocation["relative_path"] != item["ledger_relative_path"]
        or allocation["sha256"] != item["ledger_sha256"]
    ):
        raise ExistingFileMismatch("joined hour feed lineage conflicts with sealed manifest")
    ledger = read_joined_json_path(
        cfg, runtime, item["batch_id"], item["ledger_relative_path"],
        allocation["size_bytes"], item["ledger_sha256"], stop_event,
    )
    valid_allocation_ledger(ledger)
    validate_hour_against_ledger(
        manifest, ledger, item["ledger_artifact_id"], item["ledger_relative_path"],
        allocation["size_bytes"], item["ledger_sha256"],
    )


def verify_joined_relative_file(cfg, runtime, batch_id, relative_path, size_bytes, sha256, stop_event):
    joined_raw_priority_checkpoint(cfg, runtime, stop_event)
    holder = {"batch_id": batch_id, "relative_path": relative_path}
    directory_fd = open_joined_output_dir(cfg, holder, create=False)
    try:
        if not verify_joined_entry(
            cfg, runtime, directory_fd, Path(relative_path).name, size_bytes, sha256, stop_event,
        ):
            raise ExistingFileMismatch("joined referenced file is missing: %s" % relative_path)
    finally:
        os.close(directory_fd)


def validate_batch_index_proof(cfg, runtime, index, stop_event):
    batch_id = index["batch_id"]
    total_sources = total_bytes = total_media = 0
    max_hour_manifest_schema_version = 1
    seen_media_artifacts = {
        reference["artifact_id"] for reference in index["allocation_ledgers"]
    } | {
        reference["hour_manifest_artifact_id"] for reference in index["hours"]
    }
    seen_media_paths = set()
    denominator_ledgers = []
    qualification_days = []
    previous_ledger = None
    # The compact index is ordered ledger-major and each ledger is immediately
    # followed logically by its exact 12 hour references. Never scan joined/.
    for ledger_position, ledger_ref in enumerate(index["allocation_ledgers"]):
        frozen = index["frozen_recordings"][ledger_position // 14]
        ledger = read_joined_json_path(
            cfg, runtime, batch_id, ledger_ref["relative_path"], ledger_ref["size_bytes"], ledger_ref["sha256"], stop_event,
        )
        valid_allocation_ledger(ledger)
        if (
            ledger["batch_id"] != batch_id or ledger["recording_id"] != ledger_ref["recording_id"]
            or ledger["local_date"] != ledger_ref["local_date"] or ledger["qualification_sha256"] != ledger_ref["qualification_sha256"]
            or ledger["qualification_sha256"] != frozen["qualification_sha256"]
            or ledger["frozen_source_sha256"] != ledger_ref["frozen_source_sha256"]
            or ledger["source_claim_sha256"] != ledger_ref["source_claim_sha256"] or ledger["ledger_sha256"] != ledger_ref["ledger_sha256"]
            or ledger["source_clip_count"] != ledger_ref["source_count"] or ledger["source_bytes"] != ledger_ref["source_bytes"]
            or ledger["generation"] != index["generation"] or ledger["timezone"] != frozen["timezone"]
        ):
            raise ExistingFileMismatch("joined batch ledger reference conflicts")
        if (
            ledger["qualification_day"]["qualification_window_ordinal"] != ledger_position % 14 + 1
            or (index["selection_authority"]["qualification_rule_version"] != TIER1_HISTORICAL_QUALIFICATION_VERSION
                and joined_timestamp_nanoseconds(ledger["qualification_day"]["window_start"], "qualification window_start")
                    < joined_timestamp_nanoseconds(index["selection_authority"]["qualification_run_frozen_at"], "qualification run frozen_at"))
            or joined_timestamp_nanoseconds(ledger["qualification_day"]["completed_at"], "qualification completed_at")
                > joined_timestamp_nanoseconds(index["selection_authority"]["cutoff"], "selection cutoff")
        ):
            raise ExistingFileMismatch("joined batch qualification chronology conflicts")
        qualification_days.append(ledger["qualification_day"])
        if previous_ledger is not None and previous_ledger["recording_id"] == ledger["recording_id"]:
            validate_cross_day_ledger_link(previous_ledger, ledger)
        previous_ledger = ledger
        denominator_ledgers.append(ledger)
        day_dispositions = []
        hour_refs = index["hours"][ledger_position * 12:(ledger_position + 1) * 12]
        for delivery_hour, hour_ref in enumerate(hour_refs, 1):
            manifest = read_joined_json_path(
                cfg, runtime, batch_id, hour_ref["relative_path"], hour_ref["size_bytes"], hour_ref["sha256"], stop_event,
            )
            valid_hour_manifest(manifest)
            max_hour_manifest_schema_version = max(max_hour_manifest_schema_version, manifest["schema_version"])
            if (
                manifest["hour_id"] != hour_ref["hour_id"] or manifest["recording_id"] != hour_ref["recording_id"]
                or manifest["local_date"] != hour_ref["local_date"] or manifest["delivery_hour"] != delivery_hour
                or manifest["status"] != hour_ref["status"] or manifest["source_count"] != hour_ref["source_count"]
                or sum(source["object"]["size_bytes"] for source in manifest["sources"]) != hour_ref["source_bytes"]
                or len(manifest["media"]) != hour_ref["media_artifact_count"]
                or manifest["timezone"] != frozen["timezone"] or manifest["media_tool"] != index["media_tool"]
            ):
                raise ExistingFileMismatch("joined batch hour reference conflicts")
            validate_hour_against_ledger(
                manifest, ledger, ledger_ref["artifact_id"], ledger_ref["relative_path"],
                ledger_ref["size_bytes"], ledger_ref["sha256"],
            )
            day_dispositions.extend(disposition["clip_id"] for disposition in manifest["source_dispositions"])
            for media in manifest["media"]:
                if media["relative_path"] != joined_delivery_path(frozen, media, delivery_hour):
                    raise ExistingFileMismatch("joined batch media delivery path conflicts with frozen naming")
                if media["artifact_id"] in seen_media_artifacts or media["relative_path"] in seen_media_paths:
                    raise ExistingFileMismatch("joined batch media reference is duplicated")
                seen_media_artifacts.add(media["artifact_id"])
                seen_media_paths.add(media["relative_path"])
                verify_joined_relative_file(
                    cfg, runtime, batch_id, media["relative_path"], media["size_bytes"], media["sha256"], stop_event,
                )
                total_media += 1
        if day_dispositions != [source["clip_id"] for source in ledger["sources"]]:
            raise ExistingFileMismatch("joined batch day disposition union conflicts with ledger")
        total_sources += ledger["source_clip_count"]
        total_bytes += ledger["source_bytes"]
        if ledger_position % 14 == 13:
            try:
                qualification_sha = qualification_window_sha(
                    frozen, qualification_days, index["selection_authority"]["cutoff"],
                    index["selection_authority"]["qualification_run_frozen_at"],
                    index["selection_authority"]["qualification_rule_version"],
                )
            except ValueError as exc:
                raise ExistingFileMismatch("joined batch qualification window conflicts") from exc
            if qualification_sha != frozen["qualification_sha256"]:
                raise ExistingFileMismatch("joined batch qualification window seal conflicts")
            qualification_days = []
    if (
        total_sources != index["source_clip_count"] or total_bytes != index["source_bytes"] or index["hour_manifest_schema_version"] != max_hour_manifest_schema_version
        or total_media != index["final_media_artifact_count"]
        or frozen_denominator_sha(index["selection_authority"], index["frozen_recordings"], denominator_ledgers) != index["frozen_denominator_sha256"]
    ):
        raise ExistingFileMismatch("joined batch installed denominator conflicts")


def validate_joined_artifact(cfg, runtime, directory_fd, name, item, stop_event):
    if item["kind"] == "media":
        return
    content, digest = read_joined_content(
        cfg, runtime, directory_fd, name, JOINED_MANIFEST_MAX_BYTES, stop_event,
    )
    if digest != item["sha256"]:
        raise ExistingFileMismatch("joined JSON artifact checksum conflicts")
    payload = decode_joined_json(content)
    if item["kind"] == "allocation_ledger":
        valid_allocation_ledger(payload)
        if payload["batch_id"] != item["batch_id"] or item["relative_path"] != "coverage/ledgers/%d/%s.json" % (payload["recording_id"], payload["local_date"]):
            raise ExistingFileMismatch("joined allocation ledger identity conflicts")
    elif item["kind"] == "hour_manifest":
        valid_hour_manifest(payload, item)
        validate_hour_ledger_binding(cfg, runtime, item, payload, stop_event)
    elif item["kind"] == "batch_index":
        valid_batch_index(payload, item)
        validate_batch_index_proof(cfg, runtime, payload, stop_event)


def validate_media_manifest_binding(cfg, runtime, item, stop_event):
    if item["kind"] != "media":
        return
    manifest_item = {
        "batch_id": item["batch_id"],
        "relative_path": item["hour_manifest_relative_path"],
    }
    directory_fd = open_joined_output_dir(cfg, manifest_item, create=False)
    try:
        read_joined_manifest(
            cfg, runtime, directory_fd, Path(item["hour_manifest_relative_path"]).name,
            item["hour_manifest_sha256"], item, stop_event,
        )
    finally:
        os.close(directory_fd)


def write_joined_stage(directory_fd, name, content):
    flags = (
        os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    descriptor = os.open(name, flags, 0o600, dir_fd=directory_fd)
    try:
        current = os.fstat(descriptor)
        if not stat_module.S_ISREG(current.st_mode) or current.st_nlink != 1:
            raise ExistingFileMismatch("joined sidecar stage is not exclusively owned")
        offset = 0
        while offset < len(content):
            offset += os.write(descriptor, content[offset:])
        os.fsync(descriptor)
        current = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    os.fsync(directory_fd)
    return current


def joined_sidecar_intent(cfg, directory_fd, name, content):
    artifact = json.loads(content)
    marker_path = joined_output_path(cfg, artifact).with_name(name).absolute()
    parent = os.fstat(directory_fd)
    identity = {
        "schema_version": 1, "artifact_id": artifact["id"],
        "marker_path": str(marker_path), "directory_device": parent.st_dev,
        "directory_inode": parent.st_ino, "size_bytes": len(content),
        "sha256": hashlib.sha256(content).hexdigest(),
    }
    key = hashlib.sha256(str(marker_path).encode("utf-8")).hexdigest()
    return cfg.state_dir / ("joined-sidecar-intent-" + key + ".json"), identity


def joined_quarantine_startup_status(cfg):
    # Replay diagnostics only; neither the ledger nor this scan grants authority
    # to mutate NAS files. Scan the whole ledger to match older quarantined names.
    path = cfg.state_dir / "joined-alias-quarantine.jsonl"
    recorded_paths = {}
    unfinished = {}
    problems = []
    malformed = 0
    try:
        descriptor = os.open(str(path), os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
        try:
            current = os.fstat(descriptor)
            if not stat_module.S_ISREG(current.st_mode) or current.st_nlink != 1:
                raise ExistingFileMismatch("joined quarantine ledger is not exclusively owned")
            fcntl.flock(descriptor, fcntl.LOCK_SH)
            with os.fdopen(descriptor, "rb", closefd=False) as ledger:
                for number, line in enumerate(ledger, 1):
                    try:
                        record = json.loads(line)
                        if not line.endswith(b"\n") or not isinstance(record, dict) or not isinstance(record.get("operation"), str):
                            raise ValueError("incomplete or invalid record")
                    except ValueError as exc:
                        malformed += 1
                        if malformed <= 5:
                            log("WARN", "joined quarantine ledger malformed line %d: %s" % (number, exc))
                        continue
                    if record.get("operation") == "alias_move" and isinstance(record.get("new_path"), str):
                        recorded_paths[record["new_path"]] = record
                    if record.get("operation") in ("alias_move", "canonical_copy"):
                        key = json.dumps([
                            record["operation"], record.get("new_path"),
                            record.get("canonical_path"), record.get("temporary_path"),
                        ], sort_keys=True)
                        if record.get("state") == "intent":
                            unfinished[key] = record
                        elif record.get("state") == "complete":
                            unfinished.pop(key, None)
        finally:
            os.close(descriptor)
    except FileNotFoundError:
        pass  # Still inspect quarantine when the ledger is missing.
    except (OSError, ExistingFileMismatch) as exc:
        problems.append("joined quarantine ledger unreadable: %s" % exc)
    if malformed:
        problems.append("joined quarantine ledger malformed lines=%d" % malformed)

    flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
    descriptor = None
    unrecorded = total = 0
    status = {"aliases": [], "pending_recoveries": []}
    detail_bytes = 0

    def add_detail(category, message):
        # Share a byte budget so the complete heartbeat cleanup object stays
        # below the server's 8 KiB limit, even with long paths. Each selected
        # detail also fits one uploaded log line. Counts include omitted items.
        nonlocal detail_bytes
        size = len(json.dumps(message).encode("utf-8"))
        if len(status[category]) < 5 and size <= 1900 and detail_bytes + size <= 5000:
            status[category].append(message)
            detail_bytes += size
            log("WARN", message)

    try:
        descriptor = os.open(str(cfg.output_dir), flags)
        for part in (".stoarama-quarantine", "aliases"):
            child = os.open(part, flags, dir_fd=descriptor)
            os.close(descriptor)
            descriptor = child
        qroot = cfg.output_dir.absolute() / ".stoarama-quarantine" / "aliases"
        for entry in sorted(os.listdir(descriptor)):
            alias = str(qroot / entry)
            total += 1
            record = recorded_paths.get(alias)
            if record is None:
                unrecorded += 1
                message = "joined quarantine unrecorded alias: " + alias
            else:
                message = "joined quarantine alias: %s -> %s inode=%s size=%s reason=%s" % (
                    record.get("old_path", "unknown"), alias, record.get("inode", "unknown"),
                    record.get("size_bytes", "unknown"), record.get("reason", "unknown"),
                )
            add_detail("aliases", message)
    except FileNotFoundError:
        pass
    except OSError as exc:
        problems.append("joined quarantine directory unreadable: %s" % exc)
    finally:
        if descriptor is not None:
            os.close(descriptor)
    pending = 0
    for record in unfinished.values():
        pending += 1
        add_detail("pending_recoveries", "joined quarantine pending recovery: " + json.dumps(record, sort_keys=True))
    for journal in sorted(cfg.state_dir.glob("joined-sidecar-intent-*.json")):
        pending += 1
        add_detail("pending_recoveries", "joined sidecar pending recovery: " + journal.name)
    if not (total or pending or problems):
        return "", None, {}
    status.update(alias_count=total, unrecorded_count=unrecorded, pending_recovery_count=pending,
                  aliases_omitted=total - len(status["aliases"]),
                  pending_recoveries_omitted=pending - len(status["pending_recoveries"]))
    summary = "joined quarantine ledger replay: aliases=%d pending recoveries=%d" % (total, pending)
    if unrecorded:
        summary += " unrecorded aliases=%d" % unrecorded
    summary += "; listed aliases=%d pending=%d; omitted aliases=%d pending=%d (up to 5 each, byte bounded)" % (
        len(status["aliases"]), len(status["pending_recoveries"]),
        status["aliases_omitted"], status["pending_recoveries_omitted"],
    )
    # The short error directs operators to the complete bounded detail lists.
    notice = "; ".join([summary] + problems)
    suffix = "; details in heartbeat cleanup.joined_quarantine and uploaded log"
    notice = notice.encode("utf-8")[:1000 - len(suffix)].decode("utf-8", "ignore") + suffix
    return notice, utc_now(), status


def append_joined_quarantine_ledger(cfg, record):
    """Fsync intent before NAS mutations, and completion afterwards; never rewrite."""
    path = cfg.state_dir / "joined-alias-quarantine.jsonl"
    flags = os.O_RDWR | os.O_APPEND | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0)
    descriptor = os.open(str(path), flags, 0o600)
    try:
        fcntl.flock(descriptor, fcntl.LOCK_EX)
        current = os.fstat(descriptor)
        if not stat_module.S_ISREG(current.st_mode) or current.st_nlink != 1:
            raise ExistingFileMismatch("joined quarantine ledger is not exclusively owned")

        def write_line(data):
            # Never resume a short write: it is a torn record, and the next
            # append must frame it off before any new intent can authorize a move.
            if os.write(descriptor, data) != len(data):
                raise OSError(errno.EIO, "short joined quarantine ledger write")
            os.fsync(descriptor)

        if current.st_size and os.pread(descriptor, 1, current.st_size - 1) != b"\n":
            write_line(b"\n")
            recovery = {"operation": "torn_tail_recovered", "recorded_at": utc_now()}
            write_line((json.dumps(recovery, sort_keys=True) + "\n").encode("utf-8"))
        data = (json.dumps(dict(record, recorded_at=utc_now()), sort_keys=True) + "\n").encode("utf-8")
        write_line(data)
    finally:
        os.close(descriptor)
    fsync_dir(cfg.state_dir)


def report_joined_quarantine(runtime, message):
    # Keep the notice visible after successful joined/raw delivery clears errors.
    if runtime is None:
        # Local stitch publication shares the durable alias ledger. Its lane
        # has no delivery Runtime; retain the live notice in stitch telemetry.
        STITCH_STATUS.fail(message[:1000])
    else:
        with runtime.lock:
            runtime.joined_quarantine_notice = message[:1000]
            runtime.joined_quarantine_notice_at = utc_now()
    log("WARN", message)


def open_joined_quarantine(cfg, directory_fd):
    flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
    descriptor = os.open(str(cfg.output_dir), flags)
    device = os.fstat(directory_fd).st_dev
    try:
        if os.fstat(descriptor).st_dev != device:
            raise ExistingFileMismatch("joined quarantine crosses filesystem")
        for part in (".stoarama-quarantine", "aliases"):
            try:
                child = os.open(part, flags, dir_fd=descriptor)
            except FileNotFoundError:
                os.mkdir(part, mode=0o700, dir_fd=descriptor)
                os.fsync(descriptor)
                child = os.open(part, flags, dir_fd=descriptor)
            if os.fstat(child).st_dev != device:
                os.close(child)
                raise ExistingFileMismatch("joined quarantine crosses filesystem")
            os.close(descriptor)
            descriptor = child
        return descriptor
    except BaseException:
        os.close(descriptor)
        raise


def joined_alias_is_canonical(name):
    # All joined media/manifests and every transfer's partial/marker are protected.
    return name.lower().endswith((".mp4", ".json")) or re.search(r"\.joined-[0-9]+\.part$", name) is not None


def copy_joined_canonical(directory_fd, name, current, cfg, stop_event):
    """Read the canonical bytes once; independently hash the fsynced private copy."""
    volume = os.fstatvfs(directory_fd)
    if volume.f_bavail * (volume.f_frsize or volume.f_bsize) < current.st_size + cfg.min_free_bytes:
        raise ExistingFileMismatch("joined quarantine copy has insufficient NAS free space")
    flags = getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0)
    source = os.open(name, os.O_RDONLY | flags, dir_fd=directory_fd)
    temporary = ".stoarama-copy-" + os.urandom(16).hex()
    target = None
    try:
        if certification_identity(os.fstat(source)) != certification_identity(current):
            raise ExistingFileMismatch("joined canonical changed before quarantine copy")
        target = os.open(temporary, os.O_RDWR | os.O_CREAT | os.O_EXCL | flags, 0o600, dir_fd=directory_fd)
        if os.fstat(target).st_nlink != 1:
            raise ExistingFileMismatch("joined quarantine copy is not private")
        source_hash = hashlib.sha256()
        copied = 0
        while True:
            if stop_event.is_set():
                raise JoinedDownloadYield("joined quarantine copy stopped at a read boundary")
            block = os.read(source, JOINED_RANGE_BYTES)
            if not block:
                break
            source_hash.update(block)
            copied += len(block)
            offset = 0
            while offset < len(block):
                offset += os.write(target, block[offset:])
        os.fsync(target)
        os.lseek(target, 0, os.SEEK_SET)
        copy_hash = hashlib.sha256()
        while True:
            block = os.read(target, JOINED_RANGE_BYTES)
            if not block:
                break
            copy_hash.update(block)
        fresh = os.fstat(target)
        canonical_after = joined_entry_stat(directory_fd, name)
        if (
            copied != current.st_size or fresh.st_size != copied or fresh.st_nlink != 1
            or source_hash.digest() != copy_hash.digest()
            or certification_identity(os.fstat(source)) != certification_identity(current)
            or canonical_after is None or certification_identity(canonical_after) != certification_identity(current)
        ):
            raise ExistingFileMismatch("joined quarantine copy size/hash or canonical identity changed")
        os.fsync(directory_fd)
        return temporary, fresh, source_hash.hexdigest()
    finally:
        os.close(source)
        if target is not None:
            os.close(target)
        # Failed/interrupted private copies are preserved, never treated as aliases.


def quarantine_joined_aliases(cfg, runtime, directory_fd, name, artifact, stop_event, hinted_stage=None, *, canonical_path=None):
    """Move only non-canonical names, then detach the canonical inode by copying."""
    current = joined_entry_stat(directory_fd, name)
    if current is None:
        raise ExistingFileMismatch("joined canonical path is missing")
    aliases = []
    for entry in sorted(os.listdir(directory_fd)):
        if entry == name:
            continue
        candidate = os.stat(entry, dir_fd=directory_fd, follow_symlinks=False)
        if same_joined_inode(current, candidate) or entry == hinted_stage:
            if joined_alias_is_canonical(entry) or not stat_module.S_ISREG(candidate.st_mode):
                raise ExistingFileMismatch("joined canonical ambiguity: %s and %s" % (name, entry))
            aliases.append((entry, candidate))
    if current.st_nlink == 1 and not aliases:
        return
    quarantine_fd = open_joined_quarantine(cfg, directory_fd)
    try:
        quarantined_links = sum(
            same_joined_inode(current, os.stat(entry, dir_fd=quarantine_fd, follow_symlinks=False))
            for entry in os.listdir(quarantine_fd)
        )
        found_links = sum(same_joined_inode(current, candidate) for _, candidate in aliases)
        if current.st_nlink != 1 + found_links + quarantined_links:
            raise ExistingFileMismatch("joined unknown hardlink outside inspected directory; refusing quarantine")
        # Complete every copy check before moving any source name.
        copied = copy_joined_canonical(directory_fd, name, current, cfg, stop_event) if current.st_nlink > 1 else None
        parent = (joined_output_path(cfg, artifact) if canonical_path is None else canonical_path).parent.absolute()
        qroot = cfg.output_dir.absolute() / ".stoarama-quarantine" / "aliases"
        reason = "extra joined hardlink or interrupted sidecar stage"
        for entry, candidate in aliases:
            destination = "%s-%d-%s-%s" % (
                time.strftime("%Y%m%dT%H%M%SZ", time.gmtime()), artifact["id"], os.urandom(16).hex(), entry[-120:],
            )
            record = {
                "operation": "alias_move", "artifact_id": artifact["id"], "old_path": str(parent / entry),
                "new_path": str(qroot / destination), "device": candidate.st_dev, "inode": candidate.st_ino,
                "size_bytes": candidate.st_size, "link_count": candidate.st_nlink, "reason": reason,
            }
            append_joined_quarantine_ledger(cfg, dict(record, state="intent"))
            observed = joined_entry_stat(directory_fd, entry)
            if observed is None or (
                observed.st_mode, observed.st_dev, observed.st_ino, observed.st_size, observed.st_mtime_ns, observed.st_nlink
            ) != (candidate.st_mode, candidate.st_dev, candidate.st_ino, candidate.st_size, candidate.st_mtime_ns, candidate.st_nlink):
                raise ExistingFileMismatch("joined alias changed before quarantine rename")
            if joined_entry_stat(quarantine_fd, destination) is not None:
                raise ExistingFileMismatch("joined quarantine destination already exists")
            os.rename(entry, destination, src_dir_fd=directory_fd, dst_dir_fd=quarantine_fd)
            os.fsync(directory_fd)
            os.fsync(quarantine_fd)
            append_joined_quarantine_ledger(cfg, dict(record, state="complete"))
            report_joined_quarantine(runtime, "joined quarantine artifact_id=%d old=%s new=%s inode=%d links=%d size=%d" % (
                artifact["id"], record["old_path"], record["new_path"], candidate.st_ino, candidate.st_nlink, candidate.st_size))
        if copied is not None:
            temporary, fresh, digest = copied
            observed = joined_entry_stat(directory_fd, name)
            # Renaming an alias can change ctime. Bytes, inode, size and mtime
            # must still match; link count must not change during the moves.
            if observed is None or (
                observed.st_dev, observed.st_ino, observed.st_size, observed.st_mtime_ns, observed.st_nlink
            ) != (current.st_dev, current.st_ino, current.st_size, current.st_mtime_ns, current.st_nlink):
                raise ExistingFileMismatch("joined canonical changed before copy replacement")
            temp_stat = joined_entry_stat(directory_fd, temporary)
            if temp_stat is None or certification_identity(temp_stat) != certification_identity(fresh) or temp_stat.st_nlink != 1:
                raise ExistingFileMismatch("joined private copy changed before replacement")
            record = {
                "operation": "canonical_copy", "artifact_id": artifact["id"], "canonical_path": str(parent / name),
                "temporary_path": str(parent / temporary), "device": current.st_dev, "old_inode": current.st_ino,
                "new_inode": fresh.st_ino, "size_bytes": fresh.st_size, "sha256": digest, "reason": reason,
            }
            append_joined_quarantine_ledger(cfg, dict(record, state="intent"))
            final_source = joined_entry_stat(directory_fd, name)
            final_copy = joined_entry_stat(directory_fd, temporary)
            if (
                final_source is None or certification_identity(final_source) != certification_identity(observed)
                or final_copy is None or certification_identity(final_copy) != certification_identity(fresh)
                or final_copy.st_nlink != 1
            ):
                raise ExistingFileMismatch("joined canonical or private copy changed during ledger sync")
            os.replace(temporary, name, src_dir_fd=directory_fd, dst_dir_fd=directory_fd)
            os.fsync(directory_fd)
            append_joined_quarantine_ledger(cfg, dict(record, state="complete"))
            report_joined_quarantine(runtime, "joined quarantine detached artifact_id=%d path=%s old_inode=%d new_inode=%d size=%d sha256=%s" % (
                artifact["id"], record["canonical_path"], current.st_ino, fresh.st_ino, fresh.st_size, digest))
    except OSError as exc:
        raise ExistingFileMismatch("joined quarantine failed: %s" % exc) from exc
    finally:
        os.close(quarantine_fd)


def recover_joined_sidecar(cfg, runtime, directory_fd, name, content, stop_event, journal, identity, record):
    # The journal is only a path hint. Recorded device/inode never authorizes
    # deletion or establishes provenance (inodes can be reused after a crash).
    stage = record.get("stage_name") if isinstance(record, dict) else None
    if (
        not isinstance(stage, str) or not stage.startswith(name + ".stage-")
        or re.fullmatch(r"[0-9a-f]{32}", stage[len(name + ".stage-"):]) is None
        or any(record.get(key) != identity[key] for key in ("artifact_id", "marker_path"))
    ):
        raise ExistingFileMismatch("joined sidecar durable intent has an invalid path hint")
    marker_stat = joined_entry_stat(directory_fd, name)
    if marker_stat is None:
        stage_stat = joined_entry_stat(directory_fd, stage)
        if stage_stat is None or stage_stat.st_nlink != 1 or not verify_joined_sidecar(
            cfg, runtime, directory_fd, stage, content, stop_event,
        ):
            raise ExistingFileMismatch("joined sidecar durable intent has no unambiguous complete stage")
        # Link publication cannot overwrite a concurrently created canonical
        # path. Its extra staging alias follows the same preservation path.
        os.link(stage, name, src_dir_fd=directory_fd, dst_dir_fd=directory_fd, follow_symlinks=False)
        os.fsync(directory_fd)
    if not verify_joined_sidecar(cfg, runtime, directory_fd, name, content, stop_event):
        raise ExistingFileMismatch("joined partial ownership marker conflicts")
    quarantine_joined_aliases(cfg, runtime, directory_fd, name, json.loads(content), stop_event, stage)
    os.fsync(directory_fd)
    journal.unlink()
    fsync_dir(journal.parent)


def publish_joined_sidecar(cfg, runtime, directory_fd, name, content, stop_event):
    journal, identity = joined_sidecar_intent(cfg, directory_fd, name, content)
    try:
        try:
            encoded = journal.read_bytes()
        except FileNotFoundError:
            pass
        else:
            try:
                record = json.loads(encoded)
            except ValueError as exc:
                raise ExistingFileMismatch("joined sidecar durable intent is invalid") from exc
            recover_joined_sidecar(cfg, runtime, directory_fd, name, content, stop_event, journal, identity, record)
            return
        if joined_entry_stat(directory_fd, name) is not None:
            if not verify_joined_sidecar(cfg, runtime, directory_fd, name, content, stop_event):
                raise ExistingFileMismatch("joined partial ownership marker conflicts")
            quarantine_joined_aliases(cfg, runtime, directory_fd, name, json.loads(content), stop_event)
            return
        for _attempt in range(8):
            stage = name + ".stage-" + os.urandom(16).hex()
            try:
                current = write_joined_stage(directory_fd, stage, content)
                break
            except FileExistsError:
                continue
        else:
            raise ExistingFileMismatch("could not allocate a private joined sidecar stage")
        record = dict(identity, stage_name=stage,
                      stage_path=str(Path(identity["marker_path"]).with_name(stage)),
                      device=current.st_dev, inode=current.st_ino)
        atomic_write(journal, json.dumps(record, sort_keys=True).encode("utf-8"))
        recover_joined_sidecar(cfg, runtime, directory_fd, name, content, stop_event, journal, identity, record)
    except (ExistingFileMismatch, OSError) as exc:
        message = "joined marker=%s artifact_id=%d: %s" % (identity["marker_path"], identity["artifact_id"], exc)
        report_joined_quarantine(runtime, message)
        raise ExistingFileMismatch(message) from exc


def same_joined_inode(left, right):
    return left is not None and right is not None and (left.st_dev, left.st_ino) == (right.st_dev, right.st_ino)


def ensure_owned_joined_partial(cfg, runtime, directory_fd, part_name, marker_name, sidecar, stop_event):
    part_stat = joined_entry_stat(directory_fd, part_name)
    marker_stat = joined_entry_stat(directory_fd, marker_name)
    if marker_stat is None and part_stat is not None:
        raise ExistingFileMismatch("joined partial has no ownership marker")
    # Recover by preserving aliases and detaching canonical files before writes.
    publish_joined_sidecar(cfg, runtime, directory_fd, marker_name, sidecar, stop_event)
    marker_stat = joined_entry_stat(directory_fd, marker_name)
    if part_stat is not None and part_stat.st_nlink != 1:
        try:
            quarantine_joined_aliases(cfg, runtime, directory_fd, part_name, json.loads(sidecar), stop_event)
        except (ExistingFileMismatch, OSError) as exc:
            report_joined_quarantine(runtime, "joined partial quarantine refused: %s" % exc)
            raise
        part_stat = joined_entry_stat(directory_fd, part_name)
    if part_stat is None:
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
        descriptor = os.open(part_name, flags, 0o600, dir_fd=directory_fd)
        try:
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        os.fsync(directory_fd)
        part_stat = joined_entry_stat(directory_fd, part_name)
    if part_stat.st_nlink != 1 or marker_stat.st_nlink != 1:
        raise ExistingFileMismatch("joined partial or marker has an unknown hardlink")
    return part_stat


def truncate_joined_part(directory_fd, name):
    flags = os.O_WRONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    descriptor = os.open(name, flags, dir_fd=directory_fd)
    try:
        current = os.fstat(descriptor)
        if not stat_module.S_ISREG(current.st_mode) or current.st_nlink != 1:
            raise ExistingFileMismatch("joined partial is not exclusively owned")
        os.ftruncate(descriptor, 0)
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def poll_raw_pending(cfg, runtime):
    page = request_json(
        cfg, "GET", "/account/clips?after_id=%d&limit=%d" % (runtime.cursor_id, LIST_PAGE_LIMIT)
    )
    clips = page.get("clips", [])
    if not isinstance(clips, list):
        raise RuntimeError("clips response is not a list")
    return bool(clips)


def poll_raw_pending_cached(cfg, runtime):
    now = time.monotonic()
    with runtime.lock:
        if now - runtime.joined_raw_priority_polled_at < 1.0:
            return runtime.joined_raw_priority_pending
    pending = poll_raw_pending(cfg, runtime)
    with runtime.lock:
        runtime.joined_raw_priority_polled_at = now
        runtime.joined_raw_priority_pending = pending
    return pending


def await_joined_work(cfg, runtime, stop_event):
    if not runtime.joined_fair_share_enabled():
        return
    while not runtime.consume_joined_work_credit():
        if not poll_raw_pending_cached(cfg, runtime):
            return
        if stop_event.is_set() or not runtime.joined_protocol_enabled():
            raise JoinedDownloadYield("joined work stopped at a bounded boundary")
        if runtime.wait_joined_work_credit(.1):
            return


def joined_raw_priority_boundary(cfg, runtime, stop_event):
    if runtime.joined_fair_share_enabled():
        await_joined_work(cfg, runtime, stop_event)
    elif poll_raw_pending(cfg, runtime):
        raise JoinedDownloadYield("joined delivery yielded to raw delivery")


def prepare_joined_download(cfg, item):
    prepared = request_json(cfg, "GET", item["download_path"], base=cfg.origin)
    if set(prepared) != {
        "url", "etag", "if_match", "version_id", "size_bytes", "sha256", "content_type", "expires_in_sec",
    }:
        raise RuntimeError("joined download response has invalid fields")
    url = prepared.get("url")
    if not isinstance(url, str):
        raise RuntimeError("joined download returned invalid URL")
    parsed = urllib.parse.urlsplit(url)
    try:
        parsed.port
    except ValueError as exc:
        raise RuntimeError("joined download returned invalid URL") from exc
    if (
        parsed.scheme != "https" or not parsed.hostname or parsed.username is not None
        or parsed.password is not None or parsed.fragment or not parsed.path.startswith("/")
    ):
        raise RuntimeError("joined download returned invalid URL")
    if prepared.get("size_bytes") != item["size_bytes"] or prepared.get("sha256") != item["sha256"]:
        raise ExistingFileMismatch("joined prepared bytes changed")
    if prepared.get("content_type") != item["content_type"]:
        raise ExistingFileMismatch("joined prepared content type changed")
    expires_in_sec = prepared.get("expires_in_sec")
    if isinstance(expires_in_sec, bool) or not isinstance(expires_in_sec, int) or not 1 <= expires_in_sec <= 3600:
        raise RuntimeError("joined download returned invalid expiry")
    etag = normalized_etag(prepared.get("etag"))
    version_id = prepared.get("version_id")
    if (
        not isinstance(version_id, str) or len(version_id) > 1024 or version_id != version_id.strip()
        or any(ord(ch) < 32 or ord(ch) == 127 for ch in version_id)
    ):
        raise RuntimeError("joined download returned invalid version_id")
    if_match = prepared.get("if_match")
    if not isinstance(if_match, str):
        raise ExistingFileMismatch("joined prepared If-Match changed")
    if if_match != '"%s"' % etag:
        raise ExistingFileMismatch("joined prepared If-Match changed")
    return {
        "url": url, "if_match": if_match, "etag": etag, "version_id": version_id,
        "url_scheme": parsed.scheme, "url_authority": parsed.netloc, "url_path": parsed.path,
    }


def validate_joined_download_renewal(first, current):
    if any(current[key] != first[key] for key in (
        "etag", "version_id", "url_scheme", "url_authority", "url_path",
    )):
        raise ExistingFileMismatch("joined prepared object identity changed")


def throttle_joined_io(started, transferred, bytes_per_sec, stop_event):
    delay = (float(transferred) / bytes_per_sec) - (time.monotonic() - started)
    if delay > 0 and stop_event.wait(delay):
        raise JoinedDownloadYield("joined I/O stopped at a bounded chunk")


def append_joined_range(prepared, directory_fd, part_name, item, start, end, stop_event):
    headers = {
        "User-Agent": USER_AGENT,
        "Range": "bytes=%d-%d" % (start, end),
        "If-Match": prepared["if_match"],
    }
    request = urllib.request.Request(prepared["url"], method="GET", headers=headers)
    try:
        response_context = open_joined_url(request)
    except urllib.error.HTTPError as exc:
        if exc.code == 416:
            truncate_joined_part(directory_fd, part_name)
            raise RuntimeError("joined range was unsatisfiable; partial restarted") from exc
        raise
    with response_context as response:
        remember_response_secrets(response)
        status = getattr(response, "status", None) or response.getcode()
        if status == 200:
            truncate_joined_part(directory_fd, part_name)
            raise RuntimeError("joined server ignored range; partial restarted")
        if status != 206:
            raise RuntimeError("joined range returned HTTP %s" % status)
        response_etag = normalized_etag(response.headers.get("ETag"))
        response_version = str(response.headers.get("x-amz-version-id") or "")
        if response_etag != prepared["etag"] or response_version != prepared["version_id"]:
            truncate_joined_part(directory_fd, part_name)
            raise ExistingFileMismatch("joined range object identity drifted; partial restarted")
        expected_range = "bytes %d-%d/%d" % (start, end, item["size_bytes"])
        if response.headers.get("Content-Range") != expected_range:
            raise RuntimeError("joined range returned invalid Content-Range")
        chunk_bytes = end - start + 1
        try:
            content_length = int(response.headers.get("Content-Length", ""))
        except ValueError as exc:
            raise RuntimeError("joined range returned invalid Content-Length") from exc
        if content_length != chunk_bytes:
            raise RuntimeError("joined range returned invalid Content-Length")
        flags = os.O_WRONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
        descriptor = os.open(part_name, flags, dir_fd=directory_fd)
        written = 0
        started = time.monotonic()
        try:
            opened = os.fstat(descriptor)
            if not stat_module.S_ISREG(opened.st_mode) or opened.st_nlink != 1 or opened.st_size != start:
                raise ExistingFileMismatch("joined partial changed before range append")
            os.lseek(descriptor, start, os.SEEK_SET)
            while written < chunk_bytes:
                block = response.read(min(1024 * 1024, chunk_bytes - written))
                if not block:
                    break
                offset = 0
                while offset < len(block):
                    offset += os.write(descriptor, block[offset:])
                written += len(block)
                throttle_joined_io(started, written, JOINED_DOWNLOAD_BYTES_PER_SEC, stop_event)
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        if written != chunk_bytes or response.read(1):
            raise RuntimeError("joined range body length mismatch")


def remove_owned_joined_transfer(cfg, runtime, directory_fd, part_name, marker_name, final_name, marker, stop_event):
    part_stat = joined_entry_stat(directory_fd, part_name)
    marker_stat = joined_entry_stat(directory_fd, marker_name)
    final_stat = joined_entry_stat(directory_fd, final_name)
    if part_stat is not None:
        if part_stat.st_nlink != 2 or final_stat.st_nlink != 2 or not same_joined_inode(part_stat, final_stat):
            raise ExistingFileMismatch("joined partial is not the published final")
        # Only client-owned transfer scratch is disposable. Raw media, finals,
        # unknown partials, and conflicting paths are never unlinked.
        os.unlink(part_name, dir_fd=directory_fd)
    if marker_stat is not None:
        if marker_stat.st_nlink != 1 or not verify_joined_sidecar(
            cfg, runtime, directory_fd, marker_name, marker, stop_event,
        ):
            raise ExistingFileMismatch("joined transfer marker conflicts")
        os.unlink(marker_name, dir_fd=directory_fd)
    os.fsync(directory_fd)
    if joined_entry_stat(directory_fd, final_name).st_nlink != 1:
        raise ExistingFileMismatch("joined published link count is invalid")


def complete_existing_joined(cfg, runtime, directory_fd, item, names, marker, stop_event):
    final_name, part_name, marker_name = names
    final_stat = joined_entry_stat(directory_fd, final_name)
    if final_stat is None:
        return False
    if not verify_joined_entry(
        cfg, runtime, directory_fd, final_name, item["size_bytes"], item["sha256"], stop_event,
    ):
        raise ExistingFileMismatch("joined final disappeared")
    final_stat = joined_entry_stat(directory_fd, final_name)
    part_stat = joined_entry_stat(directory_fd, part_name)
    marker_stat = joined_entry_stat(directory_fd, marker_name)
    if part_stat is None:
        if final_stat.st_nlink != 1:
            raise ExistingFileMismatch("joined final has an unknown hardlink")
    elif final_stat.st_nlink != 2 or part_stat.st_nlink != 2 or not same_joined_inode(final_stat, part_stat):
        raise ExistingFileMismatch("joined partial conflicts with final")
    if marker_stat is not None:
        # Refuse unknown marker aliases before removing even transfer scratch.
        publish_joined_sidecar(cfg, runtime, directory_fd, marker_name, marker, stop_event)
    if part_stat is not None and marker_stat is None:
        raise ExistingFileMismatch("joined published partial has no ownership marker")
    validate_joined_artifact(cfg, runtime, directory_fd, final_name, item, stop_event)
    remove_owned_joined_transfer(
        cfg, runtime, directory_fd, part_name, marker_name, final_name, marker, stop_event,
    )
    return True


JOINED_IDENTITY_BLOCKERS = frozenset((
    "dependency_identity", "manifest_identity", "existing_output_identity",
    "prepared_object_identity", "transfer_marker_identity",
))


def joined_identity_step(reason_code, operation, *args):
    """Attach a safe diagnostic without changing the original failure or operation."""
    try:
        return operation(*args)
    except ExistingFileMismatch as exc:
        exc.joined_identity_reason = reason_code
        raise


@NAS_MEDIA_FENCE.background_delivery
def download_joined_item(cfg, runtime, item, stop_event):
    joined_raw_priority_boundary(cfg, runtime, stop_event)
    # Expose failures while opening or hashing prerequisite manifests. Offset
    # zero is a phase marker; the server preserves any prior durable range.
    runtime.set_joined_transfer(item["id"], 0, "validate")
    joined_identity_step("dependency_identity", ensure_joined_dependency_ack, cfg, runtime, item, stop_event)
    joined_identity_step("manifest_identity", validate_media_manifest_binding, cfg, runtime, item, stop_event)
    directory_fd = open_joined_output_dir(cfg, item)
    final_name = Path(item["relative_path"]).name
    part_name = ".%s.joined-%d.part" % (final_name, item["id"])
    marker_name = part_name + ".stoarama.json"
    names = (final_name, part_name, marker_name)
    try:
        final_stat = joined_entry_stat(directory_fd, final_name)
        part_stat = joined_entry_stat(directory_fd, part_name)
        marker_stat = joined_entry_stat(directory_fd, marker_name)
        if final_stat is not None and part_stat is None and marker_stat is None and joined_identity_step("existing_output_identity", complete_existing_joined,
            cfg, runtime, directory_fd, item, names, None, stop_event,
        ):
            return False
        prepared = joined_identity_step("prepared_object_identity", prepare_joined_download, cfg, item)
        marker = joined_transfer_marker_bytes(item, prepared)
        if joined_identity_step("existing_output_identity", complete_existing_joined, cfg, runtime, directory_fd, item, names, marker, stop_event):
            return False
        part_stat = joined_identity_step("transfer_marker_identity", ensure_owned_joined_partial,
            cfg, runtime, directory_fd, part_name, marker_name, marker, stop_event,
        )
        if part_stat.st_nlink != 1:
            raise ExistingFileMismatch("joined partial has an unknown hardlink")
        part_size = part_stat.st_size
        if part_size > item["size_bytes"]:
            truncate_joined_part(directory_fd, part_name)
            part_size = 0
        runtime.set_joined_transfer(item["id"], part_size, "range")
        while part_size < item["size_bytes"]:
            if not runtime.joined_protocol_enabled() or stop_event.is_set():
                raise JoinedDownloadYield("joined download stopped at a range boundary")
            joined_raw_priority_boundary(cfg, runtime, stop_event)
            try:
                current_prepared = prepare_joined_download(cfg, item)
            except ExistingFileMismatch:
                truncate_joined_part(directory_fd, part_name)
                raise
            validate_joined_download_renewal(prepared, current_prepared)
            end = min(item["size_bytes"], part_size + JOINED_RANGE_BYTES) - 1
            range_bytes = end - part_size + 1
            require_joined_storage_capacity(cfg, runtime, range_bytes)
            try:
                append_joined_range(current_prepared, directory_fd, part_name, item, part_size, end, stop_event)
            finally:
                runtime.release_storage_reservation(range_bytes)
            part_size = end + 1
            runtime.set_joined_transfer(item["id"], part_size, "range")
        if not runtime.joined_protocol_enabled():
            raise JoinedDownloadYield("joined protocol was disabled")
        joined_raw_priority_boundary(cfg, runtime, stop_event)
        runtime.set_joined_transfer(item["id"], part_size, "verify")
        try:
            verify_joined_entry(
                cfg, runtime, directory_fd, part_name, item["size_bytes"], item["sha256"], stop_event,
            )
        except ExistingFileMismatch:
            truncate_joined_part(directory_fd, part_name)
            raise RuntimeError("joined download checksum mismatch; partial restarted")
        joined_raw_priority_boundary(cfg, runtime, stop_event)
        runtime.set_joined_transfer(item["id"], part_size, "validate")
        validate_joined_artifact(cfg, runtime, directory_fd, part_name, item, stop_event)
        joined_raw_priority_boundary(cfg, runtime, stop_event)
        runtime.set_joined_transfer(item["id"], part_size, "publish")
        def publish_final():
            os.link(part_name, final_name, src_dir_fd=directory_fd, dst_dir_fd=directory_fd, follow_symlinks=False)
            os.fsync(directory_fd)
        if not runtime.run_joined_completion(publish_final):
            raise JoinedDownloadYield("joined protocol was disabled")
        if not complete_existing_joined(cfg, runtime, directory_fd, item, names, marker, stop_event):
            raise RuntimeError("joined publication disappeared")
        return True
    finally:
        os.close(directory_fd)


def joined_ack_receipt_path(cfg, connection_id):
    scope = hashlib.sha256((cfg.origin + "\0" + str(connection_id)).encode("utf-8")).hexdigest()[:16]
    return cfg.state_dir / ("joined-ack-receipts-%s.json" % scope)


def joined_ack_receipts(cfg, connection_id):
    path = joined_ack_receipt_path(cfg, connection_id)
    empty = {"schema_version": 1, "origin": cfg.origin, "connection_id": connection_id, "receipts": {}}
    payload = read_json(path, empty)
    if not isinstance(payload, dict) or set(payload) != set(empty) or payload["schema_version"] != 1 or payload["origin"] != cfg.origin or payload["connection_id"] != connection_id or not isinstance(payload["receipts"], dict):
        raise RuntimeError("joined ACK receipt state conflicts with this connection")
    fields = {"artifact_id", "relative_path", "size_bytes", "sha256"}
    for key, receipt in payload["receipts"].items():
        if (
            not isinstance(key, str) or not key.isdigit() or not isinstance(receipt, dict) or set(receipt) != fields
            or receipt["artifact_id"] != int(key) or isinstance(receipt["artifact_id"], bool)
            or not isinstance(receipt["artifact_id"], int) or receipt["artifact_id"] < 1
            or valid_joined_relative_path(receipt["relative_path"]) != receipt["relative_path"]
            or positive_joined_int(receipt["size_bytes"], "ACK receipt size") > JOINED_MAX_BYTES
            or valid_sha256(receipt["sha256"], "ACK receipt") != receipt["sha256"]
        ):
            raise RuntimeError("joined ACK receipt state is invalid")
    return path, payload


def joined_ack_identity(item, size_bytes=None):
    return {
        "artifact_id": item["id"], "relative_path": item["relative_path"],
        "size_bytes": item["size_bytes"] if size_bytes is None else size_bytes, "sha256": item["sha256"],
    }


def has_joined_ack_receipt(cfg, connection_id, identity):
    _, payload = joined_ack_receipts(cfg, connection_id)
    return payload["receipts"].get(str(identity["artifact_id"])) == identity


def persist_joined_ack_receipt(cfg, connection_id, identity):
    path, payload = joined_ack_receipts(cfg, connection_id)
    key = str(identity["artifact_id"])
    existing = payload["receipts"].get(key)
    if existing is not None and existing != identity:
        raise RuntimeError("joined ACK receipt artifact identity conflicts")
    payload["receipts"][key] = identity
    atomic_write(path, joined_canonical_bytes(payload))


def post_joined_ack(cfg, connection_id, identity):
    request_json(cfg, "POST", "/account/joined/ack", body={
        "artifact_id": identity["artifact_id"], "relative_path": identity["relative_path"],
        "size_bytes": identity["size_bytes"], "sha256": identity["sha256"],
    })
    # The receipt is written only after the exact idempotent ACK succeeds.
    persist_joined_ack_receipt(cfg, connection_id, identity)


def ack_joined_item(cfg, runtime, item, stop_event):
    await_joined_work(cfg, runtime, stop_event)
    if not runtime.run_joined_completion(
        lambda: post_joined_ack(cfg, item["connection_id"], joined_ack_identity(item))
    ):
        raise JoinedDownloadYield("joined protocol was disabled")


def ensure_joined_dependency_ack(cfg, runtime, item, stop_event):
    if item["kind"] == "hour_manifest":
        dependency = {
            "id": item["ledger_artifact_id"], "relative_path": item["ledger_relative_path"],
            "sha256": item["ledger_sha256"],
        }
    elif item["kind"] == "media":
        dependency = {
            "id": item["hour_manifest_id"], "relative_path": item["hour_manifest_relative_path"],
            "sha256": item["hour_manifest_sha256"],
        }
    else:
        return
    holder = {"batch_id": item["batch_id"], "relative_path": dependency["relative_path"]}
    directory_fd = open_joined_output_dir(cfg, holder, create=False)
    try:
        size_bytes, digest, file_stat = hash_joined_entry(
            cfg, runtime, directory_fd, Path(dependency["relative_path"]).name, stop_event,
        )
    finally:
        os.close(directory_fd)
    if file_stat.st_nlink != 1 or digest != dependency["sha256"] or size_bytes < 1 or size_bytes > JOINED_MANIFEST_MAX_BYTES:
        raise ExistingFileMismatch("joined dependency file identity conflicts")
    identity = joined_ack_identity({**dependency, "size_bytes": size_bytes})
    if not has_joined_ack_receipt(cfg, item["connection_id"], identity):
        await_joined_work(cfg, runtime, stop_event)
        if not runtime.run_joined_completion(lambda: post_joined_ack(cfg, item["connection_id"], identity)):
            raise JoinedDownloadYield("joined protocol was disabled")


def drain_joined(cfg, runtime, stop_event, report_phase=True):
    if not runtime.joined_protocol_enabled() or cfg.dry_run:
        return False
    page = request_json(cfg, "GET", "/account/joined")
    if not runtime.joined_protocol_enabled():
        return False
    if set(page) - {"item"}:
        raise RuntimeError("joined response contains unknown fields")
    raw_item = page.get("item")
    if raw_item is None:
        return False
    item = valid_joined_item(raw_item)
    if report_phase:
        runtime.set_phase(Phase.DRAINING)
    try:
        downloaded = download_joined_item(cfg, runtime, item, stop_event)
        ack_joined_item(cfg, runtime, item, stop_event)
    except JoinedDownloadYield as exc:
        if "storage" in str(exc):
            runtime.set_joined_delivery_error(item["id"], "storage_guard", min(getattr(cfg, "poll_interval_sec", 60), 10))
        log("INFO", "joined artifact_id=%d stopped at a safe boundary" % item["id"])
        return False
    except Exception as exc:
        runtime.set_joined_transfer_error(item["id"], exc)
        runtime.set_joined_delivery_error(
            item["id"], classify_joined_delivery_error(exc), min(getattr(cfg, "poll_interval_sec", 60), 10),
            "joined artifact_id=%d: %s" % (item["id"], exc),
        )
        log("ERROR", "joined artifact_id=%d failed: %s" % (item["id"], exc))
        raise
    runtime.clear_joined_delivery_error()
    runtime.clear_joined_transfer()
    log(
        "INFO", "joined artifact_id=%d bytes=%d saved=%s%s"
        % (item["id"], item["size_bytes"], joined_output_path(cfg, item), "" if downloaded else " existing"),
    )
    return True


def classify_joined_delivery_error(exc):
    if isinstance(exc, urllib.error.HTTPError):
        return "http_error"
    if isinstance(exc, ExistingFileMismatch):
        reason = getattr(exc, "joined_identity_reason", None)
        return reason if isinstance(reason, str) and reason in JOINED_IDENTITY_BLOCKERS else "path_conflict"
    if isinstance(exc, OSError):
        return "io_error"
    if "checksum mismatch" in str(exc):
        return "hash_mismatch"
    return "download_failed"


def joined_errno_class(exc):
    cursor = exc
    while cursor is not None:
        if isinstance(cursor, OSError):
            if cursor.errno in (errno.ENOSPC, errno.EDQUOT):
                return "no_space"
            if cursor.errno in (errno.EACCES, errno.EPERM):
                return "permission"
            if cursor.errno == errno.ENOENT:
                return "missing"
            if cursor.errno == errno.EIO:
                return "io"
            return "os_error"
        cursor = cursor.__cause__
    return ""


def joined_loop(cfg, runtime, stop_event):
    """Drain collated outputs and generation-1 joined artifacts beside the raw loop."""
    while not stop_event.is_set():
        if not NAS_MEDIA_FENCE.wait_maintenance(stop_event):
            return
        progress = False
        try:
            progress = drain_collated(cfg, runtime, stop_event)
        except Exception as exc:
            log("WARN", "collated delivery deferred: %s" % exc)
        if stop_event.is_set():
            break
        if runtime.joined_background_enabled():
            try:
                progress = drain_joined(cfg, runtime, stop_event, report_phase=False) or progress
            except Exception as exc:
                log("WARN", "joined delivery deferred: %s" % exc)
                progress = False
        if not progress:
            stop_event.wait(min(cfg.poll_interval_sec, 10))


# ---------------------------------------------------------------------------
# Generation-2 collated hour delivery (docs/NAS_JOINED_DELIVERY.md).
#
# The server hands out exact collated outputs with a per-connection policy
# (enabled, bytes/s, parallel downloads). Each output lands at
# /clips/joined/<nas_relative_path>, a mirror of the raw <folder>/<Month>/
# <DD-Weekday>/ tree. The lane runs beside raw delivery with its own budget and
# never yields to it. Partials resume by byte offset; a final is only ever
# created by a no-overwrite link after its size and SHA-256 are verified, and an
# existing final with different bytes is never touched.

COLLATED_PAGE_LIMIT = 50
COLLATED_CHUNK_BYTES = 1024 * 1024
COLLATED_MAX_PARALLEL = 32
COLLATED_MIN_BYTES_PER_SEC = 1 << 20
COLLATED_MAX_BYTES_PER_SEC = 1 << 30
COLLATED_MAX_BYTES = 64 * 1024 * 1024 * 1024
COLLATED_PATH_RE = re.compile(
    r"^[^/]+/(January|February|March|April|May|June|July|August|September|October|November|December)/"
    r"(0[1-9]|[12][0-9]|3[01])-(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)/"
    r"[^/]+_hour_([01][0-9]|2[0-3])(_dst2)?((_part_[0-9]{2})?_[0-9]{6}-[0-9]{6}\.mp4|\.manifest\.json)$"
)


COLLATED_V1_PATH_RE = re.compile(
    r"^[^/]+/([1-9][0-9]*)/joined/([0-9]{4}-[0-9]{2}-[0-9]{2})/([1-9][0-9]*)_([0-9]{4}-[0-9]{2}-[0-9]{2})"
    r"_hour_([01][0-9]|2[0-3])(_part_[0-9]{2})?_[0-9]{6}-[0-9]{6}\.mp4$"
)


def collated_path_matches_contract(value):
    if COLLATED_PATH_RE.match(value):
        return True
    match = COLLATED_V1_PATH_RE.match(value)
    return bool(match) and match.group(1) == match.group(3) and match.group(2) == match.group(4)


class CollatedDownloadStopped(RuntimeError):
    """The lane stopped at a chunk boundary; the partial resumes later."""


def valid_collated_relative_path(value):
    if not isinstance(value, str) or value != value.strip() or len(value.encode("utf-8")) > 1024:
        raise ValueError("collated item has invalid nas_relative_path")
    parts = value.split("/")
    if (
        value.startswith("/") or "\\" in value or "\0" in value
        or any(part in ("", ".", "..") or part.startswith(".") for part in parts)
        or parts[0] == JOINED_ROOT or not collated_path_matches_contract(value)
    ):
        raise ValueError("collated item has invalid nas_relative_path")
    return value


def valid_collated_policy(raw):
    if not isinstance(raw, dict) or set(raw) != {"enabled", "download_bytes_per_sec", "download_parallel"}:
        raise ValueError("collated policy is invalid")
    enabled, rate, parallel = raw["enabled"], raw["download_bytes_per_sec"], raw["download_parallel"]
    if (
        type(enabled) is not bool or type(rate) is not int or type(parallel) is not int
        or not COLLATED_MIN_BYTES_PER_SEC <= rate <= COLLATED_MAX_BYTES_PER_SEC
        or not 1 <= parallel <= COLLATED_MAX_PARALLEL
    ):
        raise ValueError("collated policy is invalid")
    return {"enabled": enabled, "download_bytes_per_sec": rate, "download_parallel": parallel}


def valid_collated_item(raw):
    if not isinstance(raw, dict) or set(raw) != {"output_id", "nas_relative_path", "size_bytes", "sha256", "download_path"}:
        raise ValueError("collated item has invalid fields")
    output_id, size = raw["output_id"], raw["size_bytes"]
    if type(output_id) is not int or output_id < 1:
        raise ValueError("collated item has invalid output_id")
    if type(size) is not int or not 1 <= size <= COLLATED_MAX_BYTES:
        raise ValueError("collated item has invalid size_bytes")
    if raw["download_path"] != "/api/v1/account/collated/%d/download" % output_id:
        raise ValueError("collated item has invalid download_path")
    return {
        "output_id": output_id, "nas_relative_path": valid_collated_relative_path(raw["nas_relative_path"]),
        "size_bytes": size, "sha256": valid_sha256(raw["sha256"], "collated item"), "download_path": raw["download_path"],
    }


class ByteRateLimiter:
    """One shared bytes/second budget across every collated download worker."""

    def __init__(self, bytes_per_sec):
        self.bytes_per_sec = float(bytes_per_sec)
        self.lock = threading.Lock()
        self.next_free = time.monotonic()

    def acquire(self, size, stop_event):
        with self.lock:
            now = time.monotonic()
            start = max(now, self.next_free)
            self.next_free = start + size / self.bytes_per_sec
            delay = start - now
        if delay > 0 and stop_event.wait(delay):
            raise CollatedDownloadStopped("collated download stopped")


def open_collated_dir(cfg, relative_path, create=True):
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
    descriptor = os.open(str(cfg.output_dir), flags)
    try:
        for part in (JOINED_ROOT, *relative_path.split("/")[:-1]):
            try:
                child = os.open(part, flags, dir_fd=descriptor)
            except FileNotFoundError:
                if not create:
                    raise
                try:
                    os.mkdir(part, mode=0o755, dir_fd=descriptor)
                except FileExistsError:
                    pass
                os.fsync(descriptor)
                child = os.open(part, flags, dir_fd=descriptor)
            os.close(descriptor)
            descriptor = child
        return descriptor
    except BaseException:
        os.close(descriptor)
        raise


def hash_collated_entry(directory_fd, name, stop_event):
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    descriptor = os.open(name, flags, dir_fd=directory_fd)
    digest = hashlib.sha256()
    size = 0
    try:
        if not stat_module.S_ISREG(os.fstat(descriptor).st_mode):
            raise ExistingFileMismatch("collated entry is not a regular file")
        while True:
            if stop_event.is_set():
                raise CollatedDownloadStopped("collated hashing stopped")
            chunk = os.read(descriptor, COLLATED_CHUNK_BYTES * 8)
            if not chunk:
                break
            size += len(chunk)
            digest.update(chunk)
    finally:
        os.close(descriptor)
    return size, digest.hexdigest()


def collated_entry_stat(directory_fd, name):
    try:
        current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    except FileNotFoundError:
        return None
    if not stat_module.S_ISREG(current.st_mode):
        raise ExistingFileMismatch("collated entry is not a regular file")
    return current


def prepare_collated_download(cfg, item):
    prepared = request_json(cfg, "GET", item["download_path"], base=cfg.origin)
    if not isinstance(prepared, dict) or set(prepared) != {"url", "etag", "if_match", "size_bytes", "sha256", "expires_in_sec"}:
        raise RuntimeError("collated download response has invalid fields")
    url = prepared["url"]
    parsed = urllib.parse.urlsplit(url) if isinstance(url, str) else None
    if parsed is None or parsed.scheme != "https" or not parsed.hostname or parsed.username is not None or parsed.fragment:
        raise RuntimeError("collated download returned invalid URL")
    if prepared["size_bytes"] != item["size_bytes"] or prepared["sha256"] != item["sha256"]:
        raise ExistingFileMismatch("collated prepared bytes changed")
    etag = normalized_etag(prepared["etag"])
    if prepared["if_match"] != '"%s"' % etag:
        raise RuntimeError("collated download returned invalid If-Match")
    return {"url": url, "if_match": prepared["if_match"], "etag": etag}


def append_collated_bytes(prepared, descriptor, digest, start, item, limiter, stop_event):
    headers = {"User-Agent": USER_AGENT, "If-Match": prepared["if_match"], "Range": "bytes=%d-" % start}
    request = urllib.request.Request(prepared["url"], method="GET", headers=headers)
    with open_joined_url(request) as response:
        remember_response_secrets(response)
        status = getattr(response, "status", None) or response.getcode()
        if status == 206:
            expected = "bytes %d-%d/%d" % (start, item["size_bytes"] - 1, item["size_bytes"])
            if response.headers.get("Content-Range") != expected:
                raise RuntimeError("collated range returned invalid Content-Range")
        elif not (status == 200 and start == 0):
            raise RuntimeError("collated download returned HTTP %s" % status)
        if normalized_etag(response.headers.get("ETag")) != prepared["etag"]:
            raise ExistingFileMismatch("collated object identity drifted")
        written = start
        while written < item["size_bytes"]:
            if stop_event.is_set():
                raise CollatedDownloadStopped("collated download stopped at a chunk boundary")
            want = min(COLLATED_CHUNK_BYTES, item["size_bytes"] - written)
            limiter.acquire(want, stop_event)
            block = response.read(want)
            if not block:
                break
            offset = 0
            while offset < len(block):
                offset += os.write(descriptor, block[offset:])
            digest.update(block)
            written += len(block)
        if written != item["size_bytes"] or response.read(1):
            raise RuntimeError("collated body length mismatch")


@NAS_MEDIA_FENCE.background_delivery
def download_collated_item(cfg, item, limiter, stop_event):
    """Place one output at its contract path. Returns True when bytes were fetched."""
    relative = item["nas_relative_path"]
    name = relative.split("/")[-1]
    part_name = ".%s.collated-%d.part" % (name, item["output_id"])
    directory_fd = open_collated_dir(cfg, relative)
    try:
        if collated_entry_stat(directory_fd, name) is not None:
            size, digest = hash_collated_entry(directory_fd, name, stop_event)
            if size != item["size_bytes"] or digest != item["sha256"]:
                raise ExistingFileMismatch("existing collated file differs; it is never overwritten: %s" % relative)
            part = collated_entry_stat(directory_fd, part_name)
            if part is not None:
                os.unlink(part_name, dir_fd=directory_fd)
                os.fsync(directory_fd)
            return False
        prepared = prepare_collated_download(cfg, item)
        flags = os.O_RDWR | os.O_CREAT | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
        descriptor = os.open(part_name, flags, 0o644, dir_fd=directory_fd)
        try:
            opened = os.fstat(descriptor)
            if not stat_module.S_ISREG(opened.st_mode) or opened.st_nlink != 1:
                raise ExistingFileMismatch("collated partial is not a private regular file")
            start = opened.st_size
            if start >= item["size_bytes"]:
                os.ftruncate(descriptor, 0)
                start = 0
            digest = hashlib.sha256()
            os.lseek(descriptor, 0, os.SEEK_SET)
            remaining = start
            while remaining:
                chunk = os.read(descriptor, min(COLLATED_CHUNK_BYTES * 8, remaining))
                if not chunk:
                    raise ExistingFileMismatch("collated partial shrank while resuming")
                digest.update(chunk)
                remaining -= len(chunk)
            os.lseek(descriptor, start, os.SEEK_SET)
            try:
                append_collated_bytes(prepared, descriptor, digest, start, item, limiter, stop_event)
            finally:
                os.fsync(descriptor)
            if digest.hexdigest() != item["sha256"] or os.fstat(descriptor).st_size != item["size_bytes"]:
                os.ftruncate(descriptor, 0)
                os.fsync(descriptor)
                raise RuntimeError("collated checksum mismatch; partial restarted")
        finally:
            os.close(descriptor)
        try:
            os.link(part_name, name, src_dir_fd=directory_fd, dst_dir_fd=directory_fd, follow_symlinks=False)
        except FileExistsError:
            size, digest = hash_collated_entry(directory_fd, name, stop_event)
            if size != item["size_bytes"] or digest != item["sha256"]:
                raise ExistingFileMismatch("collated final appeared with different bytes: %s" % relative)
        os.unlink(part_name, dir_fd=directory_fd)
        os.fsync(directory_fd)
        return True
    finally:
        os.close(directory_fd)


def collated_bytes_needed(cfg, item):
    """Bytes still to be written for item: 0 when its final exists, the rest of a partial."""
    relative = item["nas_relative_path"]
    name = relative.split("/")[-1]
    try:
        directory_fd = open_collated_dir(cfg, relative, create=False)
    except FileNotFoundError:
        return item["size_bytes"]
    try:
        if collated_entry_stat(directory_fd, name) is not None:
            return 0
        part = collated_entry_stat(directory_fd, ".%s.collated-%d.part" % (name, item["output_id"]))
        if part is None or part.st_size >= item["size_bytes"]:
            return item["size_bytes"]
        return item["size_bytes"] - part.st_size
    finally:
        os.close(directory_fd)


def ack_collated_item(cfg, item):
    request_json(cfg, "POST", "/account/collated/ack", body={
        "output_id": item["output_id"], "nas_relative_path": item["nas_relative_path"],
        "size_bytes": item["size_bytes"], "sha256": item["sha256"],
    })


def report_collated_error(cfg, output_id, exc):
    try:
        request_json(cfg, "POST", "/account/collated/error", body={
            "output_id": int(output_id), "error": ("%s: %s" % (type(exc).__name__, exc))[:1000],
        })
    except Exception as report_exc:
        log("WARN", "collated error report failed: %s" % report_exc)


def drain_collated(cfg, runtime, stop_event):
    """Deliver one page of collated outputs. Returns True when any output landed."""
    if cfg.dry_run:
        return False
    page = request_json(cfg, "GET", "/account/collated?limit=%d" % COLLATED_PAGE_LIMIT)
    if not isinstance(page, dict) or set(page) != {"policy", "items"} or not isinstance(page["items"], list):
        raise RuntimeError("collated response is invalid")
    policy = valid_collated_policy(page["policy"])
    if not policy["enabled"] or not page["items"]:
        return False
    items = [valid_collated_item(raw) for raw in page["items"]]
    limiter = ByteRateLimiter(policy["download_bytes_per_sec"])
    delivered = []

    def deliver(item):
        if stop_event.is_set():
            return
        # Reserve the whole output in the shared runtime ledger so parallel
        # collated downloads and raw delivery never overcommit the same bytes.
        needed = collated_bytes_needed(cfg, item)
        if not runtime.reserve_joined_storage(cfg, storage_status(cfg), needed):
            raise CollatedDownloadStopped("collated delivery yielded to the NAS free-space reserve")
        try:
            fetched = download_collated_item(cfg, item, limiter, stop_event)
            ack_collated_item(cfg, item)
        except CollatedDownloadStopped:
            raise
        except Exception as exc:
            log("WARN", "collated output_id=%d deferred: %s" % (item["output_id"], exc))
            report_collated_error(cfg, item["output_id"], exc)
            return
        finally:
            runtime.release_storage_reservation(needed)
        delivered.append(item["output_id"])
        log("INFO", "collated output_id=%d bytes=%d saved=%s%s" % (
            item["output_id"], item["size_bytes"], cfg.output_dir / JOINED_ROOT / item["nas_relative_path"],
            "" if fetched else " existing"))

    with concurrent.futures.ThreadPoolExecutor(max_workers=policy["download_parallel"]) as executor:
        futures = [executor.submit(deliver, item) for item in items]
        stopped = None
        for future in futures:
            try:
                future.result()
            except CollatedDownloadStopped as exc:
                stopped = exc
    if stopped is not None and not delivered:
        log("INFO", "collated delivery paused: %s" % stopped)
    return bool(delivered)


def release_clip(cfg, recording_id, clip_id):
    path = "/account/recordings/%d/clips/%d/release" % (recording_id, clip_id)
    try:
        request_json(cfg, "POST", path)
    except urllib.error.HTTPError as exc:
        if exc.code not in (404, 410):
            raise


def release_clips(cfg, clips):
    body = {"clips": [
        {"recording_id": int(clip["recording_id"]), "clip_id": int(clip["clip_id"])}
        for clip in clips
    ]}
    try:
        request_json(cfg, "POST", "/account/clips/release", body=body)
    except urllib.error.HTTPError as exc:
        if exc.code != 404:
            raise
        # Compatibility during a backend-first rolling deploy. The batch route is
        # live before this client is promoted; this fallback can be removed after
        # every installation has crossed that release.
        for clip in clips:
            release_clip(cfg, int(clip["recording_id"]), int(clip["clip_id"]))


def stitch_sidecar_path(clip_path):
    return clip_path.with_name(clip_path.name + ".stoarama.json")


def stitch_provenance(clip):
    """Return the durable metadata needed to order and verify this clip later.

    The pull feed is deliberately ID-cursor ordered for exactly-once delivery,
    while concurrent uploads may commit out of media order. Generation-aware
    clips must therefore be grouped by capture_generation and ordered by
    capture_sequence. Legacy clips have null provenance and fall back to their
    explicit clip timestamps.
    """
    return {
        "schema_version": 2 if clip.get("capture_attempt_id") else 1,
        "clip_id": int(clip["clip_id"]),
        "recording_id": int(clip["recording_id"]),
        "recording_job_id": clip.get("recording_job_id"),
        "capture_generation": clip.get("capture_generation"),
        "capture_sequence": clip.get("capture_sequence"),
        "capture_attempt_id": clip.get("capture_attempt_id"),
        "timestamp_contract_version": clip.get("timestamp_contract_version"),
        "timestamp_contract_status": clip.get("timestamp_contract_status"),
        "timestamp_contract_reason": clip.get("timestamp_contract_reason"),
        "timestamp_contract": clip.get("timestamp_contract"),
        "capture_attempt_id": clip.get("capture_attempt_id"),
        "timestamp_contract_version": clip.get("timestamp_contract_version"),
        "timestamp_contract": clip.get("timestamp_contract"),
        "timestamp_contract_status": clip.get("timestamp_contract_status"),
        "timestamp_contract_reason": clip.get("timestamp_contract_reason"),
        "clip_start_at": clip.get("clip_start_at"),
        "clip_end_at": clip.get("clip_end_at"),
        "size_bytes": int(clip["size_bytes"]),
        "sha256": str(clip.get("sha256", "")).lower(),
        "relative_path": str(clip.get("relative_path", "")),
    }


def write_stitch_sidecar(clip_path, clip):
    payload = json.dumps(stitch_provenance(clip), sort_keys=True, separators=(",", ":"))
    atomic_write(stitch_sidecar_path(clip_path), (payload + "\n").encode("utf-8"))


@NAS_MEDIA_FENCE.delivery
def process_clip(cfg, clip, release=True, prepare_download=None):
    clip_id = int(clip["clip_id"])
    recording_id = int(clip["recording_id"])
    expected_bytes = int(clip["size_bytes"])
    expected_sha = str(clip.get("sha256", "")).lower()
    if expected_bytes < 0 or len(expected_sha) != 64 or any(ch not in "0123456789abcdef" for ch in expected_sha):
        raise ValueError("clip %d has invalid integrity metadata" % clip_id)
    final_path = cfg.output_dir / valid_relative_path(clip)
    final_path.parent.mkdir(parents=True, exist_ok=True)
    try:
        exists = verified_file(final_path, expected_bytes, expected_sha)
    except ExistingFileMismatch as exc:
        quarantine = final_path.with_name(f".{final_path.name}.invalid-{clip_id}-{time.time_ns()}")
        if quarantine.exists():
            raise ExistingFileMismatch(quarantine) from exc
        os.replace(str(final_path), str(quarantine))
        fsync_dir(final_path.parent)
        log("WARN", f"clip_id={clip_id} quarantined checksum-mismatched file={quarantine}")
        exists = False
    retries = 0
    downloaded_bytes = 0
    if not exists:
        temp_path = final_path.with_name(final_path.name + ".part-%d" % clip_id)

        def download():
            presigned = prepare_download() if prepare_download else request_json(cfg, "GET", str(clip["download_path"]), base=cfg.origin)
            url = str(presigned.get("url", ""))
            if not url:
                raise RuntimeError("clip %d presign returned no URL" % clip_id)
            download_verified(url, temp_path, expected_bytes, expected_sha, presigned.get("headers"))

        _, retries = retry_transient(download, clip_id, "download")
        os.replace(str(temp_path), str(final_path))
        fsync_dir(final_path.parent)
        downloaded_bytes = expected_bytes
    # Persist stitch provenance durably before releasing the server-side row.
    # If the process crashes after this write, replay safely verifies the MP4 and
    # rewrites the same deterministic sidecar before retrying release.
    write_stitch_sidecar(final_path, clip)
    if release and not cfg.dry_run:
        _, release_retries = retry_transient(
            lambda: release_clip(cfg, recording_id, clip_id), clip_id, "release"
        )
        retries += release_retries
    suffix = " dry-run" if cfg.dry_run else (" released" if release else " ready")
    log("INFO", "clip_id=%d bytes=%d saved=%s%s" % (clip_id, expected_bytes, final_path, suffix))
    return clip_id, expected_bytes, downloaded_bytes, retries


class RestoreLocalError(RuntimeError):
    """A restore the local copy cannot satisfy: outcome is reported as-is."""

    def __init__(self, outcome, message):
        super().__init__(message)
        self.outcome = outcome


class SelectedVerifyAborted(Exception):
    """No authoritative filesystem result; leave the lease available for retry."""



ORIGINAL_WITNESS_POLICY = "registered-day-presentation-v1"


def valid_original_witness_context(raw):
    if not isinstance(raw, dict) or set(raw) != {
        "policy_version", "registered_start_utc", "registered_end_utc", "timezone", "local_date"
    } or raw.get("policy_version") != ORIGINAL_WITNESS_POLICY:
        raise ValueError("invalid original witness context")
    try:
        from zoneinfo import ZoneInfo
        start = parse_certification_timestamp(raw["registered_start_utc"], "registered_start_utc")
        end = parse_certification_timestamp(raw["registered_end_utc"], "registered_end_utc")
        zone = ZoneInfo(raw["timezone"])
        span = end - start
        span_us = (span.days * 86400 + span.seconds) * 1000000 + span.microseconds
        if not 0 < span_us <= 900000000:
            raise ValueError("invalid original witness registered span")
        if (start.astimezone(zone).date().isoformat() != raw["local_date"]
                or (end - datetime.timedelta(microseconds=1)).astimezone(zone).date().isoformat() != raw["local_date"]):
            raise ValueError("original witness crosses registered local dates")
    except (ImportError, KeyError, TypeError, MediaCertificationError) as exc:
        raise ValueError("invalid original witness registered date") from exc
    return dict(raw, registered_span_us=span_us)


def original_presentation_intervals(frames, registered_span_us):
    """Conservative normalized presentation union on the registered date.
    
    This is a stored-media observation, never a camera UTC or ingest contract.
    Merge exact rational intervals before inward microsecond quantization.
    """
    from fractions import Fraction
    if not isinstance(frames, list) or not 1 <= len(frames) <= 120000:
        raise MediaCertificationError("original presentation frame bound exceeded")
    if type(registered_span_us) is not int or not 0 < registered_span_us <= 900000000:
        raise MediaCertificationError("invalid registered presentation cap")
    cap = Fraction(registered_span_us, 1000000)
    origin = None
    previous = None
    spans = []
    for frame in frames:
        if not isinstance(frame, dict):
            raise MediaCertificationError("invalid original frame observation")
        values = [frame.get(k) for k in (
            "best_effort_timestamp", "duration_timestamp", "time_base_numerator", "time_base_denominator"
        )]
        if any(type(v) is not int for v in values):
            raise MediaCertificationError("missing original frame timing")
        pts, duration, numerator, denominator = values
        if duration <= 0 or numerator <= 0 or denominator <= 0:
            raise MediaCertificationError("unsupported original frame timing")
        at = Fraction(pts * numerator, denominator)
        if previous is not None and at < previous:
            raise MediaCertificationError("original presentation order is invalid")
        if origin is None:
            origin = at
        previous = at
        a, b = max(Fraction(0), at - origin), min(cap, at - origin + Fraction(duration * numerator, denominator))
        if b > a:
            spans.append((a, b))
    merged = []
    for a, b in spans:
        if merged and a <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], b)
        else:
            merged.append([a, b])
    out = []
    for a, b in merged:
        a *= 1000000
        b *= 1000000
        lo = -((-a.numerator) // a.denominator)
        hi = b.numerator // b.denominator
        if hi > lo:
            if out and lo <= out[-1][1]:
                out[-1][1] = max(out[-1][1], hi)
            else:
                out.append([lo, hi])
    if not out:
        raise MediaCertificationError("no supported positive original presentation")
    # A bounded subset remains a lower bound; never fill omitted gaps.
    return out[:1024]


def measure_original_witness(cfg, task, source_fd, check_active, check_stable, tool_installer=None, deadline=None):
    proof = {"policy_version": ORIGINAL_WITNESS_POLICY, "status": "unverified",
             "reason": "", "video_frames": 0, "strict_full_decode": False,
             "intervals_us": [], "ffmpeg_sha256": "", "ffprobe_sha256": ""}
    try:
        check_active()
        class LeaseCancellation:
            def __init__(self):
                self.pause = threading.Event()
            def is_set(self):
                check_active()
                return False
            def wait(self, timeout):
                check_active()
                self.pause.wait(min(max(float(timeout), 0), .05))
                check_active()
                return False
        cancel = LeaseCancellation()
        import platform
        install_deadline = time.monotonic() + BENCHMARK_TOOL_INSTALL_SEC
        if deadline is not None:
            install_deadline = min(install_deadline, deadline)
        if tool_installer is None:
            tools = ensure_benchmark_tools(cfg.state_dir, platform.machine(), install_deadline, cancel=cancel)
        else:
            tools = tool_installer(cfg.state_dir, platform.machine(), install_deadline)
        check_active()
        check_stable()
        tool_path = "/proc/self/fd/%d" % source_fd
        strict_decode_media_cancellable(
            tool_path, tools["ffmpeg"], cancel, pass_fds=(source_fd,), threads=1
        )
        check_stable()
        _, observed = recompute_timestamp_contract(
            tool_path, tools["ffprobe"], cancel, pass_fds=(source_fd,)
        )
        check_stable()
        frames = observed.get("_video_frames")
        intervals = original_presentation_intervals(
            frames, task["original_witness"]["registered_span_us"]
        )
        proof.update(status="verified", strict_full_decode=True, video_frames=len(frames),
                     intervals_us=intervals, ffmpeg_sha256=tools["ffmpeg_sha256"],
                     ffprobe_sha256=tools["ffprobe_sha256"])
        check_active()
    except (OSError, RuntimeError, ValueError, KeyError, MediaCertificationError) as exc:
        proof["reason"] = str(exc).encode("utf-8")[:500].decode("utf-8", "ignore") or "original witness unsupported"
    return proof


def valid_selected_verify_task(task):
    """Validate one immutable, server-derived selected-file manifest item."""
    if not isinstance(task, dict):
        raise ValueError("invalid selected verify task")
    out = {}
    for name in ("item_id", "attempt", "size_bytes"):
        value = task.get(name)
        if type(value) is not int or value <= 0:
            raise ValueError("invalid selected verify task %s" % name)
        out[name] = value
    if task.get("kind") not in ("raw", "collated", "joined"):
        raise ValueError("invalid selected verify task kind")
    out["kind"] = task["kind"]
    for name in ("sha256", "plan_sha256"):
        value = task.get(name)
        if not isinstance(value, str) or len(value) != 64 or any(ch not in "0123456789abcdef" for ch in value):
            raise ValueError("invalid selected verify task %s" % name)
        out[name] = value
    raw = task.get("relative_path")
    if not isinstance(raw, str) or not raw or raw.startswith("/") or "\\" in raw or any(p in ("", ".", "..") for p in raw.split("/")):
        raise ValueError("invalid selected verify path")
    if raw.split("/")[0] in INVENTORY_ROOT_EXCLUSIONS or ((raw.split("/")[0] == JOINED_ROOT) != (out["kind"] != "raw")):
        raise ValueError("selected verify path does not match kind")
    out["relative_path"] = Path(raw)
    try:
        out["expires_at"] = parse_certification_timestamp(task.get("expires_at"), "expires_at")
    except MediaCertificationError as exc:
        raise ValueError(str(exc)) from exc
    if out["size_bytes"] > 32 * 1024 ** 3:
        raise ValueError("selected verify file exceeds 32 GiB bound")
    if task.get("original_witness") is not None:
        if out["kind"] != "raw":
            raise ValueError("original witnesses support raw clips only")
        out["original_witness"] = valid_original_witness_context(task["original_witness"])
    return out


def selected_verify_root_identity(root):
    info = os.lstat(root)
    if not stat_module.S_ISDIR(info.st_mode) or not os.path.ismount(str(root)):
        raise RuntimeError("selected verify NAS root is not mounted")
    return info.st_dev, info.st_ino


def run_selected_verify_task(cfg, task, stop_event=None, tool_installer=None):
    """Read-only direct check: confined regular file, exact size, then full SHA."""
    started = time.monotonic()
    result = {"attempt": task["attempt"], "plan_sha256": task["plan_sha256"],
              "outcome": "unverified", "error": "", "duration_ms": 0}
    deadline = started + min(3 * 3600, (task["expires_at"] - datetime.datetime.now(datetime.timezone.utc)).total_seconds() - 15)
    def check_active():
        if (stop_event is not None and stop_event.is_set()) or time.monotonic() >= deadline:
            raise SelectedVerifyAborted("selected verification cancelled or lease deadline reached")
    fd = None
    try:
        check_active()
        root_identity = selected_verify_root_identity(cfg.output_dir)
        try:
            path, path_stat = confined_regular_file(cfg.output_dir, task["relative_path"])
        except MediaCertificationError as exc:
            if isinstance(exc.__cause__, FileNotFoundError):
                if selected_verify_root_identity(cfg.output_dir) != root_identity:
                    raise RuntimeError("selected verify NAS root changed")
                check_active()
                result["outcome"] = "missing"
            if result["outcome"] != "missing" and exc.__cause__ is None:
                result["outcome"] = "conflict"
            raise RuntimeError(str(exc)) from exc
        fd = os.open(str(path), os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_NONBLOCK", 0))
        before = os.fstat(fd)
        if certification_identity(before) != certification_identity(path_stat):
            raise RuntimeError("local file changed while opening")
        def check_stable_identity():
            _, final_path_stat = confined_regular_file(cfg.output_dir, task["relative_path"])
            if (certification_identity(os.fstat(fd)) != certification_identity(before)
                    or certification_identity(final_path_stat) != certification_identity(before)):
                raise RuntimeError("local file or canonical path changed while hashing")
            if selected_verify_root_identity(cfg.output_dir) != root_identity:
                raise RuntimeError("selected verify NAS root changed")
            check_active()
        if before.st_size != task["size_bytes"]:
            check_stable_identity()
            result["outcome"] = "conflict"
            raise RuntimeError("local size differs from manifest")
        digest = hashlib.sha256()
        while True:
            check_active()
            chunk = os.read(fd, RESTORE_BLOCK_BYTES)
            if not chunk:
                break
            digest.update(chunk)
        check_stable_identity()
        if digest.hexdigest() != task["sha256"]:
            result["outcome"] = "conflict"
            raise RuntimeError("local sha256 differs from manifest")
        if task.get("original_witness") is not None:
            result["original_witness"] = measure_original_witness(
                cfg, task, fd, check_active, check_stable_identity, tool_installer=tool_installer, deadline=deadline
            )
            check_stable_identity()
        result["outcome"] = "match"
    except (OSError, RuntimeError, MediaCertificationError) as exc:
        result["error"] = str(exc)
    finally:
        if fd is not None:
            os.close(fd)
    if result["outcome"] != "match":
        result.pop("original_witness", None)
    result["duration_ms"] = max(0, round((time.monotonic() - started) * 1000))
    result["error"] = result["error"].encode("utf-8")[:500].decode("utf-8", "ignore")
    return result


def valid_restore_task(task):
    if not isinstance(task, dict):
        raise ValueError("invalid restore task")
    out = {}
    for name in ("task_id", "attempt", "clip_id", "size_bytes"):
        value = task.get(name)
        if type(value) is not int or value <= 0:
            raise ValueError("invalid restore task %s" % name)
        out[name] = value
    if out["size_bytes"] > RESTORE_MAX_BYTES:
        raise ValueError("restore task exceeds the single-PUT ceiling")
    sha = task.get("sha256")
    if not isinstance(sha, str) or len(sha) != 64 or any(ch not in "0123456789abcdef" for ch in sha):
        raise ValueError("invalid restore task sha256")
    out["sha256"] = sha
    out["relative_path"] = valid_relative_path({"clip_id": out["clip_id"], "relative_path": task.get("relative_path")})
    put = task.get("put")
    if not isinstance(put, dict):
        raise ValueError("invalid restore capability")
    url = urllib.parse.urlsplit(str(put.get("url", "")))
    headers = put.get("headers") or {}
    if url.scheme != "https" or not url.hostname or put.get("method") != "PUT" or not isinstance(headers, dict):
        raise ValueError("restore capability must be an https PUT")
    out["url"] = url
    out["headers"] = {str(k): str(v) for k, v in headers.items()}
    return out


class RestoreBody:
    """Streams the already-verified descriptor and hashes exactly what is sent."""

    def __init__(self, fd, size):
        self.fd = fd
        self.remaining = size
        self.sent = 0
        self.digest = hashlib.sha256()

    def read(self, amount=-1):
        if self.remaining <= 0:
            return b""
        count = RESTORE_BLOCK_BYTES if amount is None or amount < 0 else min(amount, RESTORE_BLOCK_BYTES)
        chunk = os.read(self.fd, min(count, self.remaining))
        if not chunk:
            raise RestoreLocalError("local_mismatch", "local file shrank during upload")
        self.remaining -= len(chunk)
        self.sent += len(chunk)
        self.digest.update(chunk)
        return chunk


def open_restore_source(cfg, task):
    """Open the clip under the NAS root and prove its size and sha256 first."""
    try:
        path, path_stat = confined_regular_file(cfg.output_dir, str(task["relative_path"]))
    except MediaCertificationError as exc:
        raise RestoreLocalError("local_missing", str(exc)) from exc
    fd = os.open(str(path), os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0))
    try:
        before = os.fstat(fd)
        if certification_identity(before) != certification_identity(path_stat):
            raise RestoreLocalError("local_mismatch", "local file changed while opening")
        if before.st_size != task["size_bytes"]:
            raise RestoreLocalError("local_mismatch", "local size %d differs from %d" % (before.st_size, task["size_bytes"]))
        digest = hashlib.sha256()
        while True:
            chunk = os.read(fd, RESTORE_BLOCK_BYTES)
            if not chunk:
                break
            digest.update(chunk)
        if digest.hexdigest() != task["sha256"]:
            raise RestoreLocalError("local_mismatch", "local sha256 differs from the recorded sha256")
        if certification_identity(os.fstat(fd)) != certification_identity(before):
            raise RestoreLocalError("local_mismatch", "local file changed while hashing")
        os.lseek(fd, 0, os.SEEK_SET)
        return fd
    except BaseException:
        os.close(fd)
        raise


# Restores make three requests per clip (lease share, PUT, report). Opening a
# fresh connection for each costs a DNS lookup and a TLS handshake; on NAS
# hosts with a slow first resolver that was ~4 s per request and dominated
# restore time. Each thread therefore keeps one connection per host alive.
_restore_http = threading.local()
_RESTORE_STALE_ERRORS = (http.client.RemoteDisconnected, ConnectionResetError, BrokenPipeError)


def reset_restore_connections():
    for conn in getattr(_restore_http, "conns", {}).values():
        conn.close()
    _restore_http.conns = {}


def restore_https(netloc, method, target, body, headers, timeout, read_limit=None):
    """One request on this thread's keep-alive connection to netloc.

    With read_limit, at most that many response bytes are read; a longer
    response closes the connection instead of being buffered."""
    conns = getattr(_restore_http, "conns", None)
    if conns is None:
        conns = _restore_http.conns = {}
    conn = conns.get(netloc)
    if conn is not None and time.monotonic() - getattr(conn, "stoarama_last_used", 0) > RESTORE_KEEPALIVE_IDLE_SEC:
        conn.close()
        conn = None
    if conn is None:
        conn = http.client.HTTPSConnection(netloc, timeout=timeout, blocksize=RESTORE_BLOCK_BYTES)
        conns[netloc] = conn
    try:
        conn.timeout = timeout
        if conn.sock is not None:
            conn.sock.settimeout(timeout)
        conn.request(method, target, body=body, headers=headers)
        response = conn.getresponse()
        remember_response_secrets(response)
        data = response.read() if read_limit is None else response.read(read_limit + 1)
    except BaseException:
        conns.pop(netloc, None)
        conn.close()
        raise
    if read_limit is not None and len(data) > read_limit:
        data = data[:read_limit]
        conns.pop(netloc, None)
        conn.close()
    elif response.will_close:
        conns.pop(netloc, None)
        conn.close()
    else:
        conn.stoarama_last_used = time.monotonic()
    return response.status, data


def restore_api(cfg, path, body, retry_stale=False, timeout=HTTP_TIMEOUT_SEC):
    """POST JSON to the API over a keep-alive connection; request_json semantics."""
    base = getattr(cfg, "api_base", "")
    parsed = urllib.parse.urlsplit(base + path)
    proxied = bool(urllib.request.getproxies().get("https")) and not urllib.request.proxy_bypass(parsed.netloc)
    if parsed.scheme != "https" or proxied:
        # Plain HTTP (tests) and proxied installs keep urllib's transport.
        return request_json(cfg, "POST", path, body=body, timeout=timeout)
    data = json.dumps(body).encode("utf-8")
    headers = {"User-Agent": USER_AGENT, "Authorization": "Bearer " + cfg.api_key, "Content-Type": "application/json"}
    headers.update(cleanup_session_headers(path))
    target = parsed.path + ("?" + parsed.query if parsed.query else "")
    try:
        status, raw = restore_https(parsed.netloc, "POST", target, data, headers, timeout)
    except _RESTORE_STALE_ERRORS:
        if not retry_stale:
            raise
        status, raw = restore_https(parsed.netloc, "POST", target, data, headers, timeout)
    if status >= 400:
        raise urllib.error.HTTPError(base + path, status, "HTTP %d" % status, {}, None)
    result = json.loads(raw.decode("utf-8")) if raw else {}
    CLIENT_LOG_RING.add_secrets(diagnostic_secret_values(result, response=True))
    return result


def restore_put(task, body):
    url = task["url"]
    headers = dict(task["headers"])
    headers["Content-Length"] = str(task["size_bytes"])
    headers["User-Agent"] = USER_AGENT
    status, _ = restore_https(url.netloc, "PUT", url.path + ("?" + url.query if url.query else ""), body, headers,
                              RESTORE_SOCKET_TIMEOUT_SEC, read_limit=64 * 1024)
    return status


def run_restore_task(cfg, task):
    """Verify the local copy, upload it create-only, and describe the outcome."""
    started_at = utc_now_precise()
    started = time.monotonic()
    result = {"attempt": task["attempt"], "outcome": "upload_failed", "error": "", "bytes_uploaded": 0,
              "duration_ms": 0, "started_at": started_at, "client_version": CLIENT_VERSION}
    fd = None
    body = None
    try:
        fd = open_restore_source(cfg, task)
        upload_started = time.monotonic()
        body = RestoreBody(fd, task["size_bytes"])
        try:
            status = restore_put(task, body)
        except _RESTORE_STALE_ERRORS:
            # A kept-alive connection the peer already closed: rewind the
            # proven descriptor and retry once on a fresh connection. If the
            # first attempt had landed, this one gets 412 and reports exists.
            os.lseek(fd, 0, os.SEEK_SET)
            body = RestoreBody(fd, task["size_bytes"])
            status = restore_put(task, body)
        result["duration_ms"] = max(0, round((time.monotonic() - upload_started) * 1000))
        if status == 412:
            # The key already exists (an earlier attempt landed): the server
            # re-hashes it and accepts it only if it is exactly these bytes.
            result["outcome"] = "exists"
        elif 200 <= status < 300:
            result["outcome"] = "uploaded"
            result["bytes_uploaded"] = body.sent
        else:
            result["error"] = "restore PUT returned HTTP %d" % status
    except RestoreLocalError as exc:
        result["outcome"], result["error"] = exc.outcome, str(exc)
    except Exception as exc:
        result["error"] = "%s: %s" % (type(exc).__name__, exc)
    finally:
        if fd is not None:
            os.close(fd)
    if not result["duration_ms"]:
        result["duration_ms"] = max(0, round((time.monotonic() - started) * 1000))
    result["error"] = result["error"].encode("utf-8")[:500].decode("utf-8", "ignore")
    return result


def report_restore(cfg, task_id, result, sleep=time.sleep):
    """Report once, retrying transient failures; 409 means the lease moved on."""
    for attempt in range(1, RESTORE_REPORT_ATTEMPTS + 1):
        try:
            # A replay after a stale connection is safe: a duplicate report is a 409.
            return restore_api(cfg, "/account/connections/nas-restore/%d/result" % task_id, result, retry_stale=True)
        except urllib.error.HTTPError as exc:
            if exc.code == 409:
                return {"state": "stale"}
            if not transient_error(exc) or attempt == RESTORE_REPORT_ATTEMPTS:
                raise
        except Exception as exc:
            if not transient_error(exc) or attempt == RESTORE_REPORT_ATTEMPTS:
                raise
        sleep(RESTORE_REPORT_BACKOFF_SEC * attempt)


def restore_task_and_report(cfg, task):
    """Run one restore and report it from the same worker thread, so the
    server's full re-hash of one object overlaps the other uploads."""
    result = run_restore_task(cfg, task)
    try:
        state = (report_restore(cfg, task["task_id"], result) or {}).get("state", "unknown")
    except Exception as exc:
        state = "unreported"
        log("WARN", "restore %d report failed: %s" % (task["task_id"], exc))
    if state != "verified":
        log("WARN", "restore %d clip=%d outcome=%s state=%s %s" % (
            task["task_id"], task["clip_id"], result["outcome"], state, result["error"]))
    return result, state


def lease_restores(cfg, max_tasks):
    """Lease up to max_tasks restores; returns (valid tasks, server retry_after)."""
    # Never replayed: a lease whose response was lost just expires.
    lease = restore_api(cfg, "/account/connections/nas-restore/lease",
                        {"client_version": CLIENT_VERSION, "max_tasks": max(1, min(RESTORE_MAX_LEASE, max_tasks))})
    if not isinstance(lease, dict) or not isinstance(lease.get("tasks", []), list):
        raise RuntimeError("invalid restore lease response")
    tasks = []
    for raw in lease.get("tasks") or []:
        try:
            tasks.append(valid_restore_task(raw))
        except ValueError as exc:
            # Unusable task: fail it explicitly if it can be addressed at all,
            # otherwise its lease simply expires.
            task_id, attempt = (raw or {}).get("task_id"), (raw or {}).get("attempt")
            if type(task_id) is int and type(attempt) is int and task_id > 0 and attempt > 0:
                bad = {"attempt": attempt, "outcome": "local_missing", "error": "invalid restore task: %s" % exc,
                       "bytes_uploaded": 0, "duration_ms": 0, "started_at": utc_now_precise(), "client_version": CLIENT_VERSION}
                try:
                    report_restore(cfg, task_id, bad)
                except Exception as report_exc:
                    log("WARN", "restore %d report failed: %s" % (task_id, report_exc))
    return tasks, lease.get("retry_after_sec", RESTORE_ERROR_WAIT_SEC)


def restore_once(cfg, stop_event=None):
    """Keep restore_workers restores in flight until the queue is empty.

    A task is leased only when a worker is free to start it, so no lease or
    PUT capability ages in a local queue. Returns the server's idle wait.
    """
    in_flight = set()
    retry_after = RESTORE_ERROR_WAIT_SEC
    exhausted = False
    started = time.monotonic()
    counts = {}
    uploaded_bytes = 0
    with concurrent.futures.ThreadPoolExecutor(max_workers=cfg.restore_workers) as pool:
        while True:
            free = cfg.restore_workers - len(in_flight)
            if free > 0 and not exhausted and not (stop_event is not None and stop_event.is_set()):
                try:
                    tasks, retry_after = lease_restores(cfg, free)
                except Exception as exc:
                    if not in_flight and not counts:
                        raise
                    log("WARN", "nas restore lease failed: %s" % exc)
                    tasks, retry_after = [], RESTORE_ERROR_WAIT_SEC
                if not tasks:
                    exhausted = True
                for task in tasks:
                    in_flight.add(pool.submit(restore_task_and_report, cfg, task))
            if not in_flight:
                break
            done, _ = concurrent.futures.wait(in_flight, return_when=concurrent.futures.FIRST_COMPLETED)
            for future in done:
                in_flight.discard(future)
                result, state = future.result()
                uploaded_bytes += result["bytes_uploaded"]
                counts[state] = counts.get(state, 0) + 1
    if counts:
        seconds = max(time.monotonic() - started, 0.001)
        log("INFO", "nas restore run tasks=%d bytes=%d seconds=%.1f mbps=%.1f %s" % (
            sum(counts.values()), uploaded_bytes, seconds, uploaded_bytes * 8 / seconds / 1e6,
            " ".join("%s=%d" % item for item in sorted(counts.items()))))
    return retry_after


def restore_wait(seconds):
    try:
        seconds = int(seconds)
    except (TypeError, ValueError):
        seconds = RESTORE_ERROR_WAIT_SEC
    return min(max(seconds, RESTORE_MIN_WAIT_SEC), RESTORE_MAX_WAIT_SEC)


def selected_verify_once(cfg, stop_event=None):
    """Lease a bounded batch and report direct read-only filesystem evidence."""
    lease = restore_api(cfg, "/account/connections/selected-verify/lease",
                        {"client_version": CLIENT_VERSION, "max_tasks": 1, "original_witness": True})
    if not isinstance(lease, dict) or not isinstance(lease.get("tasks", []), list):
        raise RuntimeError("invalid selected verify lease response")
    for raw in lease.get("tasks") or []:
        try:
            task = valid_selected_verify_task(raw)
        except ValueError as exc:
            log("WARN", "invalid selected verify task: %s" % exc)
            continue
        try:
            result = run_selected_verify_task(cfg, task, stop_event)
        except SelectedVerifyAborted:
            # Cancellation and time bounds do not say anything about the file.
            # Do not turn them into a terminal integrity conflict.
            return RESTORE_ERROR_WAIT_SEC
        result["client_version"] = CLIENT_VERSION
        restore_api(cfg, "/account/connections/selected-verify/%d/result" % task["item_id"], result, retry_stale=True)
    return lease.get("retry_after_sec", RESTORE_ERROR_WAIT_SEC)


def selected_verify_loop(cfg, stop_event):
    wait = 30
    while not stop_event.wait(wait):
        if not NAS_MEDIA_FENCE.wait_maintenance(stop_event):
            return
        try:
            retry = selected_verify_once(cfg, stop_event)
            # Each completed file gets a fresh individual lease immediately.
            # Do not add a second of idle time per file to a million-file audit.
            wait = 0 if retry == 0 else restore_wait(retry)
        except Exception as exc:
            log("WARN", "selected NAS verify deferred: %s" % exc)
            wait = RESTORE_ERROR_WAIT_SEC


def restore_loop(cfg, stop_event, rng=random):
    """Background NAS -> R2 restore worker; never raises and never blocks updates."""
    wait = rng.uniform(*RESTORE_STARTUP_DELAY_SEC)
    while not stop_event.wait(wait):
        if not NAS_MEDIA_FENCE.wait_maintenance(stop_event):
            return
        try:
            wait = restore_wait(restore_once(cfg, stop_event))
        except Exception as exc:
            log("WARN", "nas restore deferred: %s" % exc)
            wait = RESTORE_ERROR_WAIT_SEC


def drain_page(cfg, runtime, inventory=None):
    require_storage_capacity(cfg, runtime)
    page, list_retries = retry_transient(
        lambda: request_json(cfg, "GET", "/account/clips?after_id=%d&limit=%d" % (runtime.cursor_id, LIST_PAGE_LIMIT)),
        runtime.cursor_id, "drain-list",
    )
    clips = page.get("clips", [])
    if not isinstance(clips, list):
        raise RuntimeError("clips response is not a list")
    runtime.list_succeeded = True
    if not clips:
        return False
    runtime.set_phase(Phase.DRAINING)
    started = time.monotonic()
    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=cfg.download_workers) as executor:
        futures = [executor.submit(prepare_clip_with_capacity, cfg, runtime, clip) for clip in clips]
        for clip, future in zip(clips, futures):
            try:
                results.append((int(clip["clip_id"]), future.result(), None))
            except Exception as exc:
                results.append((int(clip.get("clip_id", 0)), None, exc))
                log("ERROR", "clip_id=%s failed: %s" % (clip.get("clip_id", "?"), exc))
    cursor = runtime.cursor_id
    successes = []
    prepared = [result for _, result, error in results if error is None]
    downloaded_bytes = sum(result[2] for result in prepared)
    retries = list_retries + sum(result[3] for result in prepared) + sum(
        error.retries for _, _, error in results if isinstance(error, RetryExhausted)
    )
    clip_by_id = {int(clip["clip_id"]): clip for clip in clips}
    prepared_ids = [clip_id for clip_id, _, error in results if error is None]
    if inventory is not None and not cfg.dry_run:
        # The durable local commit and bounded server sync happen before any
        # release call. If either fails, the page stays server-retained.
        for clip_id in prepared_ids:
            inventory.record_verified(clip_by_id[clip_id])
        inventory.sync_clip_ids(cfg, prepared_ids)
    result_by_id = {clip_id: result for clip_id, result, error in results if error is None}
    releasable = []
    for clip_id, _, error in results:
        if error is not None:
            break
        releasable.append(clip_by_id[clip_id])
    try:
        if releasable and not cfg.dry_run:
            require_storage_capacity(cfg, runtime)
            _, release_retries = retry_transient(
                lambda: release_clips(cfg, releasable), int(releasable[0]["clip_id"]), "release-batch"
            )
            retries += release_retries
    except Exception as exc:
        if isinstance(exc, RetryExhausted):
            retries += exc.retries
        first_id = int(releasable[0]["clip_id"]) if releasable else 0
        log("ERROR", "clip_id=%d release batch failed: %s" % (first_id, exc))
        if releasable:
            for index, (clip_id, _, error) in enumerate(results):
                if clip_id == first_id and error is None:
                    results[index] = (clip_id, None, exc)
                    break
        releasable = []
    for clip in releasable:
        clip_id = int(clip["clip_id"])
        successes.append(result_by_id[clip_id])
        cursor = clip_id
    if successes:
        runtime.add_successes(cfg, cursor, successes)
    failures = [(clip_id, error) for clip_id, _, error in results if error is not None]
    runtime.set_batch(len(prepared), downloaded_bytes, time.monotonic() - started, retries, len(failures))
    if failures:
        first_id, first_error = failures[0]
        runtime.set_error(
            f"{len(failures)} of {len(results)} clips failed; first clip {first_id}: {first_error}"[:1000]
        )
        if runtime.is_capacity_blocked():
            runtime.set_phase(Phase.BLOCKED)
    return bool(successes)


def load_outage(cfg):
    return read_json(cfg.outage_file, None)


def send_heartbeat_payload(cfg, payload):
    try:
        return request_json(cfg, "POST", "/account/connections/heartbeat",
                            body=payload, timeout=HEARTBEAT_TIMEOUT_SEC)
    except urllib.error.HTTPError as exc:
        host = payload.get("host")
        if exc.code != 400 or not isinstance(host, dict) or "release" not in host:
            raise
        payload["host"] = {k: v for k, v in host.items() if k != "release"}
        return request_json(cfg, "POST", "/account/connections/heartbeat",
                            body=payload, timeout=HEARTBEAT_TIMEOUT_SEC)


def send_heartbeat(cfg, runtime, outage):
    payload = runtime.heartbeat_payload(outage)
    try:
        return request_json(cfg, "POST", "/account/connections/heartbeat",
                            body=payload, timeout=HEARTBEAT_TIMEOUT_SEC)
    except urllib.error.HTTPError as exc:
        host = payload.get("host")
        if exc.code == 400 and "cleanup" in payload:
            # A backend that predates the optional cleanup status field.
            payload.pop("cleanup")
            return send_heartbeat_payload(cfg, payload)
        if exc.code != 400 or not isinstance(host, dict) or "release" not in host:
            raise
        # A rolled-back backend may not know this optional diagnostic field.
        # Retry only without that field; authentication and all other telemetry
        # stay exact, and any second rejection follows normal outage handling.
        payload["host"] = {k: v for k, v in host.items() if k != "release"}
        return request_json(cfg, "POST", "/account/connections/heartbeat",
                            body=payload, timeout=HEARTBEAT_TIMEOUT_SEC)


def heartbeat_loop(cfg, runtime, stop_event):
    outage = load_outage(cfg)
    while not stop_event.is_set():
        try:
            response = send_heartbeat(cfg, runtime, outage)
            cfg.stitch_switches.apply(response)
            runtime.stitch_enabled = cfg.stitch_enabled
            runtime.apply_joined_protocol_response(response)
            if runtime.inventory is not None:
                cleanup_release_quarantine(runtime.inventory, response.get("cleanup_release_generation"))
            runtime.heartbeat_succeeded = True
            if outage:
                outage["recovered_at"] = utc_now()
                response = send_heartbeat(cfg, runtime, outage)
                cfg.stitch_switches.apply(response)
                runtime.stitch_enabled = cfg.stitch_enabled
                runtime.apply_joined_protocol_response(response)
                outage = None
                try:
                    cfg.outage_file.unlink()
                except FileNotFoundError:
                    pass
                log("INFO", "heartbeat recovered")
        except Exception as exc:
            cfg.stitch_switches.apply(None)
            runtime.stitch_enabled = False
            try:
                classification = classify_transport_error(exc).value
                now = utc_now()
                if not outage:
                    outage = {"class": classification, "started_at": now, "failure_count": 0}
                outage["class"] = classification
                outage["failure_count"] = int(outage.get("failure_count", 0)) + 1
                atomic_write(cfg.outage_file, json.dumps(outage).encode("utf-8"))
                log("WARN", "heartbeat failed class=%s count=%d: %s" % (classification, outage["failure_count"], exc))
            except Exception as record_exc:
                # Outage bookkeeping must never kill this thread. If it dies the
                # server's view of the client freezes while the drain loop keeps
                # running, and the NAS is remote and cannot be restarted by hand.
                log("WARN", "heartbeat bookkeeping failed: %s" % record_exc)
        stop_event.wait(HEARTBEAT_INTERVAL_SEC)


class UploadProbeBody:
    """Streams size bytes by repeating one random block; nothing touches disk.

    R2 neither compresses nor deduplicates, so a repeated block measures the
    link exactly like unique data while keeping memory at one block.
    """

    def __init__(self, size, block, deadline):
        self.remaining = size
        self.block = block
        self.deadline = deadline
        self.sent = 0

    def read(self, amount=-1):
        if self.remaining <= 0:
            return b""
        if time.monotonic() > self.deadline:
            raise UploadProbeTimeout("upload probe exceeded %d seconds" % UPLOAD_PROBE_MAX_SEC)
        count = len(self.block) if amount is None or amount < 0 else min(amount, len(self.block))
        count = min(count, self.remaining)
        self.remaining -= count
        self.sent += count
        return self.block if count == len(self.block) else self.block[:count]


def valid_upload_probe_target(target):
    if not isinstance(target, dict):
        raise RuntimeError("invalid upload probe response")
    probe_id = target.get("probe_id")
    size = target.get("size_bytes")
    streams = target.get("streams")
    parts = target.get("parts")
    if type(probe_id) is not int or probe_id <= 0:
        raise RuntimeError("invalid upload probe id")
    if type(size) is not int or not 0 < size <= UPLOAD_PROBE_MAX_BYTES:
        raise RuntimeError("invalid upload probe size")
    if type(streams) is not int or not 1 <= streams <= UPLOAD_PROBE_MAX_STREAMS:
        raise RuntimeError("invalid upload probe streams")
    if not isinstance(parts, list) or len(parts) != streams:
        raise RuntimeError("invalid upload probe parts")
    valid = []
    for part in parts:
        if not isinstance(part, dict):
            raise RuntimeError("invalid upload probe part")
        url = urllib.parse.urlsplit(str(part.get("url", "")))
        part_size = part.get("size_bytes")
        headers = part.get("headers") or {}
        if url.scheme != "https" or not url.hostname or part.get("method") != "PUT":
            raise RuntimeError("upload probe target must be an https PUT")
        if type(part_size) is not int or part_size <= 0 or not isinstance(headers, dict):
            raise RuntimeError("invalid upload probe part")
        valid.append({"url": url, "size_bytes": part_size, "headers": {str(k): str(v) for k, v in headers.items()}})
    if sum(part["size_bytes"] for part in valid) != size:
        raise RuntimeError("upload probe parts do not sum to the probe size")
    return probe_id, valid


def valid_download_probe_parts(target, upload_parts):
    """Optional presigned GETs of the uploaded objects; [] when the API sends none."""
    parts = target.get("download_parts")
    if parts is None:
        return []
    if not isinstance(parts, list) or len(parts) != len(upload_parts):
        raise RuntimeError("invalid download probe parts")
    valid = []
    for part, upload in zip(parts, upload_parts):
        if not isinstance(part, dict):
            raise RuntimeError("invalid download probe part")
        url = urllib.parse.urlsplit(str(part.get("url", "")))
        if url.scheme != "https" or not url.hostname or part.get("method") != "GET":
            raise RuntimeError("download probe target must be an https GET")
        if part.get("size_bytes") != upload["size_bytes"]:
            raise RuntimeError("download probe part size differs from its upload")
        valid.append({"url": url, "size_bytes": upload["size_bytes"]})
    return valid


def download_probe_part(part, deadline, progress):
    """Read one probe object and discard it, counting bytes into progress[0].

    Every blocking call gets the remaining overall deadline as its socket
    timeout, so a stalled GET ends near the probe's time cap."""
    url = part["url"]

    def remaining():
        left = deadline - time.monotonic()
        if left <= 0:
            raise RuntimeError("download probe exceeded its time cap")
        return min(UPLOAD_PROBE_SOCKET_TIMEOUT_SEC, left)
    connection = http.client.HTTPSConnection(url.netloc, timeout=remaining(), blocksize=UPLOAD_PROBE_BLOCK_BYTES)
    try:
        connection.request("GET", url.path + ("?" + url.query if url.query else ""), headers={"User-Agent": USER_AGENT})
        if connection.sock is not None:
            connection.sock.settimeout(remaining())
        response = connection.getresponse()
        remember_response_secrets(response)
        if response.status != 200:
            raise RuntimeError("download probe GET returned HTTP %d" % response.status)
        while progress[0] < part["size_bytes"]:
            if connection.sock is not None:
                connection.sock.settimeout(remaining())
            else:
                remaining()
            block = response.read(min(UPLOAD_PROBE_BLOCK_BYTES, part["size_bytes"] - progress[0]))
            if not block:
                break
            progress[0] += len(block)
    finally:
        connection.close()


def run_download_probe(parts):
    """Download all parts concurrently; returns (bytes, duration_ms, error)."""
    started = time.monotonic()
    deadline = started + UPLOAD_PROBE_MAX_SEC
    progress, errors = [[0] for _ in parts], []

    def fetch(index, part):
        download_probe_part(part, deadline, progress[index])
    with concurrent.futures.ThreadPoolExecutor(max_workers=len(parts)) as pool:
        futures = [pool.submit(fetch, i, part) for i, part in enumerate(parts)]
        for future in futures:
            try:
                future.result()
            except Exception as exc:
                errors.append(exc)
    duration_ms = max(1, round((time.monotonic() - started) * 1000))
    size = sum(part["size_bytes"] for part in parts)
    total = min(size, sum(p[0] for p in progress))
    error = ""
    if errors:
        error = ("%s: %s" % (type(errors[0]).__name__, errors[0]))[:500]
    elif total != size:
        error = "download probe received %d of %d bytes" % (total, size)
    return total, duration_ms, error


def upload_probe_part(part, body):
    url = part["url"]
    connection = http.client.HTTPSConnection(
        url.netloc, timeout=UPLOAD_PROBE_SOCKET_TIMEOUT_SEC, blocksize=UPLOAD_PROBE_BLOCK_BYTES,
    )
    try:
        headers = dict(part["headers"])
        headers["Content-Length"] = str(part["size_bytes"])
        headers["User-Agent"] = USER_AGENT
        connection.request("PUT", url.path + ("?" + url.query if url.query else ""), body=body, headers=headers)
        response = connection.getresponse()
        remember_response_secrets(response)
        response.read(64 * 1024)
        if not 200 <= response.status < 300:
            raise RuntimeError("upload probe PUT returned HTTP %d" % response.status)
    finally:
        connection.close()


def run_upload_probe(runtime, target):
    """Upload all parts concurrently and measure wall time end to end."""
    probe_id, parts = valid_upload_probe_target(target)
    download_parts = valid_download_probe_parts(target, parts)
    block = os.urandom(UPLOAD_PROBE_BLOCK_BYTES)
    phase_start, pulled_start, joined_start = runtime.upload_probe_activity()
    started_at = utc_now_precise()
    started = time.monotonic()
    bodies = [UploadProbeBody(part["size_bytes"], block, started + UPLOAD_PROBE_MAX_SEC) for part in parts]
    errors = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=len(parts)) as pool:
        futures = [pool.submit(upload_probe_part, part, body) for part, body in zip(parts, bodies)]
        for future in futures:
            try:
                future.result()
            except Exception as exc:
                errors.append(exc)
    duration_ms = max(1, round((time.monotonic() - started) * 1000))
    phase_end, pulled_end, joined_end = runtime.upload_probe_activity()
    size = sum(part["size_bytes"] for part in parts)
    uploaded = min(size, sum(body.sent for body in bodies))
    error = ""
    if errors:
        error = ("%s: %s" % (type(errors[0]).__name__, errors[0]))[:500]
    elif uploaded != size:
        error = "upload probe sent %d of %d bytes" % (uploaded, size)
    result = {
        "bytes_uploaded": uploaded,
        "duration_ms": duration_ms,
        "started_at": started_at,
        "error": error,
        "client_version": CLIENT_VERSION,
        "client_phase_start": phase_start,
        "client_phase_end": phase_end,
        "joined_transfer_active": bool(joined_start or joined_end),
        "bytes_pulled_during": max(0, pulled_end - pulled_start),
    }
    # Measure the downlink on the objects just uploaded, before the report lets
    # the API delete them. Only a complete upload leaves complete objects.
    if download_parts and not error:
        downloaded, download_ms, download_error = run_download_probe(download_parts)
        result["bytes_downloaded"] = downloaded
        result["download_duration_ms"] = download_ms
        if download_error:
            result["download_error"] = download_error
    return probe_id, result


def upload_probe_wait(seconds, rng=random):
    try:
        seconds = int(seconds)
    except (TypeError, ValueError):
        seconds = UPLOAD_PROBE_ERROR_WAIT_SEC
    seconds = min(max(seconds, UPLOAD_PROBE_MIN_WAIT_SEC), UPLOAD_PROBE_MAX_WAIT_SEC)
    return seconds * rng.uniform(1 - UPLOAD_PROBE_JITTER, 1 + UPLOAD_PROBE_JITTER)


def upload_probe_once(cfg, runtime):
    """Ask the API whether a probe is due, run it, report it. Returns the wait."""
    target = request_json(
        cfg, "POST", "/account/connections/upload-probe",
        body={"client_version": CLIENT_VERSION}, timeout=HEARTBEAT_TIMEOUT_SEC,
    )
    if not isinstance(target, dict):
        raise RuntimeError("invalid upload probe response")
    retry_after = target.get("retry_after_sec", UPLOAD_PROBE_ERROR_WAIT_SEC)
    if target.get("enabled") is not True or target.get("due") is not True:
        return retry_after
    probe_id, result = run_upload_probe(runtime, target)
    report_upload_probe(cfg, probe_id, result)
    if "bytes_downloaded" in result:
        download_seconds = result["download_duration_ms"] / 1000.0
        log(
            "INFO" if not result.get("download_error") else "WARN",
            "download probe id=%d bytes=%d seconds=%.1f mbps=%.1f%s" % (
                probe_id, result["bytes_downloaded"], download_seconds,
                result["bytes_downloaded"] * 8 / download_seconds / 1e6,
                (" error=%s" % result["download_error"]) if result.get("download_error") else "",
            ),
        )
    seconds = result["duration_ms"] / 1000.0
    log(
        "INFO" if not result["error"] else "WARN",
        "upload probe id=%d bytes=%d seconds=%.1f mbps=%.1f streams=%d%s" % (
            probe_id, result["bytes_uploaded"], seconds, result["bytes_uploaded"] * 8 / seconds / 1e6,
            len(target["parts"]), (" error=%s" % result["error"]) if result["error"] else "",
        ),
    )
    return retry_after


def report_upload_probe(cfg, probe_id, result, sleep=time.sleep):
    """Report once, retrying transient failures; 409 means already recorded."""
    for attempt in range(1, UPLOAD_PROBE_REPORT_ATTEMPTS + 1):
        try:
            request_json(
                cfg, "POST", "/account/connections/upload-probe/%d/result" % probe_id,
                body=result, timeout=HEARTBEAT_TIMEOUT_SEC,
            )
            return
        except urllib.error.HTTPError as exc:
            if exc.code == 409:
                return
            if not transient_error(exc) or attempt == UPLOAD_PROBE_REPORT_ATTEMPTS:
                raise
        except Exception as exc:
            if not transient_error(exc) or attempt == UPLOAD_PROBE_REPORT_ATTEMPTS:
                raise
        sleep(UPLOAD_PROBE_REPORT_BACKOFF_SEC * attempt)


def upload_probe_loop(cfg, runtime, stop_event, rng=random):
    """Background upload speed probe; never raises and never blocks updates."""
    wait = rng.uniform(*UPLOAD_PROBE_STARTUP_DELAY_SEC)
    while not stop_event.wait(wait):
        try:
            wait = upload_probe_wait(upload_probe_once(cfg, runtime), rng)
        except Exception as exc:
            log("WARN", "upload probe deferred: %s" % exc)
            wait = upload_probe_wait(UPLOAD_PROBE_ERROR_WAIT_SEC, rng)


# ---------------------------------------------------------------------------
# NAS host facts and one-shot media benchmark
#
# Measures what NAS-side collation would cost on this NAS. The server hands out
# one real hour of clips already on the NAS (exact path, size, sha256). The
# benchmark reads them read-only, remuxes them into one temp file under
# /state, checks a per-stream packet hash chain, decodes around every seam and
# then the whole output, records wall and CPU seconds, deletes its temp output
# and reports. It never writes to, renames or deletes anything under /clips.
# ---------------------------------------------------------------------------

BENCHMARK_TOOL_VERSION = "N-126239-g88ae625e69"
# The same pinned FFmpeg the cloud joined pipeline uses (batch media_tool
# identity), mirrored as a repository release. Only x86_64 is published; other
# architectures report unsupported_arch with their host facts.
BENCHMARK_TOOLS = {
    "x86_64": {
        "url": "https://github.com/daydemir/stoarama/releases/download/joined-media-tools-ffmpeg-N-126239-g88ae625e69/ffmpeg-N-126239-g88ae625e69-linux64-gpl.tar.xz",
        "archive_sha256": "b7d2cf59ccb19372f6ee0198a938ccc1b6654d8704d056f8c72b82fda30af34f",
        "ffmpeg_sha256": "eab722b24d599876819f89f503cc142b39a096a971d7d7913a0282b0484b9d5e",
        "ffprobe_sha256": "95cda0f6de6e2d0c48cc2afe24e8ef9bcb8b4ffc5897af77158b1a59b303a97a",
    },
}
BENCHMARK_MACHINE_ALIASES = {"amd64": "x86_64", "x86-64": "x86_64"}
BENCHMARK_TOOL_MAX_ARCHIVE_BYTES = 256 * 1024 * 1024
BENCHMARK_TOOL_MAX_BINARY_BYTES = 512 * 1024 * 1024
BENCHMARK_TOOL_INSTALL_SEC = 15 * 60
BENCHMARK_MAX_DEADLINE_SEC = 30 * 60
BENCHMARK_THREADS = 2
BENCHMARK_NICE = 15
BENCHMARK_SEAM_HALF_WINDOW_SEC = 2.0
BENCHMARK_MAX_CLIPS = 200
BENCHMARK_STATE_HEADROOM_BYTES = 2 * 1024 * 1024 * 1024
BENCHMARK_STARTUP_DELAY_SEC = (60, 300)
BENCHMARK_MIN_WAIT_SEC = 300
BENCHMARK_MAX_WAIT_SEC = 24 * 60 * 60
BENCHMARK_ERROR_WAIT_SEC = 60 * 60
BENCHMARK_REPORT_ATTEMPTS = 3
BENCHMARK_REPORT_BACKOFF_SEC = 10
BENCHMARK_ROOT = "benchmark"
HOST_TOKEN = re.compile(r"[A-Za-z0-9_.+-]{1,64}\Z")
# Set while a benchmark runs so a staged self-update waits for it (bounded by
# the benchmark deadline) instead of orphaning niced FFmpeg children.
BENCHMARK_ACTIVE = threading.Event()


class BenchmarkError(RuntimeError):
    pass


class BenchmarkDeadline(BenchmarkError):
    pass


class BenchmarkUnsupported(BenchmarkError):
    pass


def _read_text(path, limit=64 * 1024):
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as source:
            return source.read(limit)
    except OSError:
        return None


def _host_token(value):
    value = str(value or "").strip()
    return value if HOST_TOKEN.match(value) else ""


def _host_text(value):
    cleaned = "".join(ch for ch in str(value or "") if 32 <= ord(ch) != 127).strip()
    # The server bounds these strings in bytes; never split a UTF-8 sequence.
    return cleaned.encode("utf-8")[:256].decode("utf-8", "ignore").strip()


def cgroup_cpu_limit(root="/sys/fs/cgroup"):
    """CPUs granted by the container cgroup, or None when unlimited/unknown."""
    raw = _read_text(os.path.join(root, "cpu.max"))
    if raw is not None:
        parts = raw.split()
        if len(parts) == 2 and parts[0] != "max":
            try:
                quota, period = int(parts[0]), int(parts[1])
                if quota > 0 and period > 0:
                    return _cpu_ratio(quota, period)
            except ValueError:
                return None
        return None
    quota = _read_text(os.path.join(root, "cpu", "cpu.cfs_quota_us"))
    period = _read_text(os.path.join(root, "cpu", "cpu.cfs_period_us"))
    try:
        quota, period = int((quota or "").strip()), int((period or "").strip())
    except ValueError:
        return None
    return _cpu_ratio(quota, period) if quota > 0 and period > 0 else None


def _cpu_ratio(quota, period):
    # The server rejects a non-positive limit; a sub-0.0005 CPU quota rounds to 0.
    ratio = round(quota / period, 3)
    return ratio if ratio > 0 else None


def cgroup_memory_limit(root="/sys/fs/cgroup"):
    """Bytes granted by the container cgroup, or None when unlimited/unknown."""
    for relative in ("memory.max", os.path.join("memory", "memory.limit_in_bytes")):
        raw = _read_text(os.path.join(root, relative))
        if raw is None:
            continue
        raw = raw.strip()
        if raw == "max":
            return None
        try:
            value = int(raw)
        except ValueError:
            return None
        # cgroup v1 reports "unlimited" as a page-rounded near-2^63 value.
        return value if 0 < value < (1 << 60) else None
    return None


def meminfo_bytes(text):
    values = {}
    for line in (text or "").splitlines():
        name, _, rest = line.partition(":")
        fields = rest.split()
        if name in ("MemTotal", "MemAvailable") and fields:
            try:
                values[name] = int(fields[0]) * 1024
            except ValueError:
                pass
    return values.get("MemTotal", 0), values.get("MemAvailable", 0)


def cpu_model(text):
    for line in (text or "").splitlines():
        name, _, value = line.partition(":")
        if name.strip() in ("model name", "Hardware", "Model") and value.strip():
            return _host_text(value)
    return ""


def state_exec_allowed(state_dir):
    """True when a binary on the state volume can execute (not noexec)."""
    tools = Path(state_dir) / "tools"
    probe = tools / (".exec-probe-%d" % os.getpid())
    try:
        tools.mkdir(parents=True, exist_ok=True)
        with open(probe, "w", encoding="ascii") as output:
            output.write("#!/bin/sh\nexit 0\n")
        os.chmod(probe, 0o700)
        completed = subprocess.run([str(probe)], stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                                   stderr=subprocess.DEVNULL, timeout=10, check=False)
        return completed.returncode == 0
    except PermissionError:
        return False
    except (OSError, subprocess.SubprocessError):
        return None
    finally:
        try:
            probe.unlink()
        except OSError:
            pass


class HostFacts:
    """Static facts are gathered once; memory and load refresh per call."""

    def __init__(self, state_dir):
        self.state_dir = state_dir
        self.static = None
        self.lock = threading.Lock()

    def _gather_static(self):
        import platform
        try:
            affinity = len(os.sched_getaffinity(0))
        except (AttributeError, OSError):
            affinity = 0
        return {
            "machine": _host_token(platform.machine()),
            "system": _host_token(platform.system()),
            "kernel_release": _host_text(platform.release()),
            "python_version": _host_token(platform.python_version()),
            "cpu_model": cpu_model(_read_text("/proc/cpuinfo", 256 * 1024)),
            "cpu_count": max(0, int(os.cpu_count() or 0)),
            "affinity_cpus": affinity,
            "cgroup_cpu_limit": cgroup_cpu_limit(),
            "cgroup_memory_limit_bytes": cgroup_memory_limit(),
            "state_exec_allowed": state_exec_allowed(self.state_dir),
        }

    def __call__(self):
        with self.lock:
            if self.static is None:
                self.static = self._gather_static()
            facts = dict(self.static)
        total, available = meminfo_bytes(_read_text("/proc/meminfo"))
        facts["mem_total_bytes"] = total
        facts["mem_available_bytes"] = available
        try:
            facts["load1"] = round(max(0.0, os.getloadavg()[0]), 2)
        except (AttributeError, OSError):
            facts["load1"] = None
        return facts


def benchmark_tool_arch(machine):
    machine = str(machine or "").strip().lower()
    return BENCHMARK_MACHINE_ALIASES.get(machine, machine)


def _verified_binary(path, expected_sha):
    try:
        size, digest = sha256_file(path)
    except OSError:
        return False
    return size > 0 and digest == expected_sha



_BENCHMARK_TOOL_INSTALL_LOCK = threading.Lock()


def _check_benchmark_tool_budget(deadline, cancel):
    if cancel is not None and cancel.is_set():
        raise BenchmarkDeadline("tool setup cancelled")
    if time.monotonic() >= deadline:
        raise BenchmarkDeadline("tool setup exceeded its time cap")


def ensure_benchmark_tools(state_dir, machine, deadline, opener=None, cancel=None):
    """Serialize the shared pinned cache across benchmark and witness lanes."""
    _check_benchmark_tool_budget(deadline, cancel)
    acquired = False
    try:
        while not acquired:
            _check_benchmark_tool_budget(deadline, cancel)
            acquired = _BENCHMARK_TOOL_INSTALL_LOCK.acquire(timeout=min(.1, max(0, deadline - time.monotonic())))
        return _ensure_benchmark_tools_locked(state_dir, machine, deadline, opener=opener, cancel=cancel)
    finally:
        if acquired:
            _BENCHMARK_TOOL_INSTALL_LOCK.release()


def _ensure_benchmark_tools_locked(state_dir, machine, deadline, opener=None, cancel=None):
    """Install the pinned FFmpeg/ffprobe under /state/tools; verify every byte."""
    _check_benchmark_tool_budget(deadline, cancel)
    arch = benchmark_tool_arch(machine)
    spec = BENCHMARK_TOOLS.get(arch)
    if spec is None:
        raise BenchmarkUnsupported("no pinned FFmpeg build for architecture %r" % (machine or "unknown"))
    tools_dir = Path(state_dir) / "tools" / ("ffmpeg-%s-%s" % (BENCHMARK_TOOL_VERSION, arch))
    binaries = {"ffmpeg": spec["ffmpeg_sha256"], "ffprobe": spec["ffprobe_sha256"]}
    info = {"version": BENCHMARK_TOOL_VERSION, "arch": arch,
            "ffmpeg_sha256": spec["ffmpeg_sha256"], "ffprobe_sha256": spec["ffprobe_sha256"]}
    if all(_verified_binary(tools_dir / name, sha) for name, sha in binaries.items()):
        _check_benchmark_tool_budget(deadline, cancel)
        info.update({"source": "cached", "ffmpeg": str(tools_dir / "ffmpeg"), "ffprobe": str(tools_dir / "ffprobe")})
        return info
    import tarfile
    tools_dir.mkdir(parents=True, exist_ok=True)
    archive = tools_dir / (".archive-%d.tar.xz" % os.getpid())
    partials = []
    try:
        request = urllib.request.Request(spec["url"], headers={"User-Agent": USER_AGENT})
        digest = hashlib.sha256()
        size = 0
        with (opener or urllib.request.urlopen)(request, timeout=min(60, max(.1, deadline-time.monotonic()))) as response, open(archive, "wb") as output:
            remember_response_secrets(response)
            while True:
                _check_benchmark_tool_budget(deadline, cancel)
                chunk = response.read(1024 * 1024)
                if not chunk:
                    break
                size += len(chunk)
                if size > BENCHMARK_TOOL_MAX_ARCHIVE_BYTES:
                    raise BenchmarkError("tool archive is larger than expected")
                digest.update(chunk)
                output.write(chunk)
        if digest.hexdigest() != spec["archive_sha256"]:
            raise BenchmarkError("tool archive sha256 mismatch")
        found = set()
        with tarfile.open(archive, "r:xz") as bundle:
            for member in bundle:
                _check_benchmark_tool_budget(deadline, cancel)
                parts = member.name.split("/")
                name = parts[-1]
                if name not in binaries or name in found or len(parts) < 2 or parts[-2] != "bin" or not member.isfile():
                    continue
                if member.size <= 0 or member.size > BENCHMARK_TOOL_MAX_BINARY_BYTES:
                    raise BenchmarkError("tool binary has an unexpected size")
                partial = tools_dir / (".%s.partial-%d" % (name, os.getpid()))
                partials.append(partial)
                binary_digest = hashlib.sha256()
                source = bundle.extractfile(member)
                with source, open(partial, "wb") as output:
                    while True:
                        _check_benchmark_tool_budget(deadline, cancel)
                        chunk = source.read(1024 * 1024)
                        if not chunk:
                            break
                        binary_digest.update(chunk)
                        output.write(chunk)
                    output.flush()
                    os.fsync(output.fileno())
                if binary_digest.hexdigest() != binaries[name]:
                    raise BenchmarkError("%s sha256 mismatch" % name)
                _check_benchmark_tool_budget(deadline, cancel)
                os.chmod(partial, 0o755)
                os.replace(partial, tools_dir / name)
                found.add(name)
                if found == set(binaries):
                    break
        if found != set(binaries):
            raise BenchmarkError("tool archive lacks ffmpeg/ffprobe")
        fsync_dir(tools_dir)
    finally:
        for path in [archive] + partials:
            try:
                path.unlink()
            except OSError:
                pass
    info.update({"source": "downloaded", "archive_bytes": size,
                 "ffmpeg": str(tools_dir / "ffmpeg"), "ffprobe": str(tools_dir / "ffprobe")})
    return info


def _niced(command):
    import shutil
    prefix = []
    if shutil.which("nice"):
        prefix += ["nice", "-n", str(BENCHMARK_NICE)]
    if shutil.which("ionice"):
        prefix += ["ionice", "-t", "-c", "2", "-n", "7"]
    return prefix + list(command)


def run_measured(command, deadline, stop_event, stdout_path=None, niced=True):
    """Run one child to completion; return wall, CPU and peak RSS from wait4.

    The child gets its own process group and is killed at the deadline or on
    shutdown, so no FFmpeg descendant outlives the benchmark.
    """
    remaining = deadline - time.monotonic()
    if remaining <= 0:
        raise BenchmarkDeadline("benchmark deadline reached")
    stderr_file = tempfile.TemporaryFile()
    stdout_file = open(stdout_path, "wb") if stdout_path else subprocess.DEVNULL
    started = time.monotonic()
    try:
        process = subprocess.Popen(_niced(command) if niced else list(command), stdin=subprocess.DEVNULL,
                                   stdout=stdout_file, stderr=stderr_file, start_new_session=True)
    except BaseException:
        stderr_file.close()
        if stdout_path:
            stdout_file.close()
        raise
    killed = {"reason": ""}
    done = threading.Event()

    def watchdog():
        while not done.wait(0.5):
            reason = "deadline" if time.monotonic() >= deadline else ("shutdown" if stop_event.is_set() else "")
            if reason:
                killed["reason"] = reason
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except OSError:
                    pass
                return

    guard = threading.Thread(target=watchdog, name="benchmark-watchdog", daemon=True)
    guard.start()
    try:
        _, status, usage = os.wait4(process.pid, 0)
        process.returncode = os.waitstatus_to_exitcode(status)
    finally:
        done.set()
        guard.join(timeout=2)
        if stdout_path:
            stdout_file.close()
    stderr_file.seek(0)
    stderr_tail = stderr_file.read()[-400:].decode("utf-8", "replace").strip()
    stderr_file.close()
    wall = time.monotonic() - started
    measured = {
        "wall_s": wall, "cpu_s": usage.ru_utime + usage.ru_stime,
        "max_rss_kb": int(usage.ru_maxrss if sys.platform != "darwin" else usage.ru_maxrss // 1024),
        "returncode": process.returncode, "stderr": stderr_tail,
    }
    if killed["reason"] == "deadline":
        raise BenchmarkDeadline("benchmark deadline reached")
    if killed["reason"] == "shutdown":
        raise BenchmarkError("client shutting down")
    return measured


class StageMeter:
    """Accumulates children (and optionally this thread) into one stage."""

    def __init__(self):
        self.wall = 0.0
        self.cpu = 0.0
        self.rss = 0
        self.started = time.monotonic()
        self.thread_cpu = time.thread_time()

    def add(self, measured):
        self.cpu += measured["cpu_s"]
        self.rss = max(self.rss, measured["max_rss_kb"])

    def finish(self, include_thread=False, **extra):
        stage = {"wall_s": round(time.monotonic() - self.started, 3),
                 "cpu_s": round(self.cpu + ((time.thread_time() - self.thread_cpu) if include_thread else 0.0), 3),
                 "max_rss_kb": self.rss}
        stage.update(extra)
        return stage


def parse_framehash(path, digests=None, counts=None, check_timing=False):
    """Fold framehash lines into a per-stream sha256 chain of (size, hash).

    Timestamps are excluded from the chain (concat rebases them); with
    check_timing, output DTS must be strictly increasing per stream.
    """
    digests = {} if digests is None else digests
    counts = {} if counts is None else counts
    last_dts, violations = {}, 0
    with open(path, "r", encoding="ascii", errors="replace") as source:
        for line in source:
            if not line or line.startswith("#"):
                continue
            fields = [field.strip() for field in line.split(",")]
            if len(fields) < 6:
                continue
            stream, dts, size, frame_hash = fields[0], fields[1], fields[4], fields[5]
            digests.setdefault(stream, hashlib.sha256()).update(("%s:%s\n" % (size, frame_hash)).encode("ascii"))
            counts[stream] = counts.get(stream, 0) + 1
            if check_timing:
                try:
                    value = int(dts)
                except ValueError:
                    violations += 1
                    continue
                if stream in last_dts and value <= last_dts[stream]:
                    violations += 1
                last_dts[stream] = value
    return digests, counts, violations


def benchmark_concat_manifest(paths, durations):
    lines = ["ffconcat version 1.0\n"]
    for path, duration in zip(paths, durations):
        lines.append(concat_manifest_line(path))
        if duration is not None and duration > 0:
            lines.append("duration %.6f\n" % duration)
    return "".join(lines)


def clean_benchmark_root(state_dir):
    """Remove leftovers of this client's own benchmark temp dirs (flat, files only)."""
    root = Path(state_dir) / BENCHMARK_ROOT
    if not root.is_dir() or root.is_symlink():
        return True
    clean = True
    for entry in os.scandir(root):
        if not entry.is_dir(follow_symlinks=False):
            continue
        for child in os.scandir(entry.path):
            if child.is_file(follow_symlinks=False) or child.is_symlink():
                try:
                    os.unlink(child.path)
                except OSError:
                    clean = False
            else:
                clean = False
        try:
            os.rmdir(entry.path)
        except OSError:
            clean = False
    return clean


